# file: frontend.cl.jac
"""studio - client entry. Auth gate + app shell.

`app` is the one `def:pub` client surface (the served UI). Behavior depends on
how the server was started:

- **Local desktop** (start.sh sets JAC_LOCAL_USER=1 → `local_mode()` True): the
  gate calls `local_session()` over the native bridge, which registers + logs in
  the implicit local user IN-PROCESS and returns a JWT. The desktop webview host
  can't reach `/user/register` + `/user/login` over HTTP (the loopback broker
  only proxies those in CEF mode), so the in-process `local_session()` endpoint
  does the /user/* dance server-side and hands back a token. The client
  `jacSetToken()`s it, after which every authenticated `def:priv` call succeeds
  and <AppShell/> mounts — no login screen. `touchSession()` re-mints on a timer
  so a short JWT TTL cannot strand the user mid-session.
- **Production** (start_prod.sh leaves the env unset → `local_mode()` False):
  logged-out visitors get the <Login/> gate, exactly as before. `session_alive`
  pings detect expiry; `jac-auth-expired` bounces back to <Login/>.

Every var holding an `await` result is pre-declared (compiled-JS let-scoping
would otherwise leave post-await checks with a ReferenceError)."""

import from "@jac/runtime" { jacIsLoggedIn }
import from react { useEffect }
sv import from .auth { local_mode }
import from .auth_session { authEventName, refreshLocalSession, touchSession }
import from .components.AppShell { AppShell }
import from .components.Login { Login }
import from .components.jms.Landing { Landing }
import from .components.jms.JmsShell { JmsShell }

def:pub app -> JsxElement {
    has authTick: int = 0,
        checking: bool = True,
        loggedIn: bool = False,
        surface: str = "";

    """Read the current surface from the URL hash (#jms / #experiments / else "")."""
    def _hashSurface() -> str {
        try {
            w: any = window;
            s: str = str(w.location.hash).replace("#", "");
            if s == "jms" or s == "experiments" { return s; }
        } except Exception { }
        return "";
    }

    """Navigate to a surface AND push a browser history entry so the OS/browser
    Back button returns to the previous surface (popstate handler below restores
    it). Hash-based so a refresh/deeplink lands on the same surface."""
    def goSurface(s: str) -> None {
        surface = s;
        try {
            w: any = window;
            w.history.pushState({"surface": s}, "", ("#" + s) if s else "#");
        } except Exception { }
    }

    """On mount: read local_mode() once. Local desktop mints an in-process
    session token (see module docstring); prod falls through to <Login/> when
    no session is present. Retries briefly — the native host can 401 pub
    endpoints for a beat while the in-process server finishes booting."""
    async can with entry {
        # apply persisted light/dark mode before first paint
        try {
            dc: any = document;
            wm: any = window;
            md: str = "dark";
            sv2: any = wm.localStorage.getItem("jacml.mode");
            if sv2 { md = str(sv2); }
            elif wm.matchMedia and wm.matchMedia("(prefers-color-scheme: light)").matches { md = "light"; }
            if md == "dark" { dc.documentElement.classList.add("dark"); }
            else { dc.documentElement.classList.remove("dark"); }
        } except Exception { }
        lm: bool = False;
        ok: bool = False;
        attempt: int = 0;
        while attempt < 10 {
            attempt = attempt + 1;
            try {
                lm = await local_mode();
            } except Exception {
                lm = False;
            }
            if lm {
                try {
                    ok = await refreshLocalSession();
                } except Exception {
                    ok = False;
                }
                if ok {
                    break;
                }
            } elif jacIsLoggedIn() {
                ok = True;
                break;
            }
        }
        loggedIn = ok or jacIsLoggedIn();
        checking = False;
    }

    useEffect(lambda {
        if not (loggedIn or jacIsLoggedIn()) {
            return lambda { };
        }
        touchSession();
        iv: any = None;
        iv = setInterval(lambda { touchSession(); }, 240000);
        handler = lambda(_e: any) {
            loggedIn = jacIsLoggedIn();
            authTick = authTick + 1;
        };
        w: any = window;
        evtName = authEventName();
        w.addEventListener(evtName, handler);
        return lambda {
            if iv is not None {
                clearInterval(float(str(iv)));
            }
            w.removeEventListener(evtName, handler);
        };
    }, [authTick, loggedIn]);

    # Browser Back/Forward ↔ surface sync. On mount, adopt the URL hash (so a
    # refresh/deeplink lands on the right surface); listen for popstate (Back)
    # and restore the surface from the hash.
    useEffect(lambda {
        init = _hashSurface();
        if init { surface = init; }
        wp: any = window;
        onPop = lambda(_e: any) { surface = _hashSurface(); };
        wp.addEventListener("popstate", onPop);
        # hashchange too: the assistant widget navigates by setting location.hash
        # directly (no synthetic popstate), which fires only hashchange natively.
        wp.addEventListener("hashchange", onPop);
        return lambda {
            wp.removeEventListener("popstate", onPop);
            wp.removeEventListener("hashchange", onPop);
        };
    }, []);

    # Still resolving local_mode()/local_session() — hold a blank frame so we
    # never flash the login screen (which local users should never see).
    if checking {
        return <div className="h-screen bg-background" />;
    }
    # Valid session (local auto-login OR prod login) → surface router:
    # "" = hub landing, "jms" = new product shell, "experiments" = the existing
    # AppShell — its WorkspaceBar's "‹ EXPERIMENTS" button calls onHub directly,
    # so no separate overlay button is needed here anymore.
    if loggedIn or jacIsLoggedIn() {
        if surface == "jms" {
            return <JmsShell
                onHub={lambda { goSurface(""); }}
            />;
        }
        if surface == "experiments" {
            return <AppShell onHub={lambda { goSurface(""); }} />;
        }
        return <Landing
            onPick={lambda(s: str) { goSurface(s); }}
        />;
    }
    # Production gate for logged-out visitors (or expired session).
    return <Login
        onDone={lambda {
            loggedIn = True;
            authTick = authTick + 1;
        }}
    />;
}

# file: gallery.sv.jac
"""studio - repo figure galleries. The experiments already render their graphs
to disk (matplotlib pngs under results/); the studio serves those files
verbatim as base64 data-URIs instead of re-deriving charts. Read-only,
allowlisted to the known artifact roots, capped per request."""

import base64;
import models;
import from pathlib { Path }

glob GALLERY_ROOTS: list[str] = ["model-experiments/01-sft-dpo/results", "model-experiments/02-rl-grpo", "model-experiments/03-cpt-only/results"];
glob IMG_EXTS: list[str] = [".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg"];
glob MAX_IMAGES: int = 48;
glob MAX_BYTES: int = 4_000_000;
# Total raw bytes one gallery_images call may encode. Without this the per-file
# cap alone allows 48 x 4MB = ~192MB raw (~256MB base64) in a single response.
glob MAX_TOTAL_BYTES: int = 24_000_000;

def _is_img(p: Path) -> bool {
    return p.suffix.lower() in IMG_EXTS;
}

def _mime(p: Path) -> str {
    s = p.suffix.lower();
    if s == ".svg" { return "image/svg+xml"; }
    if s == ".jpg" or s == ".jpeg" { return "image/jpeg"; }
    if s == ".webp" { return "image/webp"; }
    if s == ".gif" { return "image/gif"; }
    return "image/png";
}

"""True iff *rel* is a clean relative path inside one of GALLERY_ROOTS."""
def _allowed(rel: str) -> bool {
    if not rel or rel.startswith("/") { return False; }
    for seg in rel.split("/") {
        if seg == ".." or seg == "" { return False; }
    }
    for rt in GALLERY_ROOTS {
        r = str(rt);
        if rel == r or rel.startswith(r + "/") { return True; }
    }
    return False;
}

"""Every dir under the artifact roots that directly contains images:
[{dir, count}], sorted by path. Authenticated (was def:pub — an unauthenticated
enumeration of every experiment artifact on the box)."""
def list_galleries() -> list[dict] {
    base = models.data_root();
    out: list = [];
    for rt in GALLERY_ROOTS {
        rp = base / str(rt);
        if not rp.is_dir() { continue; }
        dirs: dict = {};
        for f in rp.rglob("*") {
            if f.is_file() and _is_img(f) {
                d = str(f.parent.relative_to(base));
                cur = int(str(dirs.get(d, 0)));
                dirs[d] = cur + 1;
            }
        }
        names: list = list(dirs.keys());
        names.sort();
        for d in names {
            out.append({"dir": d, "count": dirs[d]});
        }
    }
    return out;
}

"""All images in *rel_dir* (allowlisted), name-sorted, as data-URI payloads:
[{name, mime, b64}]. Oversized files are skipped with a stub entry, and once the
per-request MAX_TOTAL_BYTES budget is spent the remaining files come back as
stub entries too (never silently dropped). Authenticated (was def:pub — an
unauthenticated download of every artifact image on the box)."""
def gallery_images(rel_dir: str) -> list[dict] {
    if not _allowed(rel_dir) { return []; }
    d = models.data_root() / rel_dir;
    if not d.is_dir() { return []; }
    out: list = [];
    files: list = [];
    for f in d.iterdir() {
        if f.is_file() and _is_img(f) { files.append(f); }
    }
    files.sort(key=lambda (p: Path) -> str { return p.name; });
    n = 0;
    spent = 0;
    for f in files {
        if n >= MAX_IMAGES { break; }
        n += 1;
        try {
            size = int(str(f.stat().st_size));
            if size > MAX_BYTES {
                mb = int(size / 1000000);
                out.append({"name": f.name, "mime": "", "b64": "", "note": f"skipped ({mb}MB)"});
                continue;
            }
            if spent + size > MAX_TOTAL_BYTES {
                out.append({"name": f.name, "mime": "", "b64": "", "note": "skipped (response size budget)"});
                continue;
            }
            spent += size;
            raw = f.read_bytes();
            b64 = str(base64.b64encode(raw), "ascii");
            out.append({"name": f.name, "mime": _mime(f), "b64": b64, "note": ""});
        } except Exception {
            out.append({"name": f.name, "mime": "", "b64": "", "note": "unreadable"});
        }
    }
    return out;
}

