def _is_transit(key: str) -> bool {
    return key in ["DTW", "FNT", "LAN"] or key.startswith("Amtrak ");
}

def _is_landmark(key: str) -> bool {
    return key in LANDMARKS;
}

# A realistic departure for this kind of trip, spread in 5-minute steps:
#   home -> work 7-9 AM, work -> home 4-6 PM, home <-> home 6 AM-11 PM,
#   landmarks 9 AM-10 PM, airports/stations any time, moves 7-11 AM,
#   getaways 7 AM-noon, driving tests 8 AM-3 PM.
def _time_for(mode: str, origin: str, dest: str, k: int, i: int, n: int = 1) -> str {
    window = [360, 1380];
    if mode == "ride" {
        window = [960, 1080] if origin in WORK else [420, 540];
    } elif _is_transit(origin) or _is_transit(dest) {
        window = [270, 1410];
    } elif dest.startswith("Test ") {
        window = [480, 900];
    } elif dest in GETAWAYS {
        window = [420, 720];
    } elif mode == "rental" {
        window = [420, 660];
    } elif origin in WORK or dest in WORK or _is_landmark(origin) or _is_landmark(dest) {
        window = [540, 1320];
    }
    seed = 0;
    for ch in origin + "|" + dest {
        seed = (seed * 31 + ord(ch)) % 1000003;
    }
    # Several trips on one route are spread across the window, one per slot.
    slot = (window[1] - window[0]) // max(1, n);
    start = window[0] + (slot * i) // 5 * 5;
    steps = slot // 5;
    offset = ((seed + k * 7919 + i * 104729) % (steps + 1)) * 5;
    total = start + offset;
    return f"{total // 60:02d}:{total % 60:02d}";
}

def _gender_of(k: int) -> str {
    slot = k % 9;
    if slot == 8 {
        return "non-binary";
    }
    return "woman" if slot % 2 == 0 else "man";
}

def _first_name(k: int, gender: str) -> str {
    if gender == "woman" {
        return WOMEN[(k * 7) % len(WOMEN)];
    }
    if gender == "man" {
        return MEN[(k * 11) % len(MEN)];
    }
    return NONBINARY[(k * 3) % len(NONBINARY)];
}

def _age_for(k: int, dest: str, origin: str) -> int {
    students = ["MSU", "UM Campus", "EMU", "Wayne State", "Oakland U"];
    if dest in students or origin in students {
        return 19 + (k % 6);
    }
    if dest.startswith("Test ") {
        return 18 + (k % 6);
    }
    return 21 + ((k * 17) % 46);
}

# Every sample person, in the same shape as the hand-written demo people.
# `taken` holds handles already in use elsewhere, so none are reused.
def demo_network(taken: list[str] = []) -> list[dict] {
    people: list[dict] = [];
    used: set[str] = set(taken);
    k = 0;
    for r in ROUTES {
        mode = r[0] as str;
        role = r[1] as str;
        origin = r[2] as str;
        dest = r[3] as str;
        extra = r[5] as str;
        for (i, listed) in enumerate(r[4] as list[str]) {
            dep = _time_for(mode, origin, dest, k, i, len(r[4] as list[str]));
            gender = _gender_of(k);
            noun_key = role if mode == "ride" else mode;
            nouns = NOUNS[noun_key];
            handle = ADJ[k % len(ADJ)] + nouns[(k // len(ADJ) + k) % len(nouns)];
            bump = 10 + k % 89;
            base = handle;
            while handle in used {
                handle = base + str(bump);
                bump += 1;
            }
            used.add(handle);
            vehicle = "";
            moving = False;
            if mode == "rental" {
                parts = extra.split("|");
                vehicle = parts[0];
                moving = len(parts) > 1 and parts[1] == "move";
            }
            note_key = role if mode == "ride" else mode;
            if mode == "rental" {
                note_key = "move" if moving else ("test" if dest.startswith("Test ") else "trip");
            }
            notes = NOTES[note_key];
            is_new = k % 6 == 0;
            a = PLACES[origin];
            b = PLACES[dest];
            person: dict = {
                "handle": handle, "name": _first_name(k, gender), "gender": gender,
                "age": _age_for(k, dest, origin), "role": role, "mode": mode,
                "from": a[0], "from_lat": a[1], "from_lng": a[2],
                "to": b[0], "to_lat": b[1], "to_lng": b[2],
                "dep": dep, "arr": "",
                "seats": (1 + k % 3) if role == "DRIVER" else 0,
                "people": (2 if k % 4 == 0 else 1) if mode != "ride" else 1,
                "rating": 0.0 if is_new else 4.3 + ((k * 3) % 7) / 10.0,
                "reviews": 0 if is_new else 3 + (k * 7) % 45,
                "note": notes[k % len(notes)], "vehicle": vehicle, "moving": moving,
                "recurring": mode == "ride", "gender_prefs": [], "age_min": 1, "age_max": 100
            };
            # A few people set their own preferences, so filters work both ways.
            if gender == "woman" and k % 10 == 4 {
                person["gender_prefs"] = ["woman", "non-binary"];
            }
            if k % 12 == 7 {
                person["age_min"] = 21;
                person["age_max"] = 65;
            }
            people.append(person);
            k += 1;
        }
    }
    return people;
}

