                        className="flex min-w-0 items-center gap-2 justify-self-start text-foreground"
                        aria-label={"A2 Pulse, " + TAGLINE}
                    >
                        <span className="size-2.5 shrink-0 rounded-full bg-foreground" />
                        <span className="flex min-w-0 flex-col leading-tight">
                            <span className="truncate text-base font-semibold tracking-tight">
                                {"A2 Pulse"}
                            </span>
                            <span className="hidden truncate text-[10px] text-muted-foreground sm:inline">
                                {TAGLINE}
                            </span>
                        </span>
                    </Link>
                    <nav className="flex items-center gap-1 justify-self-center rounded-full bg-muted p-1">
                        {for item in NAV_ITEMS {
                            <Link
                                key={item["to"]}
                                to={item["to"]}
                                className={
                                    "rounded-full px-3 py-1.5 text-sm font-medium transition-colors "
                                    + (
