def build_video(
    script: Script, topic: str, allowed_urls: list[str], notes: list[str], force_review: bool,
    scored_by: str
) -> Video {
    narration = _clip(script.narration, 1400);
    n_words = len(narration.split());
    scenes = sanitize_scenes(script.scenes, n_words);
    attributions: list[str] = [];
    for sc in scenes {
        if sc.template == "image" {
            img: dict[str, str] = {};
            try {
                img = find_commons_image(sc.query);
            } except Exception as err {
                notes.append("image search failed: " + str(err)[:80]);
            }
            if img {
                sc.image = img;
                attributions.append(img["credit"] + " — " + img["page"]);
            } else {
                sc.template = "bullets" if sc.items else "title_card";
                if not sc.heading {
                    sc.heading = sc.body or script.title;
                }
                notes.append("no licensed image for '" + sc.query + "'");
            }
        }
    }
    tts = TtsResult();
    if elevenlabs_enabled() {
        try {
            tts = elevenlabs_tts(narration);
        } except Exception as err {
            notes.append("tts failed: " + str(err)[:80]);
        }
    }
    has_audio = bool(tts.audio) and len(tts.words) > 0;
    words = tts.words if has_audio else estimate_words(narration);
    for sc in scenes {
        idx = min(sc.w, len(words) - 1) if words else 0;
        sc.t = words[idx].s if words else 0.0;
    }
    duration = words[-1].e + 0.6 if words else 30.0;
    manifest: dict[str, object] = {
        "v": 1, "tts": "elevenlabs" if has_audio else "browser", "audio": tts.audio if has_audio else "",
        "duration": r3(duration), "narration": narration, "words": _words_to_json(words),
        "scenes": [sc.to_dict() for sc in scenes]
    };
    citations = [u for u in script.citations if u in allowed_urls][:6];
    if not citations {
        citations = allowed_urls[:3];
    }
    digest = hashlib.sha1((script.title + "|" + narration).encode("utf-8")).hexdigest()[:16];
    quiz_ok = (
        len(script.quiz_choices) >= 2 and 0 <= script.quiz_answer < len(script.quiz_choices)
        and bool(script.quiz_question.strip())
    );
    status = "review" if force_review or topic == "current-events" else "live";
    return Video(
        kind="generated",
        title=_clip(script.title, 80),
        topic=topic,
        status=status,
        summary=_clip(script.summary, 200),
        tags=[_clip(t, 24).lower() for t in script.tags[:4]],
        duration_s=r3(duration),
        quality=0.75 if status == "live" else 0.6,
        scored_by=scored_by,
        score_reason="generated from cited sources; claims checked" if not force_review else "needs review",
        published_at=now_iso(),
        creator_name=STUDIO_NAME,
        creator_id="abt",
        provider="abt",
        external_id=digest,
        manifest_json=safe_json(manifest),
        citations=citations,
        attributions=attributions,
        quiz_question=_clip(script.quiz_question, 160) if quiz_ok else "",
        quiz_choices=[_clip(c, 80) for c in script.quiz_choices[:4]] if quiz_ok else [],
        quiz_answer=script.quiz_answer if quiz_ok else -1,
        quiz_explanation=_clip(script.quiz_explanation, 200) if quiz_ok else "",
        review_notes=notes
    );
}

def _publish(v: Video, run: PipelineRun) -> GenerationResult {
    existing = find_video("abt", v.external_id);
    if existing is not None {
        return GenerationResult(ok=True, status=existing.status, video_id=jid(existing),
                                title=existing.title, message="already exists");
    }
    if add_video(v) is None {
        return GenerationResult(ok=False, message="unknown topic " + v.topic);
    }
    run.finished_at = now_iso();
    run.stats = {"created": 1};
    root.shared ++> run;
    return GenerationResult(ok=True, status=v.status, video_id=jid(v), title=v.title,
                            notes=v.review_notes);
}

"""Full LLM pipeline for a subject. Must run anonymously."""
def generate_from_subject(subject: str, topic: str) -> GenerationResult {
    if not llm_enabled() {
        return GenerationResult(ok=False, message="No LLM configured (set OPENAI_API_KEY or similar).");
    }
    run = PipelineRun(kind="generation", started_at=now_iso(), notes=[subject]);
    outcome = run_research_agent(subject, topic);
    if outcome.error or outcome.script is None {
        return GenerationResult(ok=False, message=outcome.error or "agent produced no script",
                                notes=outcome.trace + outcome.notes);
    }
    script = outcome.script;
    notes = ["agent: " + t for t in outcome.trace] + outcome.notes;
    force_review = outcome.needs_review;
    n_words = len(script.narration.split());
    if n_words < 80 or n_words > 220 {
        notes.append("narration length " + str(n_words) + " words");
        force_review = True;
    }
    run.notes = run.notes + outcome.trace;
    v = build_video(script, topic, [d.url for d in outcome.sources], notes, force_review,
                    "agent:" + LLM_MODEL_NAME);
    return _publish(v, run);
}

"""Publish a hand-authored script (no LLM needed)."""
def publish_script(script: Script, topic: str, citations: list[str]) -> GenerationResult {
    run = PipelineRun(kind="seed", started_at=now_iso(), notes=[script.title]);
    v = build_video(script, topic, citations, [], False, "editorial");
    return _publish(v, run);
}

# file: services/planner.sv.jac
"""Catalog planner (walker + LLM editor) and the job worker.

PlanCatalog walks root.shared -> Topic nodes. At each topic it measures supply
(live / generated videos) and demand (user signals), asks the LLM editor what
the topic needs, and enqueues Job nodes. run_jobs() drains the queue.
"""

import re;
import from services.catalog {
    Topic, Video, Signal, Job, JobQueue, PipelineRun, job_queue, jobs, signal_log, videos_of,
    admin_error, ensure_catalog, now_iso
}
import from services.ai { fast_llm, llm_enabled, LLM_MODEL_NAME }
import from services.curation { run_curation }
import from services.generation { generate_from_subject }

obj TopicPlan {
    has curate: bool,
        subjects: list[str],
        rationale: str;
}

sem TopicPlan.curate = "True if the topic needs more curated videos from its channels.";
sem TopicPlan.subjects = "0..max_new concrete, evergreen, factual subjects for new ~60s explainers, not already covered.";
sem TopicPlan.rationale = "One short sentence explaining the plan.";

def llm_plan_topic(
    topic_name: str, description: str, live_count: int, generated_count: int,
    demand_share: float, recent_titles: list[str], max_new: int
) -> TopicPlan by fast_llm(temperature=0.6, max_tokens=500);

sem llm_plan_topic = """You are the editor of an educational short-video feed. Given a topic's
supply (live videos) and demand (share of recent learner engagement), decide whether to curate
more and propose up to max_new specific subjects for new explainers (e.g. 'How suspension
bridges carry load'). Never propose opinion, partisan, medical-advice or breaking-news subjects,
and never repeat anything in recent_titles.""";
sem llm_plan_topic.demand_share = "0..1 share of recent engagement landing in this topic.";

def _norm(s: str) -> str {
    return re.sub("[^a-z0-9 ]", "", s.lower()).strip();
}

"""Heuristic plan when no LLM is configured (can only request curation)."""
def heuristic_plan(live_count: int, target_live: int, demand_share: float) -> TopicPlan {
    needs = live_count < target_live or (demand_share > 0.25 and live_count < target_live * 2);
    return TopicPlan(curate=needs, subjects=[], rationale="heuristic: supply vs target");
}

walker:pub PlanCatalog {
    has admin_key: str = "",
        target_live: int = 20,
        max_new_per_topic: int = 2,
        reports: list[list[str]] = [];

    has demand: dict[str, float] = {},
        pending: set[str] = set(),
        queued: list[str] = [],
        use_llm: bool = False,
        error: str = "";

    can start with Root entry {
        self.error = admin_error(self.admin_key);
        if self.error {
            report [self.error];
            disengage;
        }
        ensure_catalog();
        self.use_llm = llm_enabled();
        self.queued = [];
        self.pending = {j.kind + ":" + j.topic + ":" + _norm(j.subject) for j in jobs("queued")};
        # Demand = share of recent completes/likes/saves per topic.
        topic_of = {jid(v): v.topic for t in [here -->[?:Topic]] for v in videos_of(t)};
        counts: dict[str, float] = {};
        total = 0.0;
        log = signal_log();
        if log is not None {
            for s in [log -->[?:Signal]] {
                w = {"complete": 1.0, "like": 1.5, "save": 2.0}.get(s.kind, 0.0);
                t = topic_of.get(s.video_id, "");
                if w > 0.0 and t {
                    counts[t] = counts.get(t, 0.0) + w;
                    total += w;
                }
            }
        }
        self.demand = {k: counts[k] / total for k in counts} if total > 0.0 else {};
        visit [here -->[?:Topic]];
    }

    can plan_topic with Topic entry {
        vids = videos_of(here);
        live = [v for v in vids if v.status == "live"];
        generated = [v for v in live if v.kind == "generated"];
        titles = [v.title for v in sorted(vids, key=lambda v: Video : v.added_at, reverse=True)[:30]];
        share = self.demand.get(here.slug, 0.0);
        plan = heuristic_plan(len(live), self.target_live, share);
        if self.use_llm {
            try {
                plan = llm_plan_topic(
                    here.name, here.description, len(live), len(generated), share, titles,
                    0 if here.is_current_events else self.max_new_per_topic
                );
            } except Exception as err {
                print("[plan] LLM failed for", here.slug, str(err)[:120]);
            }
        }
        existing = {_norm(t) for t in titles};
        if plan.curate {
            self._enqueue("curate", here.slug, "", plan.rationale);
        }
        if not here.is_current_events {
            for subj in plan.subjects[:self.max_new_per_topic] {
                if subj.strip() and _norm(subj) not in existing and len(subj) <= 200 {
                    self._enqueue("generate", here.slug, subj.strip(), plan.rationale);
                }
            }
        }
    }

    def _enqueue(kind: str, topic: str, subject: str, reason: str) {
        key = kind + ":" + topic + ":" + _norm(subject);
        q = job_queue();
        if key in self.pending or q is None {
            return;
        }
        self.pending.add(key);
        q ++> Job(kind=kind, topic=topic, subject=subject, reason=reason[:200], created_at=now_iso());
        self.queued.append(key);
    }

    can finish with Root exit {
        if not self.error {
            report self.queued;
        }
    }
}

obj JobResult {
    has kind: str,
        topic: str,
        subject: str,
        status: str,
        result: str;
}

"""Process up to max_jobs queued jobs (FIFO). Must run anonymously."""
def run_jobs(max_jobs: int) -> list[JobResult] {
    queued = sorted(jobs("queued"), key=lambda j: Job : j.created_at);
    out: list[JobResult] = [];
    for j in queued[:max_jobs] {
        j.status = "running";
        j.attempts += 1;
        try {
            if j.kind == "curate" {
                stats = run_curation(4, "", j.topic);
                j.result = "new=" + str(stats.get("new", 0)) + " live=" + str(stats.get("live", 0));
                j.status = "done";
            } elif j.kind == "generate" {
                r = generate_from_subject(j.subject, j.topic);
                j.result = (r.status + " " + r.title) if r.ok else ("failed: " + r.message);
                j.status = "done" if r.ok else "failed";
            } else {
                j.status = "failed";
                j.result = "unknown job kind";
            }
        } except Exception as err {
            j.status = "failed" if j.attempts >= 3 else "queued";
            j.result = str(err)[:200];
        }
        j.finished_at = now_iso();
        out.append(JobResult(kind=j.kind, topic=j.topic, subject=j.subject, status=j.status, result=j.result));
    }
    return out;
}

