                            ); }}
                            reward={("+" + str(v.task.xp) + " XP")}
                        /> for v in tasks
                    ]
                        if loaded
                        else []}
                    <Button
                        label="Finish"
                        onClick={lambda (e: MouseEvent) { finish(); }}
                        disabled={saving}
                        full={True}
                    />
                </div>
            )
                if step == 4
                else None}
        </main>
    </div>
}

impl Onboarding.load -> None {
    summary: JourneySummary | None = None;
    summary = await my_journey();
    tasks = summary.tasks;
    loaded = True;
}

impl Onboarding.saveArrival -> None {
    result: ProfileUpdateResult | None = None;
    saving = True;
    result = await update_my_profile(
        {"arrival_date": arrival_date, "arrival_time": arrival_time}
    );
    saving = False;
    if result.ok {
        error = "";
        step = step + 1;
    } else {
        error = result.error;
    }
}

impl Onboarding.saveAcademic -> None {
    result: ProfileUpdateResult | None = None;
    saving = True;
    result = await update_my_profile({"major": major, "class_year": class_year});
    saving = False;
    if result.ok {
        error = "";
        step = step + 1;
    } else {
        error = result.error;
    }
}

impl Onboarding.saveHousing -> None {
    result: ProfileUpdateResult | None = None;
    saving = True;
    result = await update_my_profile({"area": area, "housing_status": housing_status});
    saving = False;
    if result.ok {
        error = "";
        step = step + 1;
    } else {
        error = result.error;
    }
}

impl Onboarding.saveLanguage -> None {
    result: ProfileUpdateResult | None = None;
    saving = True;
    result = await update_my_profile({"preferred_language": preferred_language});
    saving = False;
    if result.ok {
        error = "";
        step = step + 1;
    } else {
        error = result.error;
    }
}

impl Onboarding.toggleTask(tid: str, done: bool) -> None {
    if done {
        await reopen_task(tid);
    } else {
        await mark_task_done(tid, skip_step_check=True);
    }
    await load();
}

impl Onboarding.finish -> None {
    result: ProfileUpdateResult | None = None;
    saving = True;
    result = await update_my_profile({"onboarding_done": True});
    saving = False;
    if result.ok {
        error = "";
        go("/today");
    } else {
        error = result.error;
    }
}

