"""Gabriel's workspace. Search and selection belong to this tab, not the shell."""
import from .Panels { PeoplePanel, ClaimsPanel }
import from .IdentityReview { IdentityReview }
import from .PeopleStats { PeopleStats }
import from .CorpusPeople { CorpusPeople }
import from ...components.shared.Display { SectionHeading }
import from ...components.shared.Scale { is_corpus_snapshot }
sv import from ...services.trace { DashboardSnapshot, PersonView, search_people }
sv import from ...walkers.resolve { DuplicateCandidate }

def:pub PeopleTab(snapshot: DashboardSnapshot, onRefresh: Callable[[], any], onShowOnMap: Callable[[str], None] | None = None, reviewRequest: int = 0) -> JsxElement {
    has query: str = "", selectedId: str = "", reviewKey: str = "",
        results: list[PersonView] | None = None, searching: bool = False,
        searchError: str = "", searchedFor: str = "";

    # A different incident starts with its own default list and no stale search.
    can with [snapshot.incident_id] entry {
        results = None;
        query = "";
        searchedFor = "";
        searchError = "";
        selectedId = "";
        reviewKey = "";
    }

    # The story guide asks to open a match review: prefer an undecided one.
    can with [reviewRequest] entry {
        if reviewRequest <= 0 or len(snapshot.duplicates) == 0 { return; }
        pending = [d for d in snapshot.duplicates if d.decision == "PENDING"];
        first = pending[0] if len(pending) > 0 else snapshot.duplicates[0];
        query = "";
        reviewKey = first.person_a_id + "|" + first.person_b_id;
    }

    async def runSearch -> None {
        term = query.strip();
        if term == "" {
            results = None;
            searchedFor = "";
            return;
        }
        searching = True;
        searchError = "";
        try {
            results = await search_people(snapshot.incident_id, term, 100);
            searchedFor = term;
        } except Exception as e {
            searchError = "Search failed: " + str(e);
        }
        searching = False;
    }

    raw: any = snapshot;
    corpus = is_corpus_snapshot(raw);
    if corpus {
        return <CorpusPeople snapshot={snapshot} people={results if results != None else snapshot.people}
            query={query} searching={searching} searchError={searchError} searchedFor={searchedFor}
            selectedId={selectedId} onSelect={lambda (pid: str) { selectedId = pid; }}
            onQuery={lambda (value: str) {
                query = value;
                if value.strip() == "" { results = None; searchedFor = ""; }
            }}
            onSearch={runSearch} onShowOnMap={onShowOnMap} />;
    }

    q = query.strip().lower();
    people = [p for p in snapshot.people if q == "" or q in p.name.lower()];
    selected: PersonView | None = None;
    for p in people {
        if p.id == selectedId { selected = p; }
    }
    if selected == None and len(people) > 0 { selected = people[0]; }
    duplicates = [d for d in snapshot.duplicates if q == "" or q in d.person_a.lower() or q in d.person_b.lower()];

    # The open review is looked up from the live snapshot, so refresh updates it.
    matches: list[DuplicateCandidate] = [d for d in snapshot.duplicates if reviewKey != "" and (d.person_a_id + "|" + d.person_b_id) == reviewKey];
    personA: PersonView | None = None;
    personB: PersonView | None = None;
    reviewPanel: any = None;
    if len(matches) > 0 {
        review: DuplicateCandidate = matches[0];
        for p in snapshot.people {
            if p.id == review.person_a_id { personA = p; }
            if p.id == review.person_b_id { personB = p; }
        }
        reviewPanel = <IdentityReview candidate={review} personA={personA} personB={personB}
            onRefresh={onRefresh} onClose={lambda { reviewKey = ""; }} />;
    }

    return <div className="flex flex-col gap-5">
        <SectionHeading title="People" subtitle="Find someone, see every report about them, and check possible matches." />
        <PeopleStats people={snapshot.people} duplicates={snapshot.duplicates} />
        <label className="flex max-w-xl flex-col gap-2 text-sm">
            <span className="font-medium">{"Search people"}</span>
            <input type="search" value={query}
                onChange={lambda (e: ChangeEvent) { query = e.target.value; }}
                placeholder="Type a name, for example Maya"
                className="h-11 w-full rounded-md border border-input bg-card px-3 text-base outline-none focus-visible:ring-2 focus-visible:ring-ring" />
            <span className="text-xs text-muted-foreground">{str(len(people)) + " of " + str(len(snapshot.people)) + " people shown"}</span>
        </label>
        <div id="identity-review" className="scroll-mt-4">{reviewPanel}</div>
        <div className="grid items-start gap-8 xl:grid-cols-2">
            <PeoplePanel people={people} duplicates={duplicates}
                selectedId={selected.id if selected else ""}
                onSelect={lambda (pid: str) { selectedId = pid; }}
                onReview={lambda (key: str) { reviewKey = key; }} />
            <ClaimsPanel person={selected} incidentId={snapshot.incident_id} onShowOnMap={onShowOnMap}
                mappedClaimIds={[e.claim_id for place in snapshot.locations for e in place.evidence]} />
        </div>
    </div>;
}

# file: features/people/README.md
# People — Gabriel

Entry component: `PeopleTab.jac`.

Own case search, report timelines, human identity review, and walkers/resolve.jac. Add corrections as sourced claims; never overwrite source history.

Keep feature components, helpers, new server adapters, and focused tests in this folder.
All tabs receive a read-only `DashboardSnapshot` and async `onRefresh` callback.
After a successful server write, `await onRefresh()` to update all views.

See [the team contract](../../docs/TEAM.md) before changing shared interfaces.

## Identity review flow

Agent proposes a pair -> it appears as a candidate in People -> a human opens
"Review match", sees both records, their claims and sources (agent-cited claims
highlighted), similarities / differences / unknowns -> confirms or rejects with
name + reason -> decision persists and shows after refresh.

Files: `IdentityReview.jac` (UI), `services.jac` (endpoints),
`test_identity_review.jac` (9 tests). Logic: `walkers/resolve.jac`.

### Agent interface (for Anshu / the investigation agent)

`POST /function/propose_identity`

```
propose_identity(incident_name: str, person_a_id: str, person_b_id: str,
                 proposed_by: str, rationale: str, cited_claim_ids: list[str])
  -> IdentityDecisionResult {ok, message, changed, decision, pair_key}
```

- IDs are Person `jid`s from `DashboardSnapshot.people[].id`; claim IDs from
  `people[].claims[].id`. Order of the two person IDs does not matter.
- Refused (ok=False, nothing written): unknown incident, same ID twice, an ID
  that is not a Person in that incident, a cited ID that is not a claim about
  one of the two records, empty `proposed_by`.
- Idempotent per pair: same proposal again returns changed=False; a new
  rationale/citation set updates the one proposal in place.
- A proposal never creates a decision or association. After calling it,
  the agent (or the shell) should `await onRefresh()`.

`POST /function/review_identity` (called by the panel)

```
review_identity(incident_name, person_a_id, person_b_id, decision, reviewer,
                note, basis: list[str], evidence_claim_ids: list[str])
```

Same validation, plus decision in {CONFIRMED, REJECTED} and non-empty reviewer.

### Integrated shared changes
- **Miguel (schema, graph/nodes.jac + graph/edges.jac):**
  - `IdentityDecision` (one per pair, `pair_key` = sorted jids) gained
    `incident_name`, `evidence_claim_ids`, `past_reviews: list[IdentityReviewEntry]`.
    The legacy `history: list[str]` field is kept but no longer written.
  - New `obj IdentityReviewEntry {decision, reviewer, decided_at, note, basis, evidence_claim_ids}`.
  - New `node IdentityProposal {pair_key, person_a_id, person_b_id, incident_name,
    proposed_by, rationale, cited_claim_ids, proposed_at}` attached to root.
  - `edge Reviews: IdentityDecision --> Person` (unchanged from v1).
- **Anshu (integration):**
  - `main.jac` imports `features.people.services { review_identity, propose_identity, IdentityDecisionResult }`.
  - `DuplicateCandidate` (in the snapshot) gained defaulted fields: incident_name,
    evidence_claim_ids, past_reviews, proposed_by, proposal_rationale,
    cited_claim_ids, differences, unknowns. No renames.
  - ResolveWalker now also lists agent-proposed pairs that the name/age rules
    did not flag (label "NOT RULE-MATCHED").
  - IngestWalker associates reports only through an explicit person ID; otherwise
    it creates a separate record. Review decisions do not silently redirect ingestion.

### Behaviour notes
- "Latest status" comparisons sort status claims by report timestamp and keep
  repeats, so MISSING -> FOUND_SAFE -> MISSING ends at MISSING. Undated claims
  are not ordered and are reported as "No dated status report".
- Unknowns only say what the graph does not hold ("No ... comparison result is
  recorded"); they never claim a check was or was not performed.

### Limitations
- Reviewer is a typed name (no auth).
- A CONFIRMED decision does not merge timelines or change displayed status.
- Incident-scoped reset clears its decisions/proposals while preserving shared and unrelated data.
- PersonView flags differing latest/undated status reports for review; it does not
  treat strictly earlier differing reports as a current conflict.

