/* Fonts + every design token this file's classes consume now live in
   theme.css (loaded before this file — see main.jac's import order). This
   file only defines: the Tailwind @theme inline binding (still needed here,
   Tailwind's utility-class generation is per-CSS-file), and the .exp-*
   component classes that consume theme.css's tokens. */
@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);
  --font-heading: var(--font-sans);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  /* The Tailwind `border-border` utility is used ~62x as a DIVIDER (section-header
     rules, tab strips, table cells, rail edges). `--border` is the glass RIM token
     — rgba(255,255,255,0.55) — i.e. a white line, invisible on the light theme.
     Point the utility at `--border-alt` (the real hairline divider); .exp-panel and
     friends still reference `var(--border)` directly for their glass rim. */
  --color-border: var(--border-alt);
  --color-border-glass: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-chart-6: var(--chart-6);
  --color-ok: var(--ok);
  --color-danger: var(--danger);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  /* bare `rounded` defaults to Tailwind's 4px, which reads as a chip next to the
     16px panels around it. Name the DEFAULT so it lands on our scale. (Do NOT
     declare `--radius` itself here — theme.css owns it, and --radius-lg reads it
     back, so redeclaring would be a circular reference.) */
  --radius-DEFAULT: calc(var(--radius) * 0.6);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

/* Token values (colors, radius, fonts, sidebar, chart palette) are all
   defined once in theme.css's :root — nothing to redeclare here. */

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  html {
    @apply font-sans;
  }
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  font-weight: var(--weight-light);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
/* Flat theme: the mesh-gradient layer and the grain overlay that used to sit
   behind all content are both gone — the page is plain --bg (true black / pure
   white) and orange is the only chromatic element. --bg-gradient is kept as a
   token set to `none` so any rule still referencing it stays valid. */

/* --border is the glass rim (white in light mode) — a divider needs --border-alt */
.dashed-rule { border-top: 1px dashed var(--border-alt); }

/* ============================================================ exp-* component classes
   Structural layer for the Experiments surface. Mirrors jms.css's component
   treatment (deliberate radius, hairline borders, accent-glow hover, mono
   labels/buttons/pills) but consumes THIS app's :root tokens (--accent,
   --border, --card, --popover, --muted-foreground, --accent-foreground) so
   Experiments reads as the same product family as the JMS hero/shell WITHOUT
   redefining any color token or duplicating the .jms-scope. jms.css's .jms-*
   classes live under .jms-scope and consume --jms-* tokens; both --jms-* and
   --exp-* are aliases of the same canonical tokens, declared once in
   theme.css. Layout/spacing stay in the components' Tailwind utilities;
   these classes own only surface identity. */

/* -- labeled bordered panel — replaces the ~42 hand-rolled
   `rounded-md border border-border bg-card` blocks. Glass surface: blurred
   translucent fill, hairline border, soft shadow + inner highlight. Pair with
   the existing `.micro-label absolute -top-2 left-3 bg-background px-2`
   floating tab. Grouped with jms.css's .jms-card/.jms-section — same glass
   surface, all three now render identical chrome. */
.exp-panel, .jms-card, .jms-section, .jms-feature {
  position: relative;
  background: var(--surface); backdrop-filter: var(--blur); -webkit-backdrop-filter: var(--blur);
  border: 1px solid var(--border); border-radius: var(--radius);
  box-shadow: var(--shadow-soft), var(--inner-hi);
  transition: border-color var(--dur-fast) var(--ease-out), box-shadow var(--dur-fast) var(--ease-out), background-color var(--dur-fast) var(--ease-out), transform var(--dur-fast) var(--ease-out);
}
@supports not (backdrop-filter: blur(1px)) { .exp-panel,.jms-card,.jms-section,.jms-feature { background: var(--surface-strong); } }

/* Near-opaque surface for OVERLAYS that sit over other UI (slide-over drawers,
   modals, popovers) — plain glass lets the content behind bleed through and
   read as noise. Apply alongside a glass panel/popover class. */
.g-scrim { background: var(--scrim); }
.g-overlay { background: var(--overlay) !important; backdrop-filter: var(--blur); -webkit-backdrop-filter: var(--blur); }

/* -- accent-glow hover — the single treatment that makes the JMS surface feel
   alive rather than flat. Add to any clickable card / nav tile / row / chip. */
.exp-hoverable { transition: border-color var(--dur-fast) var(--ease-out), box-shadow var(--dur-fast) var(--ease-out), background-color var(--dur-fast) var(--ease-out), color var(--dur-fast) var(--ease-out), transform var(--dur-fast) var(--ease-out); }
.exp-hoverable:hover, .jms-card:hover { border-color: var(--accent); box-shadow: var(--shadow-soft), var(--inner-hi); transform: translateY(-2px); }

/* unified glass button — .exp-btn and .jms-btn are the SAME rule */
.exp-btn, .jms-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  font-family: var(--font-mono); font-size: 11px; font-weight: var(--weight-reg);
  letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--text-muted);
  background: var(--surface); backdrop-filter: var(--blur); -webkit-backdrop-filter: var(--blur);
  border: 1px solid var(--border-alt);
  border-radius: calc(var(--radius) * 0.75);
  box-shadow: var(--inner-hi);
  padding: 7px 14px; cursor: pointer;
  transition: color var(--dur-fast) var(--ease-out), border-color var(--dur-fast) var(--ease-out), background-color var(--dur-fast) var(--ease-out), box-shadow var(--dur-fast) var(--ease-out), transform var(--dur-fast) var(--ease-out), filter var(--dur-fast) var(--ease-out);
}
.exp-btn:hover, .jms-btn:hover {
  color: var(--text); border-color: var(--accent);
  transform: translateY(-1px); box-shadow: var(--shadow-soft), var(--inner-hi);
}
.exp-btn:disabled, .jms-btn:disabled { opacity: 0.4; cursor: not-allowed; transform: none; }
/* was hardcoded #fff, which is 2.6:1 on the light accent — below AA for the 11px
   text this class sets — and contradicted --accent-foreground in dark mode. */
.exp-btn-accent, .jms-btn-accent {
  background: var(--accent); border-color: var(--accent); color: var(--accent-foreground);
}
.exp-btn-accent:hover, .jms-btn-accent:hover {
  filter: brightness(1.08); color: var(--accent-foreground); border-color: var(--accent);
}
/* the vocabulary hole: components were applying the CHIP modifier .exp-chip-active
   to buttons because no active-button state existed. */
.exp-btn-active, .jms-btn-active {
  color: var(--accent); border-color: var(--accent);
  background: var(--accent-tint); box-shadow: var(--accent-ring);
}
.exp-btn-ghost, .jms-btn-ghost { background: transparent; backdrop-filter: none; border-color: transparent; box-shadow: none; }
.exp-btn-ghost:hover, .jms-btn-ghost:hover { color: var(--text); border-color: transparent; }
.exp-btn-danger, .jms-btn-danger { color: var(--danger); border-color: var(--border-alt); }
.exp-btn-danger:hover, .jms-btn-danger:hover { color: var(--danger); border-color: var(--danger); }
@supports not (backdrop-filter: blur(1px)) { .exp-btn, .jms-btn { background: var(--surface-strong); } }

/* -- chip / pill (segmented options, session pickers, file chips) --------- */
/* grouped with jms.css's .jms-chip (badge + chat-bubble use) — glass pill
   reads fine in both roles. */
.exp-chip, .jms-chip {
  display: inline-flex; align-items: center; gap: 6px;
  font-family: var(--font-mono); font-size: 11px; letter-spacing: 0.04em;
  color: var(--text-muted);
  background: var(--surface); backdrop-filter: var(--blur); -webkit-backdrop-filter: var(--blur);
  border: 1px solid var(--border-alt); border-radius: 999px;
  padding: 4px 12px; cursor: pointer;
  transition: color var(--dur-fast) var(--ease-out), border-color var(--dur-fast) var(--ease-out), background-color var(--dur-fast) var(--ease-out), box-shadow var(--dur-fast) var(--ease-out);
}
.exp-chip:hover, .jms-chip:hover { color: var(--text); border-color: var(--accent); }
.exp-chip-active, .jms-chip-active {
  color: var(--accent); border-color: var(--accent);
  background: var(--accent-tint); box-shadow: var(--accent-ring);
}
@supports not (backdrop-filter: blur(1px)) { .exp-chip, .jms-chip { background: var(--surface-strong); } }

/* -- top workspace bar — the horizontal switcher across the app's top edge
   (mirrors jms.css's .jms-topbar: hairline bottom rule, card surface, a
   left group [wordmark + workspace tiles] and a right action). Tile chrome
   itself is the existing .exp-hoverable + Tailwind utilities in
   WorkspaceBar.cl.jac; this owns only the bar frame. */
/* padding matches jms.css's .jms-topbar exactly — same header height both surfaces */
/* --topbar-h is the bar's height as a TOKEN, not a magic number: the ⚙ WORKSPACES
   drawers (WorkspaceSettings / JmsWorkspaceSettings) offset their own top edge by
   exactly this, so the bar — and therefore the ⚙ WORKSPACES button that opens
   them — stays visible and CLICKABLE while the drawer is open. Before that, the
   right-hand drawer panel rendered on top of its own trigger (both `fixed inset-0
   z-50`, panel x:1152→1600 vs button x:1443→1568), elementFromPoint at the gear
   returned the panel header, and a second click could never reach the toggle.
   Pinning min-height here is what stops the two from drifting apart: the natural
   height is 61.5px (14px padding ×2 + a 33px .exp-btn + the 1px rule), rounded up
   to 62 so the drawer's top edge leaves no sub-pixel seam. z-index is deliberately
   NOT the fix: .exp-topbar sets backdrop-filter, which makes it a stacking context
   (so a z-index on the button alone can never escape it), and raising the whole
   62px bar above z-50 would bury the drawer's own 49px header row — ✕ included —
   and every other z-50 overlay's top edge (AssistantPanel, ApiKeyModal, Gallery). */
:root { --topbar-h: 62px; }
.exp-topbar, .jms-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-shrink: 0;
  min-height: var(--topbar-h);
  padding: 14px clamp(16px, 2.5vw, 32px);
  background: var(--bar);
  backdrop-filter: var(--blur);
  -webkit-backdrop-filter: var(--blur);
  border-bottom: 1px solid var(--border-alt);
}
@supports not (backdrop-filter: blur(1px)) { .exp-topbar, .jms-topbar { background: var(--bar); } }
/* workspace tiles live in a fixed-height bar — no lift (it clips outside the frame) */
.exp-topbar .exp-hoverable:hover, .jms-topbar .exp-hoverable:hover { transform: none; box-shadow: none; }

/* -- text input / textarea ---------------------------------------------- */
.exp-input, .jms-input, .jms-textarea {
  width: 100%; font-family: var(--font-mono); font-size: 12px; color: var(--text);
  background: var(--surface); backdrop-filter: var(--blur); -webkit-backdrop-filter: var(--blur);
  border: 1px solid var(--border-alt); border-radius: calc(var(--radius) * 0.6);
  padding: 9px 12px; outline: none;
  transition: border-color var(--dur-fast) var(--ease-out), box-shadow var(--dur-fast) var(--ease-out);
}
.exp-input:focus, .jms-input:focus, .jms-textarea:focus { border-color: var(--accent); box-shadow: var(--accent-ring); }
.exp-input::placeholder, .jms-input::placeholder, .jms-textarea::placeholder { color: var(--text-muted); opacity: 0.7; }
.jms-textarea { resize: vertical; min-height: 68px; line-height: 1.45; }
@supports not (backdrop-filter: blur(1px)) { .exp-input, .jms-input, .jms-textarea { background: var(--surface-strong); } }

/* -- display / hero type — Geist at display weight & tight tracking, for the
   few natural "hero" moments (auth gate heading, offline card, empty states).
   NOT for dense data/table text — those stay at the normal mono/body scale. */
.exp-display, .jms-display {
  font-family: var(--font-display); font-weight: var(--weight-black);
  letter-spacing: -0.03em; line-height: 0.92; color: var(--text);
}

