/* theme.css — the ONE canonical token source for the whole Studio.
   FLAT theme: pure-white :root + true-black .dark. No mesh gradient, no grain, no
   warm tint — orange (#EC8242 light / #f4914e dark) is the ONLY chromatic element,
   used for buttons, highlights, active states and focus.
   Both product surfaces (Experiments .exp-*, JMS .jms-*) read these tokens;
   --jms-*, --exp-*, and shadcn names below are thin aliases so existing component
   classes need no edits. Loads before global.css + jms.css (main.jac order). */

/* ---- fonts: display grotesque (heavy) + body (light) + mono ---- */
@import url('https://fonts.googleapis.com/css2?family=Geist:wght@100..900&family=Geist+Mono:wght@100..900&family=Space+Grotesk:wght@300..700&family=Inter:wght@100..900&display=swap');

:root {
  /* ===== FLAT palette — LIGHT (default) =====
     Flat white, no mesh gradient, no tint. Orange is the ONLY chromatic element:
     buttons, highlights, focus, active states. Panels separate from the page by a
     hairline border + a soft shadow, not by a fill difference. */
  --bg: #ffffff;
  --bg-gradient: none;
  --surface: #ffffff;
  --surface-strong: #ffffff;
  --bar: #ffffff;
  --overlay: #ffffff;
  --text: #0a0a0a;
  --text-muted: #6e6e6e;
  /* neutral hairlines — --border is the panel rim, --border-alt the divider */
  --border: rgba(0,0,0,0.12);
  --border-alt: rgba(0,0,0,0.10);
  --accent: #EC8242;
  --accent-hover: #d96e2e;
  --accent-soft: #f4a574;
  --accent-tint: rgba(236,130,66,0.10);
  --accent-ring: 0 0 0 3px rgba(236,130,66,0.28);
  --ok: #3a9d6b;
  --danger: #d24b3e;
  --inner-hi: 0 0 #0000;
  /* modal/drawer scrim — was a hardcoded `bg-black/60` at every dialog, which is
     far too heavy on a pure-white page */
  --scrim: rgba(0,0,0,0.32);

  /* ===== shared (mode-independent) ===== */
  --radius: 16px;
  /* surfaces are opaque now, so the blur is a no-op on panels; kept only so any
     translucent overlay that still wants it renders the same as before */
  --blur: blur(20px) saturate(160%);
  --shadow-soft: 0 1px 2px rgba(0,0,0,0.05), 0 8px 24px rgba(0,0,0,0.06);
  --shadow-nav: 0 1px 2px rgba(0,0,0,0.05);
  --font-display: 'Geist', 'Space Grotesk Variable', ui-sans-serif, sans-serif;
  --font-body: 'Inter', ui-sans-serif, system-ui, -apple-system, sans-serif;
  --font-mono: 'Geist Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  --weight-thin: 200; --weight-light: 300; --weight-reg: 400; --weight-med: 500;
  --weight-bold: 700; --weight-black: 900;
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --dur-fast: 0.3s; --dur-base: 0.6s; --dur-slow: 0.9s;
  --space-1:4px; --space-2:8px; --space-3:12px; --space-4:16px; --space-5:20px; --space-6:24px;

  /* ===== aliases so existing classes keep working ===== */
  --background: var(--bg); --foreground: var(--text);
  --card: var(--surface); --card-foreground: var(--text);
  --popover: var(--surface-strong); --popover-foreground: var(--text);
  --primary: var(--accent); --primary-foreground: var(--accent-foreground);
  --secondary: var(--surface); --secondary-foreground: var(--text);
  --muted: var(--surface); --muted-foreground: var(--text-muted);
  /* dark brown, not white: white on #EC8242 is 2.6:1, under AA. Matches dark mode,
     where accent-foreground is already near-black — so accent buttons now read the
     same way in both themes. */
  --accent-foreground: #2b1608;
  --destructive: var(--danger); --destructive-strong: var(--danger);
  --input: var(--border-alt); --ring: var(--accent);
  --font-sans: var(--font-display);
  --glow: var(--shadow-soft);
  /* orange ramp + neutrals: series stay distinguishable without reintroducing
     off-theme blue/violet/teal into an orange-only palette */
  --chart-1: var(--accent); --chart-2: var(--text-muted); --chart-3: var(--accent-soft);
  --chart-4: var(--text); --chart-5: #b8702f;
  --chart-6: #f7b98a;
  --label: var(--text-muted);
  /* code-syntax palette — tokenized so light mode gets its own (darker) set.
     These were hardcoded dark-only hexes in global.css: pale green strings and
     #5a5a5a comments are unreadable on a white surface. */
  --tok-kw: #7c3aed; --tok-type: #0f766e; --tok-bi: #1d4ed8;
  --tok-str: #3f7d34; --tok-num: #a16207; --tok-com: #8a8279;
  --sidebar: var(--surface); --sidebar-foreground: var(--text);
  --sidebar-primary: var(--accent); --sidebar-primary-foreground: var(--accent-foreground);
  --sidebar-accent: var(--accent); --sidebar-accent-foreground: var(--accent-foreground);
  --sidebar-border: var(--border-alt); --sidebar-ring: var(--accent);
  --ws01: var(--accent); --ws02: #f7b98a; --ws03: #c96a24;
  --ws04: #9a5520; --ws05: #ffd0aa; --ws06: #7a4418; --ws-accent: var(--accent);
  /* --jms-* aliases (jms.css classes reference these unchanged) */
  --jms-bg: var(--bg); --jms-bg-raised: var(--surface); --jms-fg: var(--text);
  --jms-fg-dim: var(--text-muted); --jms-accent: var(--accent); --jms-accent-2: var(--chart-3);
  --jms-accent-fg: var(--accent-foreground); --jms-border: var(--border-alt); --jms-ok: var(--ok);
  --jms-danger: var(--danger); --jms-font-display: var(--font-display);
  --jms-font-body: var(--font-body); --jms-font-mono: var(--font-mono);
  --jms-radius: var(--radius); --jms-hover-shadow: var(--shadow-soft);
  --jms-border-w: 1px; --jms-rule-style: solid; --jms-display-weight: var(--weight-black);
  --jms-display-tracking: -0.03em; --jms-display-transform: none; --jms-display-glow: none;
  --jms-card-shadow: var(--inner-hi);
  /* --exp-* aliases */
  --exp-radius: var(--radius); --exp-glow: var(--shadow-soft);
  --exp-accent-tint: var(--accent-tint); --exp-accent-ring: var(--accent-ring);
  --scrollbar: rgba(0,0,0,0.25);
}

.dark {
  /* ===== FLAT palette — DARK =====
     True black page, no mesh gradient, no warm tint. Panels lift off the page by
     one step of neutral grey + a hairline border. Orange stays the only accent. */
  --bg: #000000;
