import from ..shared.Gallery { Gallery }

def _stripModels(m: str) -> str {
    if m.startswith("models/") { return m[7:]; }
    return m;
}

def _g(sc: any, k: str) -> str {
    if sc and k in sc { return str(sc[k]); }
    return "·";
}

def _idiomatic(sc: any) -> str {
    if sc and "idiomatic" in sc and "runs" in sc {
        return str(sc["idiomatic"]) + "/" + str(sc["runs"]);
    }
    return "·";
}

# Numeric headline (probe→test_pass_pct, idiom→avg_sim) for best-cell highlight; -1 absent.
def _headNum(r: any) -> float {
    sc: any = r.scores;
    if not sc { return -1.0; }
    key = "test_pass_pct" if str(r.kind) == "probe" else "avg_sim";
    if key in sc { return float(str(sc[key])); }
    return -1.0;
}

# Raw display string of the headline value (preserves the JSON form, e.g. "85").
def _headDisp(r: any) -> str {
    sc: any = r.scores;
    key = "test_pass_pct" if str(r.kind) == "probe" else "avg_sim";
    return str(sc[key]);
}

# String shown in the history SCORE column.
def _headline(r: any) -> str {
    sc: any = r.scores;
    if not sc { return str(r.status); }
    if str(r.kind) == "probe" {
        if "test_pass_pct" in sc { return str(sc["test_pass_pct"]) + "%"; }
        return str(r.status);
    }
    if "avg_sim" in sc { return "sim " + str(sc["avg_sim"]); }
    return str(r.status);
}

# Latest done eval for (model, holdout); `done` is newest-first, so first match wins.
def _match(done: list, mdl: any, h: str) -> any {
    for r in done {
        if r.model == mdl and str(r.holdout) == h { return r; }
    }
    return None;
}

def:pub Evals -> JsxElement {
    has models: list[ModelView] = [],
        kind: str = "probe",
        modelId: str = "",
        modelPath: str = "",
        adapter: str = "",
        holdout: str = "graph",
        limit: str = "",
        simThreshold: str = "0.7",
        history: list = [],
        current: any = None,
        error: str = "",
        loaded: bool = False,
        confirmDel: str = "",
        busy: bool = False;

    async def _refreshList -> None {
        try {
            r = await list_evals();
            history = list(r["evals"]);
        } except Exception as e {
            error = "history load failed · " + str(e);
        }
    }

    async def _poll(cid: str) -> None {
        try {
            d = await get_eval(cid);
        } except Exception { return; }
        if d is None { return; }
        current = d;
        if str(d.status) != "running" {
            await _refreshList();
        }
    }

    async can with entry {
        try {
            ms = await list_models();
            models = ms;
            for m in ms {
                if m.available { modelId = m.id; break; }
            }
            await _refreshList();
        } except Exception as e {
            # Unguarded, this rejected into the void and the panel sat on its
            # empty initial state, looking like a slow load forever.
            error = "eval section failed to load · " + str(e);
        }
        loaded = True;
    }

    # Re-arm the poll timer whenever the active run changes. The id is
    # effect-LOCAL and cleared from the effect's own cleanup: the previous
    # `can with exit` closed over `pollId` from the first render (still None),
    # so it never cleared anything and every remount leaked a 2.5s poller.
    useEffect(lambda {
        iv: any = None;
        c: any = current;
        if c and str(c.status) == "running" {
            cid = str(c.id);
            iv = setInterval(lambda { _poll(cid); }, 2500);
        }
        return lambda { if iv is not None { clearInterval(float(str(iv))); } };
    }, [current]);

    # An armed DEL ("SURE?") disarms itself on Escape, on a pointer-down outside
    # the button, or after 4s — see hooks/useConfirmReset. Without it the armed
    # row stayed armed forever and a later stray click deleted an eval run.
    useConfirmReset(confirmDel, lambda -> None { confirmDel = ""; });

    async def start -> None {
        # No-wasted-call guard, mirroring SourcesStage.addSrc's "path required":
        # create_eval cannot do anything without a model, and the button below is
        # disabled for exactly this case — this is the belt to that suspenders
        # (Enter on a focused control, a stale render, an assistant-driven call).
        if not (modelId or modelPath.strip()) {
            error = "pick a model above, or type a model path, before launching";
            return;
        }
        if not holdout.strip() {
            error = "pick a holdout set before launching";
            return;
        }
        busy = True;
        error = "";
        lim = 0;
        if limit.strip() {
            try { lim = int(limit.strip()); } except Exception { lim = 0; }
        }
        sim = 0.0;
        if kind == "idiom" and simThreshold.strip() {
            try { sim = float(simThreshold.strip()); } except Exception { sim = 0.0; }
        }
        mid = "" if modelPath else modelId;
        try {
            rec = await create_eval(
                kind=kind, model_id=mid, model_path=modelPath,
                adapter=adapter, holdout=holdout, limit=lim, sim_threshold=sim
            );
            if rec is None {
                error = "launch failed — check model / path";
            } else {
                d = await get_eval(str(rec.id));
                current = d;
                await _refreshList();
            }
        } except Exception as e {
            error = "launch failed · " + str(e);
        }
        busy = False;
    }

    async def stopActive -> None {
        c: any = current;
        if not c { return; }
        try {
            await stop_eval(str(c.id));
            d = await get_eval(str(c.id));
            current = d;
        } except Exception as e {
            error = "stop failed · " + str(e);
        }
        await _refreshList();
    }

    # Two-click confirm (first click → SURE?), the app-wide destructive-action
    # pattern — same shape as WorkspaceSettings' DELETE and JmsProjects' card
    # DELETE. An eval run's scores are not reproducible for free, so the one
    # unguarded one-click delete in this surface gets the same friction.
    async def removeEval(id: str) -> None {
        if confirmDel != id { confirmDel = id; return; }
        confirmDel = "";
        try {
            await delete_eval(id);
            c: any = current;
            if c and str(c.id) == id { current = None; }
        } except Exception as e {
            error = "delete failed · " + str(e);
        }
        await _refreshList();
    }

    async def openEval(id: str) -> None {
        try {
            d = await get_eval(id);
            current = d;
        } except Exception as e {
            error = "could not open eval " + id + " · " + str(e);
        }
    }

    def _launch -> JsxElement {
        avail: list[ModelView] = [];
        for m in models {
            if m.available { avail.append(m); }
        }
        # Disabled-with-the-reason-stated, the guard shape GenerateStage uses for
        # DRAFT PLAN (canDraft + hint). `modelId` is auto-picked on mount from the
        # first AVAILABLE model, so it is empty exactly when nothing is installed —
        # LAUNCH was clickable in that state and always failed server-side.
        #
        # Reachability: the MODEL chips and the HOLDOUT Segmented are
        # click-to-deselect — clicking the ACTIVE option clears it back to "".
        # Without that, both pickers were radio-style with a default already
        # selected on mount, so on any machine with a model installed this guard
        # could never fire (correct-but-dead code). The default-on-mount
        # selection is untouched; nothing changes until a user clicks twice.
        hasModel = bool(modelId) or bool(modelPath.strip());
        hasHoldout = bool(holdout.strip());
        why = "";
        if not hasModel {
            why = ("No model selected — pick one above, or type a model path."
                   if len(avail) > 0
                   else "No model available — type a model path, or install a model first.");
        } elif not hasHoldout {
            why = "No holdout set selected — pick FUNCTION or GRAPH above.";
        }
        canLaunch = hasModel and hasHoldout;
        return <div className="relative exp-panel p-4 pt-5">
            <span className="micro-label absolute -top-2 left-3 bg-background px-2">EVAL.LAUNCH</span>
            <div className="flex flex-col gap-4">
                <Field label="KIND">
                    <div className="flex flex-col gap-1">
                        <Segmented options={["probe", "idiom"]} value={kind} onSet={lambda (v: str) { kind = v; }} />
                        <span className="stat-line text-muted-foreground/80">{
                            "behavioral test-pass on holdout" if kind == "probe"
                            else "ROUGE vs transpile judge: idiomatic similarity score"
                        }</span>
                    </div>
                </Field>
                <Field label="MODEL">
                    <div className="flex flex-col gap-2">
                        {len(avail) > 0 and <div className="flex flex-wrap gap-1">
                            {for m in avail {
                                <button
                                    key={str(m.id)}
                                    title={"click again to deselect" if (modelId == m.id and not modelPath) else str(m.id)}
                                    onClick={lambda (e: MouseEvent) {
                                        if modelId == m.id and not modelPath { modelId = ""; }
                                        else { modelId = m.id; modelPath = ""; }
                                    }}
                                    className={"exp-chip !text-xs " + (
                                        "exp-chip-active" if (modelId == m.id and not modelPath)
                                        else ""
                                    )}
                                >
                                    {m.label}
                                </button>
                            }}
                        </div>}
                        <TextInput
                            value={modelPath}
                            onSet={lambda (v: str) { modelPath = v; if v { modelId = ""; } }}
                            placeholder="or model path (models/...)"
                            mono={True}
                        />
                    </div>
                </Field>
                <Field label="ADAPTER (optional)">
                    <TextInput value={adapter} onSet={lambda (v: str) { adapter = v; }} placeholder="e.g. model-experiments/01-sft-dpo/adapters/qwen-probe" mono={True} />
                </Field>
                <Field label="HOLDOUT">
                    <Segmented options={["function", "graph"]} value={holdout} onSet={lambda (v: str) { holdout = "" if holdout == v else v; }} />
                </Field>
                <Field label="LIMIT">
                    <TextInput value={limit} onSet={lambda (v: str) { limit = v; }} placeholder="all" mono={True} />
                </Field>
                {kind == "idiom" and <Field label="SIM THRESHOLD">
                    <TextInput value={simThreshold} onSet={lambda (v: str) { simThreshold = v; }} placeholder="0.7" mono={True} />
                </Field>}
                <button
                    onClick={lambda (e: MouseEvent) { start(); }}
                    disabled={bool(busy or not canLaunch)}
                    title={why if why else "run this eval"}
                    className="exp-btn exp-btn-accent mt-1 w-full"
                >
                    {"LAUNCHING…" if busy else "LAUNCH"}
                </button>
                {why and <span className="stat-line text-muted-foreground/80">{why}</span>}
                {error and <span className="stat-line text-foreground">{error}</span>}
            </div>
        </div>;
    }

    def _scoreTiles(run: any) -> JsxElement {
        sc: any = run.scores;
        if str(run.kind) == "probe" {
            return <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
                <StatTile label="TEST.PASS%" value={_g(sc, "test_pass_pct")} sub="" dim={False} />
                <StatTile label="RUNS%" value={_g(sc, "runs_pct")} sub="" dim={False} />
                <StatTile label="TOK/CORRECT" value={_g(sc, "tokens_to_correct")} sub="" dim={False} />
                <StatTile label="EVAL.TPS" value={_g(sc, "eval_tps")} sub="" dim={False} />
            </div>;
        }
        return <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            <StatTile label="AVG.SIM" value={_g(sc, "avg_sim")} sub="" dim={False} />
            <StatTile label="IDIOMATIC" value={_idiomatic(sc)} sub="" dim={False} />
            <StatTile label="PY.SHAPED" value={_g(sc, "python_shaped")} sub="" dim={False} />
            <StatTile label="FEAT" value={_g(sc, "avg_feat")} sub="" dim={False} />
        </div>;
    }

