<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline';" />
    <title>Accessa</title>
    <style>
      :root { color-scheme: dark; font: 14px system-ui, sans-serif; color: #e8eaed; background: #202124; }
      * { box-sizing: border-box; }
      body { height: 150px; margin: 0; padding: 0 12px 9px; overflow: hidden; border-bottom: 1px solid #17181a; background: #202124; }
      header { display: flex; align-items: center; gap: 10px; height: 39px; }
      h1 { margin: 0; color: #e8eaed; font-size: 13px; font-weight: 600; white-space: nowrap; }
      .browser-mark { display: grid; width: 22px; height: 22px; place-items: center; border-radius: 50%; color: #202124; background: linear-gradient(135deg, #8ab4f8, #81c995); font-size: 12px; font-weight: 800; }
      .tab-strip { display: flex; align-items: end; gap: 4px; height: 34px; margin: 0 -12px; padding: 0 12px; background: #17181a; }
      #tab-list { display: flex; align-items: end; gap: 4px; min-width: 0; }
      .tab { display: flex; align-items: center; gap: 8px; min-width: 180px; max-width: 280px; height: 30px; padding: 0 10px; border: 0; border-radius: 9px 9px 0 0; color: #bdc1c6; background: #202124; font-size: 12px; }
