      button:disabled { opacity: .5; cursor: default; }
      #address { min-width: 120px; flex: 1; border: 1px solid #5f6368; border-radius: 18px; padding: 7px 14px; color: #e8eaed; background: #303134; font: inherit; }
      #address:focus { border-color: #8ab4f8; outline: none; background: #292a2d; }
      #message { display: inline-block; max-width: 56vw; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #9aa0a6; font-size: 12px; vertical-align: middle; }
      #page-title { font-size: 11px; color: #9aa0a6; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1; }
