  <body>
    <div class="tab-strip" aria-label="Browser tabs">
      <div id="tab-list" aria-live="polite"></div>
      <button class="new-tab-icon" id="new-tab-top" type="button" aria-label="New tab">+</button>
    </div>
    <header>
      <span class="browser-mark" aria-hidden="true">A</span>
      <h1>Accessa</h1>
      <span id="bridge-status" data-bridge-status>Connecting bridge…</span>
      <span id="page-title">Starting Chromium…</span>
    </header>
    <form id="navigation">
      <button id="back" type="button" aria-label="Go back">←</button>
      <button id="forward" type="button" aria-label="Go forward">→</button>
      <button id="reload" type="button" aria-label="Reload page">↻</button>
      <input id="address" aria-label="Website address" placeholder="Search Google or enter an address" autocomplete="off" spellcheck="false" />
      <button id="go" type="submit">Go</button>
    </form>
    <div id="tools">
      <button id="snapshot" type="button">Page snapshot</button>
      <button id="experience" type="button">Open accessibility panel</button>
      <button id="undo" type="button" disabled>Undo adaptation</button>
      <span id="message" role="status">The live webpage is isolated in its own Chromium surface.</span>
    </div>
    <script>
      const status = document.querySelector("#message");
      const address = document.querySelector("#address");
      const title = document.querySelector("#page-title");
      const undoButton = document.querySelector("#undo");
      let lastSnapshot;
      let lastUndoToken;
      let requestNumber = 0;

      function requestId() { requestNumber += 1; return `ui_${Date.now()}_${requestNumber}`; }
      function unwrap(result) {
        if (result?.status === "rejected") throw new Error(result.error?.message || result.result || "Request rejected");
        return result;
      }
      async function state() { return unwrap(await window.browser.getBrowserState()); }
      async function command(kind, args = {}, requiresConfirmation = false) {
        const current = await state();
        const tabId = current.activeTabId;
        const result = unwrap(await window.browser.executeBrowserCommand({
          schemaVersion: 1, requestId: requestId(), tabId, kind,
          arguments: args, requiresConfirmation,
        }));
        if (result.status === "rejected" || result.status === "failed") throw new Error(result.message || result.result || "Command failed");
        return result;
      }
      function show(message) { status.textContent = message; }
      function renderTabs(current) {
        const list = document.querySelector("#tab-list");
        list.replaceChildren();
        current.tabs.forEach((tab) => {
          const tabButton = document.createElement("button");
          tabButton.className = `tab${tab.tabId === current.activeTabId ? " active" : ""}`;
          tabButton.type = "button";
          tabButton.setAttribute("aria-current", tab.tabId === current.activeTabId ? "page" : "false");
          tabButton.title = tab.title || tab.url || "New tab";
          const dot = document.createElement("span"); dot.className = "tab-dot";
          const label = document.createElement("span"); label.className = "tab-title"; label.textContent = tab.title || tab.url || "New tab";
          const close = document.createElement("span"); close.className = "tab-close"; close.textContent = "×";
          tabButton.append(dot, label, close);
          tabButton.addEventListener("click", async (event) => {
            if (event.target === close) {
              event.stopPropagation();
              try {
                if (tab.tabId !== current.activeTabId) await command("switch_tab", { tabId: tab.tabId });
                await command("close_tab", {}, true);
                updateShellState();
                show("Tab closed.");
              }
              catch (error) { show(error.message); }
              return;
            }
            try { await command("switch_tab", { tabId: tab.tabId }); updateShellState(); }
            catch (error) { show(error.message); }
          });
          list.append(tabButton);
        });
      }
      function updateShellState() {
        window.browser.getBrowserState().then(unwrap).then((current) => {
          renderTabs(current);
          const active = current.tabs.find((tab) => tab.tabId === current.activeTabId);
          if (active) { address.value = active.url; title.textContent = active.title || active.url; }
        }).catch((error) => show(error.message));
      }

      document.querySelector("#navigation").addEventListener("submit", async (event) => {
        event.preventDefault();
        try { await command("navigate", { url: address.value }); show("Opening page…"); }
        catch (error) { show(error.message); }
      });
      document.addEventListener("keydown", (event) => {
        if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "l") {
          event.preventDefault();
          address.focus();
          address.select();
        }
      });
      document.querySelector("#back").addEventListener("click", () => command("back").catch((error) => show(error.message)));
      document.querySelector("#forward").addEventListener("click", () => command("forward").catch((error) => show(error.message)));
      document.querySelector("#reload").addEventListener("click", () => command("reload").catch((error) => show(error.message)));
      document.querySelector("#new-tab-top").addEventListener("click", async () => {
        try { await command("new_tab"); address.value = ""; updateShellState(); show("New tab opened."); }
        catch (error) { show(error.message); }
      });

      document.querySelector("#snapshot").addEventListener("click", async () => {
        try {
          lastSnapshot = unwrap(await window.browser.getActivePageSnapshot());
          title.textContent = `${lastSnapshot.title || lastSnapshot.url} · ${lastSnapshot.elements.length} visible elements`;
          address.value = lastSnapshot.url;
          show(`Snapshot ${lastSnapshot.snapshotId}; revision ${lastSnapshot.pageRevision}. ${lastSnapshot.contentSummary.slice(0, 190)}`);
        } catch (error) { show(`Snapshot failed: ${error.message}`); }
      });
      document.querySelector("#experience").addEventListener("click", async () => {
        try {
          unwrap(await window.browser.openAccessibilityExperience());
          show("Accessibility panel opened. Use Jac to preview, apply, undo, and save changes.");
        } catch (error) { show(`Accessibility panel failed: ${error.message}`); }
      });
      undoButton.addEventListener("click", async () => {
        try {
          const result = unwrap(await window.browser.undoAdaptation(lastUndoToken));
          lastUndoToken = undefined;
          undoButton.disabled = true;
          show(result.result);
        } catch (error) { show(`Undo failed: ${error.message}`); }
      });

      window.browser.onPageChanged((event) => {
        if (event.tabId !== lastSnapshot?.tabId || event.pageRevision !== lastSnapshot?.pageRevision) {
          lastUndoToken = undefined;
          undoButton.disabled = true;
        }
        if (event.url) address.value = event.url;
        if (event.title) { title.textContent = event.title; }
        if (event.reason?.includes("error")) show(event.reason);
        else if (event.reason === "navigation") show("Loading page…");
        else if (event.reason === "loaded") show("Page loaded. Snapshot or adjust text using the controls above.");
        updateShellState();
      });
      updateShellState();
    </script>
  </body>
</html>

