def respawn(t: Target) {
    t.x = rand_range(-14.0, 14.0);
    t.base_y = rand_range(1.0, 5.0);
    t.z = rand_range(-16.0, 2.0);
    t.phase = rand_range(0.0, 6.28);
    t.y = t.base_y;
    t.alive = True;
}

"""Fire a bullet from the eye along the current aim, reusing a dead pool slot."""
def fire(bullets: list[Bullet]) -> None {
    yaw_r = yaw * DEG2RAD;
    pitch_r = pitch * DEG2RAD;
    cp = jcos(pitch_r);
    dx = -jsin(yaw_r) * cp;
    dy = jsin(pitch_r);
    dz = -jcos(yaw_r) * cp;
    speed = 40.0;
    i = 0;
    while i < len(bullets) {
        b = bullets[i];
        if b.life <= 0.0 {
            b.x = px;
            b.y = py;
            b.z = pz;
            b.vx = dx * speed;
            b.vy = dy * speed;
            b.vz = dz * speed;
            b.life = 2.0;
            return;
        }
        i += 1;
    }
}

"""Advance bullets, resolve hits against targets, and tally score."""
def update_bullets(bullets: list[Bullet], targets: list[Target], step: float) {
    bi = 0;
    while bi < len(bullets) {
        b = bullets[bi];
        if b.life > 0.0 {
            b.x += b.vx * step;
            b.y += b.vy * step;
            b.z += b.vz * step;
            b.life -= step;
            ti = 0;
            while ti < len(targets) {
                t = targets[ti];
                if t.alive {
                    ddx = b.x - t.x;
                    ddy = b.y - t.y;
                    ddz = b.z - t.z;
                    if ddx * ddx + ddy * ddy + ddz * ddz < 1.4 {
                        t.alive = False;
                        b.life = 0.0;
                        score += 1;
                        respawn(t);
                    }
                }
                ti += 1;
            }
        }
        bi += 1;
    }
}

"""Read keyboard + mouse and update camera orientation + position this frame."""
def handle_input(step: float) {
    turn = 90.0 * step;

    if key_tapped(KEY_TAB) {
        if mouse_captured {
            unlock_mouse();
            mouse_captured = False;
        } else {
            lock_mouse();
            mouse_captured = True;
            mouse_warmup = 8;
        }
    }
    if not mouse_captured and mouse_pressed(MOUSE_LEFT) {
        lock_mouse();
        mouse_captured = True;
        mouse_warmup = 8;
    }

    if key_held(KEY_LEFT) {
        yaw += turn;
    }
    if key_held(KEY_RIGHT) {
        yaw -= turn;
    }
    if key_held(KEY_UP) {
        pitch += turn;
    }
    if key_held(KEY_DOWN) {
        pitch -= turn;
    }

    if mouse_captured {
        mx = mouse_x();
        my = mouse_y();
        if mouse_warmup > 0 {
            mouse_warmup -= 1;
        } else {
            ddx = mx - prev_mx;
            ddy = my - prev_my;
            if ddx < 150.0 and ddx > -150.0 and ddy < 150.0 and ddy > -150.0 {
                yaw -= ddx * mouse_sens;
                pitch -= ddy * mouse_sens;
            }
        }
        prev_mx = mx;
        prev_my = my;
    }

    if pitch > 85.0 {
        pitch = 85.0;
    }
    if pitch < -85.0 {
        pitch = -85.0;
    }

    yaw_r = yaw * DEG2RAD;
    fwd_x = -jsin(yaw_r);
    fwd_z = -jcos(yaw_r);
    rgt_x = jcos(yaw_r);
    rgt_z = -jsin(yaw_r);
    move = 8.0 * step;
    if key_held(KEY_W) {
        px += fwd_x * move;
        pz += fwd_z * move;
    }
    if key_held(KEY_S) {
        px -= fwd_x * move;
        pz -= fwd_z * move;
    }
    if key_held(KEY_D) {
        px += rgt_x * move;
        pz += rgt_z * move;
    }
    if key_held(KEY_A) {
        px -= rgt_x * move;
        pz -= rgt_z * move;
    }
}

glob targets: list[Target] = [],
     bullets: list[Bullet] = [];

# ─── Browser entry points (replace the native `with entry` loop) ─────────────
"""Set up the window and object pools. Call once before the first frame()."""
def init {
    open_window(960, 600, "Jac Cube Shooter");
    for n in range(7) {
        t = Target(x=0.0, y=0.0, z=0.0, base_y=0.0, phase=0.0, alive=False);
        respawn(t);
        targets.append(t);
    }
    for n in range(24) {
        bullets.append(
            Bullet(x=0.0, y=0.0, z=0.0, vx=0.0, vy=0.0, vz=0.0, life=0.0)
        );
    }
}

"""Advance and render one frame. Returns True when the game wants to close."""
def frame -> bool {
    step = dt();
    world_t += step;
    handle_input(step);
    fire_cd -= step;
    if key_held(KEY_SPACE) and fire_cd <= 0.0 {
        fire(bullets);
        fire_cd = 0.14;
    }
    update_bullets(bullets, targets, step);
    ti = 0;
    while ti < len(targets) {
        t = targets[ti];
        t.y = t.base_y + 0.4 * jsin(world_t * 1.5 + t.phase);
        ti += 1;
    }
    begin_frame(15, 18, 28);
    set_camera(px, py, pz, yaw, pitch, 1.6);
    draw_floor(20, 1.5);
    ti = 0;
    while ti < len(targets) {
        t = targets[ti];
        if t.alive {
            draw_box(t.x, t.y, t.z, 1.4, 1.4, 1.4, 235, 80, 60);
        }
        ti += 1;
    }
    bi = 0;
    while bi < len(bullets) {
        b = bullets[bi];
        if b.life > 0.0 {
            draw_box(b.x, b.y, b.z, 0.22, 0.22, 0.22, 250, 220, 90);
        }
        bi += 1;
    }
    end_camera(960.0, 600.0);
    draw_fps(10, 10);
    end_frame();
    return should_close();
}

"""Current score (targets destroyed) - for an HTML/`sv` HUD."""
def get_score -> int {
    return score;
}

