def spawn_detached(cmd: str, runlog: Path, env: dict, cwd: Path) -> int {
    if _count_running_jobs() >= _max_concurrent_jobs() {
        raise ValueError("concurrent job limit reached");
    }
    runlog.parent.mkdir(parents=True, exist_ok=True);
    logf: any = open(runlog, "a");
    proc: any = None;
    try {
        proc = Popen(
            cmd, shell=True, start_new_session=True,
            stdout=logf, stderr=STDOUT, cwd=str(cwd), env={**os.environ, **env}
        );
    } finally {
        logf.close();
    }
    pid = int(str(proc.pid));
    audit.log("job_spawn", {"pid": pid, "cwd": str(cwd), "runlog": str(runlog)});
    return pid;
}

"""Read-only cross-app job snapshot for the global activity indicator in the top
bar. The app launches multi-hour detached GPU jobs and the user moves between 4
workspaces and 2 surfaces, so without this there is no signal that anything is
running once you navigate away from the section that started it.

Reuses the existing helpers only — no new state, no writes, and it never touches
the heavy lock's guard file (so it cannot contend with a real acquire).
`heavy` is the current holder's label, "" when the GPU slot is free.
# ponytail: ceiling — `running` rglob's the caller's results tree (same cost as
# the pre-existing `_count_running_jobs`), so poll it on the order of seconds, not
# continuously. If the tree grows enough to matter, keep a counter in the lock file."""
def active_jobs() -> dict {
    running = 0;
    try {
        running = _count_running_jobs();
    } except Exception { running = 0; }
    heavy = "";
    try {
        cur = read_job(_heavy_lock_file());
        if cur is not None and _heavy_live(cur) {
            heavy = str(cur.get("holder", ""));
        }
    } except Exception { heavy = ""; }
    return {"running": running, "heavy": heavy};
}

# file: jobs.test.jac
"""studio - unit tests for the heavy-job GPU lock in jobs.sv.jac.

Covers the single-slot mutual exclusion that guarantees only one heavy local job
(training / CPT / builder / eval / RL generate) runs at a time on the shared GPU:
a clean acquire, the busy path (correct busy_with), release-then-reacquire, and
self-healing of a stale lock left by a crashed in-process holder.

The lock file lives at a REAL path (models.results_dir()/.heavy-lock.json), so
each test unlinks it before and after to stay hermetic and never clobber a live
lock. Annex file: pairs with jobs.sv.jac. Run with `jac test jobs.test.jac`.
"""

test "heavy_acquire succeeds on an empty slot" {
    lf = _heavy_lock_file();
    try { lf.unlink(); } except Exception {}
    g = heavy_acquire("test:a");
    assert g["ok"], g;
    try { lf.unlink(); } except Exception {}
}

test "a second heavy_acquire is busy with the current holder" {
    lf = _heavy_lock_file();
    try { lf.unlink(); } except Exception {}
    g1 = heavy_acquire("test:first");
    assert g1["ok"], g1;
    g2 = heavy_acquire("test:second");
    assert not g2["ok"], g2;
    assert g2["busy_with"] == "test:first", g2;
    try { lf.unlink(); } except Exception {}
}

test "release frees the slot for a competing holder" {
    lf = _heavy_lock_file();
    try { lf.unlink(); } except Exception {}
    assert heavy_acquire("test:holder")["ok"];
    assert not heavy_acquire("test:other")["ok"];   # blocked while held
    heavy_release("test:holder");
    g = heavy_acquire("test:other");
    assert g["ok"], g;
    try { lf.unlink(); } except Exception {}
}

test "a stale lock (dead pid, no job file) self-heals" {
    lf = _heavy_lock_file();
    try { lf.unlink(); } except Exception {}
    # A crashed in-process holder: a pid that is not alive and no job file to
    # resolve against. The next acquire must find it not-live and steal the slot.
    write_job(lf, {
        "holder": "test:dead", "job_file": "", "runlog": "",
        "pid": 999999, "stamp": "", "started": "old"
    });
    g = heavy_acquire("test:fresh");
    assert g["ok"], g;
    cur = read_job(lf);
    assert cur is not None and str(cur.get("holder", "")) == "test:fresh", cur;
    try { lf.unlink(); } except Exception {}
}

