    --accent: #F1ECE3;
    --accent-foreground: #14120F;
    --destructive: #C81E3C;         /* crimson — must not read as brand ember */
    --border: #E6DDCC;              /* visible on both paper and muted surfaces */
    --input: #E2DACC;
