def:pub CommunityDonations() -> JsxElement {
    has donations: list[DonationItem] = [];
    has organizations: list[str] = [];
    has title: str = "";
    has description: str = "";
    has donor: str = "";
    has amount: str = "";
    has organization: str = "";
    has loading: bool = True;
    has notice: str = "";
    has error_text: str = "";
    has submitting: bool = False;
    has claiming_id: str = "";
    has claimant_name: str = "";
    has claim_time: str = "";
    async can with entry {
        try {
            donations = await list_donations();
            org_options: list[str] = await list_organizations();
            organizations = org_options;
            if len(org_options) > 0 { organization = org_options[0]; }
        } except Exception { error_text = "The community board is unavailable. Please refresh and try again."; }
        loading = False;
    }
    def handle_title(e: ChangeEvent) { title = e.target.value; }
    def handle_description(e: ChangeEvent) { description = e.target.value; }
    def handle_donor(e: ChangeEvent) { donor = e.target.value; }
    def handle_amount(e: ChangeEvent) { amount = e.target.value; }
    def handle_claimant_name(e: ChangeEvent) { claimant_name = e.target.value; }
    def handle_claim_time(e: ChangeEvent) { claim_time = e.target.value; }
    async def add_donation(e: FormEvent) -> None {
        e.preventDefault();
        if title.strip() == "" or amount.strip() == "" { notice = "Add a donation name and estimated value to continue."; return; }
        if organization == "" { notice = "No organizations are registered yet. Please try again later."; return; }
        item: DonationItem | None = await submit_donation(title, description, donor, float(amount), organization);
        if item is None { notice = "This organization is no longer available. Refresh and choose another organization."; return; }
        donations = donations + [item];
        title = ""; description = ""; donor = ""; amount = "";
        notice = "Your donation was sent to " + organization + " for approval. It will appear on the community board once approved.";
    }
    async def claim_item(donation_id: str) {
        if claimant_name.strip() == "" or claim_time.strip() == "" {
            notice = "Enter your name and the time you would like to collect this donation.";
            return;
        }
        claimed: bool = await claim_donation(donation_id, claimant_name, claim_time);
        if claimed {
            fresh_items: list[DonationItem] = await list_donations();
            donations = fresh_items;
            claiming_id = "";
            claimant_name = "";
            claim_time = "";
            notice = "Donation claimed. Your name and requested pickup time were sent to the organization.";
        } else { notice = "This donation is no longer available to claim."; }
    }
    available = len([item for item in donations if item.approved and not item.claimed]);
    return <div className="min-h-svh bg-muted/40">
        <header className="sticky top-0 z-10 border-b bg-background/95 backdrop-blur"><div className="mx-auto flex min-h-16 max-w-7xl flex-wrap items-center gap-5 px-5 sm:px-8"><Link to="/donate" className="flex items-center gap-2.5 text-base font-semibold tracking-tight"><span className="flex size-9 items-center justify-center rounded-lg bg-primary text-primary-foreground">G</span>GiveTogether</Link><nav className="flex flex-1 flex-wrap items-center gap-1"><Link to="/dashboard" className="rounded-md px-3 py-2 text-sm text-muted-foreground transition-colors hover:bg-muted hover:text-foreground">Organization dashboard</Link><Link to="/donate" className="rounded-md bg-primary/10 px-3 py-2 text-sm font-medium text-primary">Give or claim</Link><Link to="/login" className="ml-auto rounded-md px-3 py-2 text-sm text-muted-foreground transition-colors hover:bg-muted hover:text-foreground">Organization sign in</Link></nav></div></header>
        <main className="mx-auto flex w-full max-w-7xl flex-col gap-7 px-5 py-8 sm:px-8">
            <div className="flex flex-col gap-2"><p className="text-sm font-medium text-primary">COMMUNITY EXCHANGE</p><h1 className="text-3xl font-semibold tracking-tight">Good things, passed along.</h1><p className="max-w-2xl text-sm leading-relaxed text-muted-foreground">Share something useful with a neighbor, or find a gift that could make a difference today.</p></div>
            {notice != "" and <div role="status" className="rounded-lg border border-primary/20 bg-primary/5 px-4 py-3 text-sm text-primary">{notice}</div>}
            <div className="grid items-start gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.7fr)]">
                <Card className="shadow-sm"><CardHeader><CardTitle>Give something</CardTitle><CardDescription>Choose an organization to review your contribution before it is shared.</CardDescription></CardHeader><CardContent><form onSubmit={add_donation} className="flex flex-col gap-4">
                    <label htmlFor="donation-organization" className="flex flex-col gap-2 text-sm font-medium">Organization<select id="donation-organization" value={organization} onChange={lambda (e: ChangeEvent) { organization = e.target.value; }} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm">{for org_name in organizations {<option key={org_name} value={org_name}>{org_name}</option>}}</select></label>
                    <label className="flex flex-col gap-2 text-sm font-medium">Donation name<Input placeholder="Winter coat, grocery card..." value={title} onChange={handle_title} /></label>
                    <label className="flex flex-col gap-2 text-sm font-medium">What should someone know?<Input placeholder="Size, condition, or helpful details" value={description} onChange={handle_description} /></label>
                    <label className="flex flex-col gap-2 text-sm font-medium">Your name <span className="font-normal text-muted-foreground">(optional)</span><Input placeholder="Leave blank to give anonymously" value={donor} onChange={handle_donor} /></label>
                    <label className="flex flex-col gap-2 text-sm font-medium">Estimated value in dollars<Input type="number" min="0" step="0.01" placeholder="25.00" value={amount} onChange={handle_amount} /></label>
                    <Button type="submit" className="mt-1 h-10 shadow-sm">Send donation for approval</Button>
                </form></CardContent></Card>
                <Card className="shadow-sm"><CardHeader className="flex flex-row items-start justify-between gap-4 border-b"><div className="flex flex-col gap-1"><CardTitle>Available for neighbors</CardTitle><CardDescription>{str(available)} approved donations ready to be claimed.</CardDescription></div><Badge variant="secondary">Community board</Badge></CardHeader><CardContent className="p-0">
                    {if loading { <p className="p-8 text-sm text-muted-foreground">Loading community donations...</p>; }}
