                    {if not loading and error_text == "" and available == 0 { <div className="flex flex-col items-center gap-2 p-12 text-center"><span className="text-lg font-medium">Nothing waiting to be claimed</span><p className="max-w-md text-sm text-muted-foreground">Approved donations will appear here. Contributions are reviewed by the organization first.</p></div>; }}
                    {if not loading and error_text == "" and available > 0 { <div className="divide-y">{for item in donations {if item.approved and not item.claimed {<article key={jid(item)} className="flex flex-col gap-4 p-5"><div className="flex flex-col gap-1.5"><h2 className="text-base font-semibold">{item.title}</h2><p className="text-sm leading-relaxed text-muted-foreground">{item.description}</p><p className="text-xs text-muted-foreground">For {item.organization} · Shared by {item.donor}</p><span className="text-sm font-medium tabular-nums">Estimated value: ${f"{item.amount:.2f}"}</span></div>{if claiming_id == jid(item) {<div className="grid gap-3 rounded-lg border bg-muted/30 p-4 sm:grid-cols-2"><label className="flex flex-col gap-2 text-sm font-medium">Your name<Input placeholder="Name for the organization" value={claimant_name} onChange={handle_claimant_name} /></label><label className="flex flex-col gap-2 text-sm font-medium">Requested pickup time<Input type="text" placeholder="e.g. Friday at 3:30 PM" value={claim_time} onChange={handle_claim_time} /></label><div className="flex flex-wrap items-center gap-2 sm:col-span-2"><Button type="button" size="sm" onClick={lambda { claim_item(jid(item)); }}>Confirm claim</Button><Button variant="outline" size="sm" onClick={lambda { claiming_id = ""; claimant_name = ""; claim_time = ""; }}>Cancel</Button></div></div>} else {<Button variant="outline" size="sm" className="self-start" onClick={lambda { claiming_id = jid(item); }}>Claim donation</Button>}}</article>}}}</div>; }}
