cl import from "@jac/runtime" { Link, Outlet, useLocation, jacIsLoggedIn, jacLogout, useNavigate }
cl {
    def:pub layout -> JsxElement {
        location = useLocation();
        navigate = useNavigate();

        def path_of(loc: any) -> str {
            return str(loc.pathname if hasattr(loc, "pathname") else "/");
        }

        def handleLogout(e: any) -> None {
            e.preventDefault();
            jacLogout();
            # Full reset: a hard reload drops every page's in-memory state so
            # the app lands on a truly fresh home, exactly like first visit.
            window.location.href = "/";
        }

        loggedIn = jacIsLoggedIn();

        can with entry {
            document.title = "PlateMate";
            # Favicon: the PlateMate logo (same image as the nav bar).
            if not document.querySelector("link[rel='icon']") {
                head_el: any = document.head;
                link_el: any = document.createElement("link");
                link_el.setAttribute("rel", "icon");
                link_el.setAttribute("type", "image/png");
                link_el.setAttribute("href", "/compiled/assets/PlateMate-logo.png");
                head_el.appendChild(link_el);
            }
        }

        # Organizations tab is member-only: it needs a logged-in account to
        # make sense (browse as a donor, or manage as an organization).
        links: list = [
            ("/", "Home"),
            ("/available", "Available Food"),
            ("/donate", "Donate Food")
        ];
        if loggedIn {
            links.append(("/organizations", "Organizations"));
        }

        return
            <div className="fb-shell">
                <nav className="fb-nav">
                    <Link to="/" className="fb-logo">
                        <img className="fb-logo-img" src="/compiled/assets/PlateMate-logo.png" alt="PlateMate"/>
                    </Link>
                    {[
                        <Link
                            key={l[0]}
                            to={l[0]}
                            className={"fb-navlink" + (" active" if path_of(location) == l[0] else "")}
                        >
                            {l[1]}
                        </Link> for l in links
                    ]}
                    {loggedIn and (
                        <span className="btn-row">
                            <Link to="/my_reservations" className="fb-navlink">My Reservations</Link>
                            <Link to="/organization_dashboard" className="fb-navlink">Org Dashboard</Link>
                            <button className="fb-navbtn" onClick={handleLogout}>Log out</button>
                        </span>
                    ) or (
                        <span className="btn-row">
                            <Link to="/login" className="fb-navlink">Login</Link>
                            <Link to="/signup" className="fb-navbtn solid">Sign Up</Link>
                        </span>
                    )}
                </nav>
                <main className="fb-main">
                    <Outlet/>
                </main>
                <footer className="fb-footer">
                    <div className="mascot-row small">
                        <span className="mascot-plate"><img className="mascot" src="/compiled/assets/mascots/carrot.png" alt="carrot"/></span>
                        <span className="mascot-plate"><img className="mascot" src="/compiled/assets/mascots/apple.png" alt="apple"/></span>
                        <span className="mascot-plate"><img className="mascot" src="/compiled/assets/mascots/banana.png" alt="banana"/></span>
                    </div>
                    <div>PlateMate - neighbors feeding neighbors, one plate at a time.</div>
                    <div className="fb-note">Built with Jac for JacHacks. Leave a little, take a little.</div>
                </footer>
            </div>;
    }
}

# file: pages/login.jac
cl import from "react" { useState }
cl import from "@jac/runtime" { Link, useNavigate, jacLogin }

sv import from ..endpoints { GetProfile, CompleteProfile }

"""Login page."""
cl {
    def:pub page -> JsxPage {
        (username, set_username) = useState("");
        (password, set_password) = useState("");
        (error, set_error) = useState("");
        navigate = useNavigate();

        async def submit(e: any) -> None {
            e.preventDefault();
            set_error("");
            uname = str(username).strip();
            if not uname or not password {
                set_error("Please fill in every field, neighbor.");
                return;
            }
            ok = await jacLogin(uname, str(password));
            if ok {
                prof = root spawn GetProfile();
                r = "";
                for p in prof.reports {
                    if p is not None {
                        r = str(p.get("role", ""));
                    }
                }
                if r == "" {
                    # Account predates the profile step (or was never finished)
                    # - heal it with a default Neighbor profile, then re-read.
                    root spawn CompleteProfile(role="RECIPIENT", display_name=uname);
                    prof = root spawn GetProfile();
                    for p in prof.reports {
                        if p is not None {
                            r = str(p.get("role", ""));
                        }
                    }
                }
                if r == "ORGANIZATION" {
                    navigate("/organization_dashboard");
                } else {
                    navigate("/");
                }
            } else {
                set_error("That name and password don't match our board. Try again?");
            }
        }

        return
            <div className="fb-form">
                <h2>Welcome back, neighbor</h2>
                <p className="fb-note">Sign in to claim food, donate, or review submissions.</p>
                <form onSubmit={submit}>
                    <div className="fb-field">
                        <label>Name or username</label>
                        <input value={username} onChange={lambda e: ChangeEvent { set_username(e.target.value); }} placeholder="e.g. nia_on_cedar"/>
                    </div>
                    <div className="fb-field">
                        <label>Password</label>
                        <input type="password" value={password} onChange={lambda e: ChangeEvent { set_password(e.target.value); }} placeholder="a little secret"/>
                    </div>
                    {error and <div className="fb-error">{error}</div>}
                    <div className="btn-row">
                        <button type="submit" className="btn primary">Log in</button>
                        <Link to="/signup" className="btn">New here? Sign up</Link>
                    </div>
                </form>
            </div>;
    }
}

# file: pages/my_reservations.jac
cl import from "react" { useState }
cl import from "@jac/runtime" { Link, jacIsLoggedIn }

sv import from ..endpoints { ListMyReservations, CancelReservation, MarkPickedUp }

"""Cozy status labels."""
cl {
    def status_label(status: str) -> str {
        if status == "RESERVED" {
            return "Heading your way";
        }
        if status == "PICKED_UP" {
            return "Picked up!";
        }
        if status == "CANCELLED" {
            return "Cancelled";
        }
        return "Expired";
    }

    def status_class(status: str) -> str {
        if status == "RESERVED" {
            return "reserved";
        }
        if status == "PICKED_UP" {
            return "picked";
        }
        if status == "CANCELLED" {
            return "cancelled";
        }
        return "";
    }
}

"""My Reservations page."""
cl {
    def:pub page -> JsxPage {
        (items, set_items) = useState([] as list[dict]);
        (loaded, set_loaded) = useState(False);
        (toast, set_toast) = useState("");

        async def load -> None {
            if not jacIsLoggedIn() {
                set_loaded(True);
                return;
            }
            result = root spawn ListMyReservations();
            fresh: list[dict] = [];
            for x in result.reports {
                if x is not None {
                    fresh.append(x as dict);
                }
            }
            set_items(fresh);
            set_loaded(True);
        }

        can with entry {
            load();
        }

        async def cancel(code: str) -> None {
            root spawn CancelReservation(code=str(code));
            set_toast("Reservation " + str(code) + " cancelled - the servings are back on the table.");
            load();
        }

        async def picked_up(code: str) -> None {
            root spawn MarkPickedUp(code=str(code));
            set_toast("Enjoy! Marked " + str(code) + " as picked up.");
            load();
        }

        def render_row(r: dict) -> JsxElement {
            status = str(r.get("status", ""));
            return
                <div className="fb-row pop-in" key={str(r.get("code", ""))}>
                    <img className="thumb" src={str(r.get("image_url", ""))} alt={str(r.get("food_name", ""))}/>
                    <div className="grow">
                        <h3>{str(r.get("food_name", ""))}</h3>
                        <div className="fb-meta">
                            {str(r.get("servings", "")) + " servings - " + str(r.get("org_name", ""))}
                        </div>
                        <div className="fb-meta">{str(r.get("org_address", ""))}</div>
                        <div className="fb-meta">{"Pickup hours: " + str(r.get("pickup_hours", ""))}</div>
                        <div className="fb-meta">{"Reserved " + str(r.get("reserved_at", ""))}</div>
                        <div style={{"color": "var(--tomato)", "fontWeight": "bold", "letterSpacing": "0.1em"}}>
                            {str(r.get("code", ""))}
                        </div>
                    </div>
                    <div style={{"textAlign": "right"}}>
                        <span className={"badge " + status_class(status)}>
                            {status_label(status)}
                        </span>
                        {status == "RESERVED" and (
                            <div className="btn-row" style={{"marginTop": "0.6rem"}}>
                                <button className="btn small leaf" onClick={lambda { picked_up(str(r.get("code", ""))); }}>Picked up!</button>
                                <button className="btn small" onClick={lambda { cancel(str(r.get("code", ""))); }}>Cancel</button>
                            </div>
                        )}
                    </div>
                </div>;
        }

        def render_rows -> list {
            rows: list = [];
            for r in (items as list[dict]) {
                rows.append(render_row(r));
            }
            return rows;
        }

        n_items = 0;
        if loaded {
            n_items = len(items as list[dict]);
        }

        if loaded and not jacIsLoggedIn() {
            return
                <div className="fb-form" style={{"textAlign": "center"}}>
                    <h2>My Reservations</h2>
                    <p className="fb-note">Log in to see the food waiting for you.</p>
                    <div className="btn-row" style={{"justifyContent": "center", "marginTop": "0.6rem"}}>
                        <Link to="/login" className="btn primary">Log in</Link>
                        <Link to="/signup" className="btn leaf">Sign up</Link>
                    </div>
                </div>;
        }

        return
            <div>
                <div className="fb-section">
                    <h2>My Reservations</h2>
                    <span className="hint">Food with your name on it, neighbor.</span>
                </div>

                {loaded and n_items == 0 and (
                    <div className="fb-empty">
                        <div className="mascot-row small">
                            <span className="mascot-plate"><img className="mascot" src="/compiled/assets/mascots/orange.png" alt="orange"/></span>
                            <span className="mascot-plate"><img className="mascot" src="/compiled/assets/mascots/banana.png" alt="banana"/></span>
                        </div>
                        Nothing reserved yet. Browse <Link to="/available">Available Food</Link> and
                        claim something tasty.
                    </div>
                )}

                {not loaded and <div className="fb-loading">Checking the pickup shelf...</div>}

                <div className="fb-list">{render_rows()}</div>

                {toast and <div className="fb-toast">{toast}</div>}
            </div>;
    }
}

