.flair-phrase-cycle {
  position: relative;
  min-height: 2.5rem;
}

.flair-phrase-cycle span {
  animation: flair-phrase-cycle 12.5s infinite;
  inset: 0;
  opacity: 0;
  position: absolute;
  width: 100%;
}

.flair-phrase-cycle span:nth-child(2) {
  animation-delay: 2.5s;
}

.flair-phrase-cycle span:nth-child(3) {
  animation-delay: 5s;
}

.flair-phrase-cycle span:nth-child(4) {
  animation-delay: 7.5s;
}

.flair-phrase-cycle span:nth-child(5) {
  animation-delay: 10s;
}

@keyframes flair-phrase-cycle {
  0% {
    opacity: 0;
    transform: translateY(8px);
  }
  7%,
  18% {
    opacity: 1;
    transform: translateY(0);
  }
  25%,
  100% {
    opacity: 0;
    transform: translateY(-8px);
  }
}

