@import url("https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600&family=Geist+Mono:wght@400;500&display=swap");

/* Sherry web — global styles.
   Stark ink-on-near-white system: Geist for everything narrative, Geist Mono
   for technical labels, hairline cards with stacked shadows, and a multi-color
   mesh gradient used only at hero scale (the sign-in screen).
   Tokens first; light is the default, dark follows the OS preference. */

:root {
  /* Surfaces */
  --canvas: #ffffff;
  --canvas-soft: #fafafa;
  --canvas-soft-2: #f5f5f5;
  --hairline: #ebebeb;
  --hairline-strong: #a1a1a1;

  /* Text */
  --ink: #171717;
  --body: #4d4d4d;
  --mute: #888888;

  /* Action */
  --primary: #171717;
  --primary-hover: #383838;
  --on-primary: #ffffff;
  --link: #0070f3;
  --link-deep: #0761d1;
  --link-soft: #d3e5ff;
  --focus: #0070f3;

  /* Semantic (success doubles as the link blue) */
  --ok: #0070f3;
  --ok-soft: #d3e5ff;
  --warn: #ab570a;
  --warn-soft: #ffefcf;
  --danger: #ee0000;
  --danger-deep: #c50000;
  --danger-soft: #f7d4d6;

  /* Elevation: inset hairline ring + stacked small offsets */
  --ring: 0 0 0 1px rgba(0, 0, 0, 0.08);
  --shadow-1: var(--ring);
  --shadow-2: 0 1px 1px rgba(0, 0, 0, 0.02), 0 2px 2px rgba(0, 0, 0, 0.04), var(--ring);
  --shadow-3: 0 2px 2px rgba(0, 0, 0, 0.04), 0 8px 8px -8px rgba(0, 0, 0, 0.04), var(--ring);
  --shadow-4: 0 2px 2px rgba(0, 0, 0, 0.04), 0 8px 16px -4px rgba(0, 0, 0, 0.04), var(--ring);
  --shadow-5: 0 1px 1px rgba(0, 0, 0, 0.02), 0 8px 16px -4px rgba(0, 0, 0, 0.04),
    0 24px 32px -8px rgba(0, 0, 0, 0.06), var(--ring);

  /* Shape */
  --r-sm: 6px;
  --r-md: 8px;
  --r-lg: 12px;
  --r-pill: 100px;

  /* Type */
  --font: "Geist", "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --mono: "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, monospace;

  /* Platform chips — drawn from the brand palette */
  --p-web: #4d4d4d;
  --p-desktop: #7928ca;
  --p-mobile: #eb367f;
  --p-chatgpt: #1a9a7d;
  --p-claude: #ab570a;
  --p-gemini: #0070f3;
  --p-codex: #171717;
  --p-antigravity: #4c2889;

  /* Hero mesh (develop → preview → ship) */
  --mesh-a: #007cf0;
  --mesh-b: #00dfd8;
  --mesh-c: #7928ca;
  --mesh-d: #ff0080;
  --mesh-e: #ff4d4d;
  --mesh-f: #f9cb28;
  --mesh-opacity: 0.55;

  /* Dashboard accent (card arrows) */
  --accent: #6e56cf;
  --track: #f0f0f0;

  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
  :root {
    --canvas: #0a0a0a;
    --canvas-soft: #000000;
    --canvas-soft-2: #1a1a1a;
