def handle_input(step: float) {
    turn = 90.0 * step;

    if key_tapped(KEY_TAB) {
        if mouse_captured {
            unlock_mouse();
            mouse_captured = False;
        } else {
            lock_mouse();
            mouse_captured = True;
            mouse_warmup = 8;
        }
    }
    if not mouse_captured and mouse_pressed(MOUSE_LEFT) {
        lock_mouse();
        mouse_captured = True;
        mouse_warmup = 8;
    }

    if key_held(KEY_LEFT) {
        yaw += turn;
    }
    if key_held(KEY_RIGHT) {
        yaw -= turn;
    }
    if key_held(KEY_UP) {
        pitch += turn;
    }
    if key_held(KEY_DOWN) {
        pitch -= turn;
    }

    if mouse_captured {
        mx = mouse_x();
        my = mouse_y();
        if mouse_warmup > 0 {
            mouse_warmup -= 1;
        } else {
            ddx = mx - prev_mx;
            ddy = my - prev_my;
            if ddx < 150.0 and ddx > -150.0 and ddy < 150.0 and ddy > -150.0 {
                yaw -= ddx * mouse_sens;
                pitch -= ddy * mouse_sens;
            }
        }
        prev_mx = mx;
        prev_my = my;
    }

    if pitch > 85.0 {
        pitch = 85.0;
    }
    if pitch < -85.0 {
        pitch = -85.0;
    }

    yaw_r = yaw * DEG2RAD;
    fwd_x = -jsin(yaw_r);
    fwd_z = -jcos(yaw_r);
    rgt_x = jcos(yaw_r);
    rgt_z = -jsin(yaw_r);
    move = 8.0 * step;
    if key_held(KEY_W) {
        px += fwd_x * move;
        pz += fwd_z * move;
    }
    if key_held(KEY_S) {
        px -= fwd_x * move;
        pz -= fwd_z * move;
    }
    if key_held(KEY_D) {
        px += rgt_x * move;
        pz += rgt_z * move;
    }
    if key_held(KEY_A) {
        px -= rgt_x * move;
        pz -= rgt_z * move;
    }
}


glob targets: list[Target] = [],
     bullets: list[Bullet] = [];

with entry {
    open_window(960, 600, "Jac Cube Shooter");

    for n in range(7) {
        t = Target(x=0.0, y=0.0, z=0.0, base_y=0.0, phase=0.0, alive=False);
        respawn(t);
        targets.append(t);
    }

    for n in range(24) {
        bullets.append(Bullet(x=0.0, y=0.0, z=0.0, vx=0.0, vy=0.0, vz=0.0, life=0.0));
    }

    while not should_close() {
        step = dt();
        world_t += step;

        frames += 1;
        if step > 0.0 {
            inst = 1.0 / step;
            if inst > max_fps {
                max_fps = inst;
            }
        }

        handle_input(step);
        fire_cd -= step;
        if key_held(KEY_SPACE) and fire_cd <= 0.0 {
            fire(bullets);
            fire_cd = 0.14;
        }
        update_bullets(bullets, targets, step);

        ti = 0;
        while ti < len(targets) {
            t = targets[ti];
            t.y = t.base_y + 0.4 * jsin(world_t * 1.5 + t.phase);
            ti += 1;
        }

        begin_frame(15, 18, 28);
        set_camera(px, py, pz, yaw, pitch, 1.6);
        draw_floor(20, 1.5);

        ti = 0;
        while ti < len(targets) {
            t = targets[ti];
            if t.alive {
                draw_box(t.x, t.y, t.z, 1.4, 1.4, 1.4, 235, 80, 60);
            }
            ti += 1;
        }

        bi = 0;
        while bi < len(bullets) {
            b = bullets[bi];
            if b.life > 0.0 {
                draw_box(b.x, b.y, b.z, 0.22, 0.22, 0.22, 250, 220, 90);
            }
            bi += 1;
        }

        end_camera(960.0, 600.0);
        draw_fps(10, 10);
        end_frame();

        # Self-screenshot path (dormant unless `.screenshot` exists): grab the
        # presented frame after EndDrawing, then exit.
        if shot > 0 and frames >= shot {
            TakeScreenshot("shooter_shot.png");
            break;
        }

        if bench > 0.0 and clock() >= bench {
            break;
        }
    }

    if bench > 0.0 {
        elapsed = clock();
        avg_fps = 0.0;
        if elapsed > 0.0 {
            avg_fps = float(frames) / elapsed;
        }
        write_bench_result(avg_fps, max_fps, frames, elapsed);
    }

    close_window();
