# file: walkers/log.jac
"""Daily-log walkers: day buckets and their entries."""

import from models {
    Project,
    Member,
    Task,
    LogDay,
    LogEntry,
    LogPage,
    LogTotals,
    MemberDays,
    Logged,
    By,
    AssignedTo,
    ForProject,
    resolve,
    on_attached,
    owned
}
import from walkers.util { today_iso, shift_day, page_bounds, now_iso }

# ---------------------------------------------------------------- daily log

walker ListLogEntries {
    """One page of entries whose LogDay date falls in [from_date, to_date],
    ISO strings, newest day first. `total` counts the whole range so a page
    can say how much of the week it is."""
    has from_date: str,
        to_date: str,
        page: int = 1,
        page_size: int = 0,
        reports: list[LogPage] = [];

    can gather with Root entry {
        (p, size, start, end) = page_bounds(self.page, self.page_size, 200, 500);
        found: list[LogEntry] = [];
        for day in [here-->[?:LogDay, date>=self.from_date, date<=self.to_date]] {
            for row in [day->:Logged:->] {
                found.append(row);
            }
        }
        # Newest day first so page 1 is the end of the week; the jid pass
        # underneath keeps rows that tie on day and name in one order
        # across pages (sorts are stable).
        found.sort(key=lambda (r: LogEntry) { jid(r); });
        found.sort(key=lambda (r: LogEntry) { r.member_name; });
        found.sort(key=lambda (r: LogEntry) { r.date; }, reverse=True);
        report LogPage(
            rows=found[start:end],
            page=p,
            page_size=size,
            has_more=len(found) > end,
            total=len(found)
        );
    }
}

# The Overview's log numbers: entries per week for the four weeks ending in
# `monday`'s week (oldest first), per weekday of that week, and which days each
# person logged on. Reads node fields only, so row volume does not change cost.
def log_totals(holder: Root, monday: str) -> LogTotals {
    week0 = monday if len(monday) >= 10 else today_iso();
    starts = [shift_day(week0, -7 * (3 - i)) for i in range(4)];
    since = starts[0];
    until = shift_day(week0, 6);
    week_days = [shift_day(week0, i) for i in range(7)];
    # Week bounds up front, for the same reason as task_totals.
    ends = [shift_day(starts[i], 7) for i in range(4)];
    by_week = [0, 0, 0, 0];
    by_day = [0, 0, 0, 0, 0, 0, 0];
    per_person: dict[str, list[int]] = {};
    for day in [holder-->[?:LogDay, date>=since, date<=until]] {
        for row in [day->:Logged:->] {
            for i in range(4) {
                if row.date >= starts[i] and row.date < ends[i] {
                    by_week[i] = by_week[i] + 1;
                }
            }
            if row.date < week0 {
                continue;
            }
            slot = -1;
            for i in range(7) {
                if row.date == week_days[i] {
                    slot = i;
                }
            }
            if slot < 0 {
                continue;
            }
            by_day[slot] = by_day[slot] + 1;
            for who in row.member_name.split(",") {
                name = who.strip();
                if not name {
                    continue;
                }
                if name not in per_person {
                    per_person[name] = [0, 0, 0, 0, 0, 0, 0];
                }
                per_person[name][slot] = per_person[name][slot] + 1;
            }
        }
    }
    people: list[MemberDays] = [];
    for name in per_person {
        counts = per_person[name];
        people.append(MemberDays(name=name, by_day=counts, total=sum(counts)));
    }
    return LogTotals(by_week=by_week, by_day=by_day, members=people);
}


walker LogCounts {
    """The Overview's log numbers over the four weeks ending in `monday`'s
    week."""
    has monday: str = "",
        reports: list[LogTotals] = [];

    can count with Root entry {
        report log_totals(here, self.monday);
    }
}


walker LogActivity {
    """Get-or-create the day bucket under the caller's root, then append one
    denormalized row. Refuses writes no view could fetch (empty date) or
    that would produce a blank authorless row (bad member jid)."""
    has date: str,
        member_id: str,
        activity: str,
        project_id: str = "",
        category: str = "",
        repo: str = "",
        issue_link: str = "",
        pr_link: str = "",
        status: str = "",
        notes: str = "",
        reports: list[LogEntry] = [];

    can start with Root entry {
        if not self.date {
            disengage;
        }
        probe = resolve(self.member_id);
        if not isinstance(probe, Member) or not owned(here, probe) {
            disengage;
        }
        visit [here-->[?:LogDay, date==self.date]] else {
            fresh = here ++> LogDay(date=self.date);
            on_attached(here, fresh);
            visit fresh;
        }
    }

    can add with LogDay entry {
        # `here` is the LogDay; its container is the caller's root.
        owners = [here<--];
        holder = owners[0];
        member_name = "";
        tags_snap = "";
        m = resolve(self.member_id);
        if isinstance(m, Member) {
            member_name = m.name;
            tags_snap = ", ".join(m.tags);
        }
        project_name = "";
        p = resolve(self.project_id);
        if isinstance(p, Project) and owned(holder, p) {
            project_name = p.name;
        }
        # Stamped like the automatic rows, so the time column and the
        # digest's ordering treat manual entries the same way.
        row = here +>:Logged():+> LogEntry(
            date=here.date,
            at=now_iso(),
            activity=self.activity,
            category=self.category,
            repo=self.repo,
            issue_link=self.issue_link,
            pr_link=self.pr_link,
            status=self.status,
            notes=self.notes,
            member_name=member_name,
            tags=tags_snap,
            project_name=project_name
        );
        if isinstance(m, Member) {
            row +>:By():+> m;
        }
        report row;
    }
}

# Board moves write the log now: append one denormalized row describing a
# task event to today's bucket. Called from the task walkers.
def record_task_event(holder: Root, task: Task, activity: str, stamp: str) -> None {
    today = stamp[:10];
    if not today {
        return;
    }
    # Server-side, a filtered re-query is answered from committed storage,
    # so a bucket created in this request is invisible to it. Use the
    # freshly connected node directly instead of querying it back.
    days = [holder-->[?:LogDay, date==today]];
    if days {
        day = days[0];
    } else {
        day = holder ++> LogDay(date=today);
        on_attached(holder, day);
    }
    names: list[str] = [];
    tag_pool: list[str] = [];
    for a in [task->:AssignedTo:->] {
        names.append(a.name);
        for t in a.tags {
            if t not in tag_pool {
                tag_pool.append(t);
            }
        }
    }
    projects = [task->:ForProject:->];
    day +>:Logged():+> LogEntry(
        date=today,
        at=stamp,
        task_id=jid(task),
        task_title=task.title,
        activity=activity,
        category=task.category,
        repo="",
        issue_link=task.issue_link,
        pr_link=task.pr_link,
        status=task.status,
        notes="",
        member_name=", ".join(names),
        tags=", ".join(tag_pool),
        project_name=projects[0].name if projects else ""
    );
}

# The move handoff arrives after the move row was written; refresh the
# latest row for this task today so its links and note show in the feed.
def sync_task_links(holder: Root, task: Task, note: str) -> None {
    today = task.updated_at[:10];
    days = [holder-->[?:LogDay, date==today]];
    if not days {
        return;
    }
    matches = [
        r
        for r in [days[0]->:Logged:->]
        if r.task_id == jid(task)
    ];
    if not matches {
        return;
    }
    matches.sort(key=lambda (r: LogEntry) { r.at; });
    target = matches[-1];
    target.issue_link = task.issue_link;
    target.pr_link = task.pr_link;
    if note {
        target.notes = note;
    }
}

walker find_log_entry {
    """Lookup base for log-entry mutations: two-hop parentage check
    (LogEntry <- LogDay <- root) before visiting."""
    has entry_id: str = "";

    can locate with Root entry {
        target = resolve(self.entry_id);
        if not isinstance(target, LogEntry) {
            disengage;
        }
        days = [target<-:Logged:<-];
        if days and owned(here, days[0]) {
            visit [target];
        }
    }
}

walker UpdateLogEntry(find_log_entry) {
    has activity: str = "",
        category: str = "",
        repo: str = "",
        issue_link: str = "",
        pr_link: str = "",
        status: str = "",
        notes: str = "",
        reports: list[LogEntry] = [];

    can apply with LogEntry entry {
        here.activity = self.activity;
        here.category = self.category;
        here.repo = self.repo;
        here.issue_link = self.issue_link;
        here.pr_link = self.pr_link;
        here.status = self.status;
        here.notes = self.notes;
        report here;
        disengage;
    }
}

walker DeleteLogEntries {
    """Bulk delete: every id is parentage-checked (LogEntry <- LogDay <-
    root) before removal, same rule as the single-entry lookup base."""
    has entry_ids: list[str] = [];

    can remove with Root entry {
        gone: list[str] = [];
        for eid in self.entry_ids {
            target = resolve(eid);
            if not isinstance(target, LogEntry) {
                continue;
            }
            days = [target<-:Logged:<-];
            if days and owned(here, days[0]) {
                gone.append(jid(target));
                del target;
            }
        }
        report {"deleted": gone};
    }
}

# file: walkers/projects.jac
"""Project walkers: CRUD plus member assignment edges."""

import from models { Project, Member, OnProject, resolve, on_attached, owned }

# ----------------------------------------------------------------- projects

walker ListProjects {
    has reports: list[list[Project]] = [];

    # Rows live in a local, never a `has` field: a walker's public fields
    # are serialised into the response beside the report, so an accumulator
    # field would ship the whole list twice.
    can gather with Root entry {
        rows = [here-->[?:Project]];
        rows.sort(key=lambda (p: Project) { p.name; });
        report rows;
    }
}

walker SaveProject {
    """Empty project_id creates; otherwise updates the addressed Project."""
    has project_id: str = "",
        name: str = "",
        description: str = "",
        reports: list[Project] = [];

    can save with Root entry {
        if not self.name.strip() {
            disengage;
        }
        if self.project_id {
            target = resolve(self.project_id);
            if isinstance(target, Project) and owned(here, target) {
                target.name = self.name.strip();
                target.description = self.description;
                report target;
            }
        } else {
            fresh = here ++> Project(
                name=self.name.strip(), description=self.description
            );
            on_attached(here, fresh);
            report fresh;
        }
    }
}

walker ArchiveProject {
    """active=False, tasks and history keep pointing at it."""
    has project_id: str;

    can archive with Root entry {
        target = resolve(self.project_id);
        if isinstance(target, Project) and owned(here, target) {
            target.active = False;
            report {"archived": self.project_id};
        }
    }
}

walker AssignToProject {
    has member_id: str,
        project_id: str;

    can assign with Root entry {
        m = resolve(self.member_id);
        p = resolve(self.project_id);
        if not isinstance(m, Member) or not isinstance(p, Project) {
            disengage;
        }
        if not owned(here, m) or not owned(here, p) {
            disengage;
        }
        if not [edge m->:OnProject:->p] {
            m +>:OnProject():+> p;
        }
        report {"assigned": True};
    }
}

walker UnassignFromProject {
    has member_id: str,
        project_id: str;

    can unassign with Root entry {
        m = resolve(self.member_id);
        p = resolve(self.project_id);
        if not isinstance(m, Member) or not isinstance(p, Project) {
            disengage;
        }
        if not owned(here, m) or not owned(here, p) {
            disengage;
        }
        for e in [edge m->:OnProject:->p] {
            del e;
        }
        report {"unassigned": True};
    }
}

# repo: flowline

# file: walkers/flowlines.jac

import from models {
    WorkflowStep,
    WorkflowMeta,
    Task,
    Role,
    StepView,
    TaskView,
    TaskPage,
    FlowsTo,
    ForProject,
    hydrate_views,
    step_view,
    resolve,
    on_attached,
    owned
}
import from walkers.util { now_iso, page_bounds }
import from constants {
    STEP_KINDS,
    KIND_COLORS,
    KIND_STATUS,
    STATUS_KIND,
    CARRY_KINDS,
    FLOW_LINE_TEMPLATES
}


# A step's kind IS the semantics every other part of the app reads, through
# each task's `status`. Re-point the tasks sitting on this step whenever the
# kind changes, or "done" work would keep reporting as "In Progress" to
# insights, the digest and the assistant.
def restatus_tasks(holder: Root, step: WorkflowStep) {
    landing = KIND_STATUS[step.kind] if step.kind in KIND_STATUS else "In Progress";
    target = jid(step);
    for t in [holder-->[?:Task]] {
        if t.step_id == target and t.status != landing {
            t.status = landing;
        }
    }
}


# Where a task lands: its own step when that step still exists, else the
# first step whose kind matches its legacy status. One rule for the board,
# the counts and the per-step panel.
def landing_step(t: Task, known: list[str], first_of_kind: dict[str, str]) -> str {
    if t.step_id and t.step_id in known {
        return t.step_id;
    }
    kind = STATUS_KIND[t.status] if t.status in STATUS_KIND else "active";
    if kind in first_of_kind {
        return str(first_of_kind[kind]);
    }
    return "";
}


# Canvas bound in px. Positions come straight off the wire, so this is what
# keeps a crafted request from breaking the workspace: NaN and ±Infinity fail
# the range test and land at the origin (a stored inf would serialize as the
# bare token `Infinity`, which JSON.parse rejects on every later read).
glob MAX_COORD: float = 20000.0;


def safe_coord(v: float) -> float {
    if v >= 0.0 and v <= MAX_COORD {
        return v;
    }
    return 0.0;
}


# Singleton per root, like GithubConnection: first touch creates it.
def get_meta(holder: Root) -> WorkflowMeta {
    existing = [holder-->[?:WorkflowMeta]];
    if existing {
        return existing[0];
    }
    fresh = holder ++> WorkflowMeta();
    on_attached(holder, fresh);
    return fresh;
}


walker GetFlowLineMeta {
    """Read-only: a GET must not write, so an org that has never renamed
    its flow line reports the default without creating the node."""
    has reports: list[dict[str, str]] = [];

    can read with Root entry {
        existing = [here-->[?:WorkflowMeta]];
        name = existing[0].name if existing else "";
        # "Workflow" was the default before the rename, and ApplyTemplate
        # persisted it for every templated org, so it reads as the new one.
        if not name or name == "Workflow" {
            name = "Flow line";
        }
        report {
            "name": name,
            "template_key": existing[0].template_key if existing else ""
        };
    }
}


walker RenameFlowLine {
    has name: str = "",
        reports: list[dict[str, str]] = [];

    can rename with Root entry {
        meta = get_meta(here);
        if self.name.strip() {
            meta.name = self.name.strip();
        }
        report {"name": meta.name};
    }
}


walker GetFlowLine {
    """The org's steps, each carrying how much work sits on it; `project_id`
    narrows the count. Computed here so the placement rule (step first, then
    the legacy status fallback) has one implementation for board and view.
    `with_counts=False` skips the walk over every task: the board counts the
    rows it already holds, so its 60 s poll need not pay for it."""
    has project_id: str = "",
        with_counts: bool = True,
        reports: list[list[StepView]] = [];

    can gather with Root entry {
        views: list[StepView] = [];
        for st in [here-->[?:WorkflowStep]] {
            views.append(step_view(st));
        }
        views.sort(key=lambda (s: StepView) { s.sort_order; });
        if not self.with_counts {
            report views;
            disengage;
        }
        # Count into a plain map first, then stamp the views: mutating a
        # view through a dict lookup is more than the checker can follow.
        counts: dict[str, int] = {};
        known: list[str] = [];
        first_of_kind: dict[str, str] = {};
        for v in views {
            counts[v.id] = 0;
            known.append(v.id);
            if v.kind not in first_of_kind {
                first_of_kind[v.kind] = v.id;
            }
        }
        for t in [here-->[?:Task]] {
            if self.project_id {
                owning = [t->:ForProject:->];
                if not owning or jid(owning[0]) != self.project_id {
                    continue;
                }
            }
            landing = landing_step(t, known, first_of_kind);
            if landing {
                counts[landing] = int(counts[landing]) + 1;
            }
        }
        for v in views {
            v.task_count = counts[v.id];
        }
        report views;
    }
}


walker ListStepTasks {
    """One page of the work sitting on one step, for the panel the flow line
    view opens. Placement reuses GetFlowLine's rule so list and count never
    disagree; the walk touches node fields only and `to_view()` runs for the
    page. `total` is the whole step, so the header can keep counting."""
    has step_id: str = "",
        project_id: str = "",
        page: int = 1,
        page_size: int = 0,
        reports: list[TaskPage] = [];

    can gather with Root entry {
        (p, size, start, end) = page_bounds(self.page, self.page_size, 50, 500);
        empty = TaskPage(rows=[], page=p, page_size=size, has_more=False, total=0);
        target = resolve(self.step_id);
        if not isinstance(target, WorkflowStep) or not owned(here, target) {
            report empty;
            disengage;
        }
        wanted = jid(target);
        known: list[str] = [];
        first_of_kind: dict[str, str] = {};
        for st in [here-->[?:WorkflowStep]] {
            known.append(jid(st));
            if st.kind not in first_of_kind {
                first_of_kind[st.kind] = jid(st);
            }
        }
        picked: list[Task] = [];
        for t in [here-->[?:Task]] {
            if landing_step(t, known, first_of_kind) != wanted {
                continue;
            }
            if self.project_id {
                owning = [t->:ForProject:->];
                if not owning or jid(owning[0]) != self.project_id {
                    continue;
                }
            }
            picked.append(t);
        }
        # jid first, then the real key: sorts are stable, so equal
        # sort_orders keep one order across pages instead of swapping.
        picked.sort(key=lambda (t: Task) { jid(t); });
        picked.sort(key=lambda (t: Task) { t.sort_order; });
        report TaskPage(
            rows=hydrate_views(here, picked[start:end]),
            page=p,
            page_size=size,
            has_more=len(picked) > end,
            total=len(picked)
        );
    }
}


walker ApplyTemplate {
    """Seed the org's flow line from one template, atomically. Idempotent by
    refusal: with any step already present the existing flow line is reported
    instead, so a double-click cannot overlay two flow lines."""
    has template_key: str = "",
        reports: list[list[StepView]] = [];

    can apply with Root entry {
        existing = [here-->[?:WorkflowStep]];
        if existing {
            views: list[StepView] = [];
            for s in existing {
                views.append(step_view(s));
            }
            views.sort(key=lambda (v: StepView) { v.sort_order; });
            report views;
            disengage;
        }
        chosen: dict[str, any] = {};
        for t in FLOW_LINE_TEMPLATES {
            if t["key"] == self.template_key {
                chosen = t;
            }
        }
        if not chosen {
            report [];
            disengage;
        }
        stamp = now_iso();
        made: list[WorkflowStep] = [];
        order = 1024.0;
        # Typed locals first: the checker will not subscript a nested `any`.
        raw_steps: list[dict[str, any]] = chosen["steps"];
        for s in raw_steps {
            kind = s["kind"] if s["kind"] in STEP_KINDS else "active";
            fresh = here ++> WorkflowStep(
                name=s["name"],
                kind=kind,
                color=s["color"],
                owner=str(s["owner"]) if "owner" in s else "",
                blurb=str(s["blurb"]) if "blurb" in s else "",
                x=s["x"],
                y=s["y"],
                sort_order=order,
                created_at=stamp,
                updated_at=stamp
            );
            on_attached(here, fresh);
            made.append(fresh);
            order = order + 1024.0;
        }
        # Parallel lists, so templates without wording or tags keep working.
        wording: list[str] = [];
        if "link_labels" in chosen {
            wording = chosen["link_labels"];
        }
        cargo: list[str] = [];
        if "link_carries" in chosen {
            cargo = chosen["link_carries"];
        }
        raw_links: list[list[int]] = chosen["links"];
        for (i, pair) in enumerate(raw_links) {
            source = made[pair[0]];
            target = made[pair[1]];
            said = wording[i] if i < len(wording) else "";
            carried = cargo[i] if i < len(cargo) else "";
            if carried not in CARRY_KINDS {
                carried = "";
            }
            source +>:FlowsTo(label=said, carries=carried):+> target;
        }
        # Remember which template this was. Scratch flow lines never come
        # through here and keep the default "".
        meta = get_meta(here);
        meta.template_key = self.template_key;
        # Seed the template's roles as Role nodes, editable org data from
        # here on. Get-or-create by name, so a role the org already made
        # keeps whatever it says.
        if "roles" in chosen {
            raw_roles: list[dict[str, str]] = chosen["roles"];
            r_order = 1024.0;
            for rr in raw_roles {
                if not [here-->[?:Role, name==rr["name"]]] {
                    fresh_role = here ++> Role(
                        name=rr["name"],
                        blurb=rr["blurb"] if "blurb" in rr else "",
                        color=rr["color"] if "color" in rr else "",
                        sort_order=r_order
                    );
                    on_attached(here, fresh_role);
                }
                r_order = r_order + 1024.0;
            }
        }
        views: list[StepView] = [];
        for m in made {
            views.append(step_view(m));
        }
        report views;
    }
}


walker find_step {
    """Lookup base: resolve the jid once, verify org parentage, then visit.
    MoveStep and DeleteStep subclass this; walkers needing Root entry repeat
    the resolve + isinstance + owned triple. Resolution is NOT authorization."""
    has step_id: str = "";

    can locate with Root entry {
        target = resolve(self.step_id);
        if isinstance(target, WorkflowStep) and owned(here, target) {
            visit [target];
        }
    }
}


walker SaveStep {
    """Empty step_id creates; otherwise updates the addressed one. Update is
    partial on purpose (empty means keep): the inspector edits one field at a
    time and must not blank the others."""
    has step_id: str = "",
        name: str = "",
        kind: str = "",
        color: str = "",
        # Empty means "keep", like every field here; a space clears it.
        owner: str = "",
        blurb: str = "",
        x: float = 0.0,
        y: float = 0.0,
        reports: list[StepView] = [];

    can save with Root entry {
        # Clamp before anything else: the response envelope echoes these
        # fields, so a non-finite float would 500 the request even when the
        # stored value is clean.
        self.x = safe_coord(self.x);
        self.y = safe_coord(self.y);
        stamp = now_iso();
        if self.step_id {
            target = resolve(self.step_id);
            if not isinstance(target, WorkflowStep) or not owned(here, target) {
                disengage;
            }
            if self.name.strip() {
                target.name = self.name.strip();
            }
            kind_changed = self.kind in STEP_KINDS and self.kind != target.kind;
            if self.kind in STEP_KINDS {
                target.kind = self.kind;
            }
            if kind_changed {
                restatus_tasks(here, target);
            }
            if self.color {
                target.color = self.color;
            }
            if self.owner {
                target.owner = self.owner.strip();
            }
            if self.blurb {
                target.blurb = self.blurb.strip();
            }
            target.updated_at = stamp;
            report step_view(target);
            disengage;
        }
        if not self.name.strip() {
            disengage;
        }
        kind = self.kind if self.kind in STEP_KINDS else "active";
        color = self.color or KIND_COLORS[kind];
        peak = 0.0;
        for s in [here-->[?:WorkflowStep]] {
            if s.sort_order > peak {
                peak = s.sort_order;
            }
        }
        fresh = here ++> WorkflowStep(
            name=self.name.strip(),
            kind=kind,
            color=color,
            owner=self.owner.strip(),
            blurb=self.blurb.strip(),
            x=self.x,
            y=self.y,
            sort_order=peak + 1024.0,
            created_at=stamp,
            updated_at=stamp
        );
        on_attached(here, fresh);
        report step_view(fresh);
    }
}

