"""Path-based routing; every market page also works as a direct link (e.g. from an email)."""
def:pub app -> JsxElement {
    path = current_path().rstrip("/") or "/";
    if path == "/ui" {
        return <Gallery/>;
    }
    if path == "/market/preview" {
        return <MarketPreview/>;
    }
    if (
        path.startswith("/market")
        or path.startswith("/journey")
        or path in ["/today", "/profile", "/onboarding", "/interests", "/events"]
    )
        and not jacIsLoggedIn() {
        return <Welcome/>;
    }
    if path == "/" {
        return <Landing/>;
    }
    if path in ["/login", "/signup"] {
        return <Welcome/>;
    }
    if path == "/profile" {
        return <Account/>;
    }
    if path == "/today" {
        return <Today/>;
    }
    if path == "/onboarding" {
        return <Onboarding/>;
    }
    if path == "/interests" {
        return <InterestsGate/>;
    }
    if path == "/journey" {
        return <JourneyHome/>;
    }
    if path == "/journey/task" {
        return <TaskDetail/>;
    }
    if path == "/journey/ask" {
        return <AskGuide/>;
    }
    if path == "/events" {
        return <Events/>;
    }
    if path == "/market" {
        return <GroupList/>;
    }
    if path == "/market/g" {
        return <GroupChat/>;
    }
    if path == "/market/matches" {
        return <MatchesInbox/>;
    }
    if path == "/market/new" {
