        }
        nid = dossier.id;
        photoReq.current = nid;
        w: any = window;
        cache: any = w.__pulsePhotoCache;
        if not cache {
            cache = {};
            w.__pulsePhotoCache = cache;
        }
        if nid in cache {
            photos = cache[nid];
            photosLoading = False;
            return;
        }
        photosLoading = True;
        photos = [];
        try {
            media: DossierMedia = await with_timeout(
