            cache[nid] = imgs;
            if photoReq.current == nid {
                photos = imgs;
            }
        } except Exception {
            if photoReq.current == nid {
                photos = [];
            }
        }
        if photoReq.current == nid {
            photosLoading = False;
        }
    }

    can with [dossier.id] entry {
        if is_neighbor_post {
            photos = [];
            photosLoading = False;
        } else {
            load_photos();
        }
    }

