            "label": "Claude (Anthropic)",
            "requires_key": True,
            "models": ["claude-sonnet-5", "claude-haiku-4-5"]
        },
        {
            "id": "mlx",
            "label": "Local (MLX)",
            "requires_key": False,
            "models": mlx_models
        }
    ];
    return {
        "configured": src != "none",
        "source": src,
        "masked": _masked_tail(),
        "providers": providers
    };
}

