"""Build the Sherry browser extension into dist/ (load it in Chrome with
"Load unpacked").

    ../../.venv/bin/jac run build.jac

Steps: compile every src/**/*.cl.jac to JavaScript with `jac jac2js`, bundle
each entry point (content, background, popup) into one self-contained script
with Bun, then copy static/ (manifest, popup.html, popup.css).

Bun is looked up in $SHERRY_BUN, then ../web/.jac/bin/bun (installed by
`jac install` in apps/web), then on PATH.
"""

import os;
import sys;
import shutil;
import subprocess;
import from pathlib { Path }

glob ENTRIES: list[str] = ["content", "background", "popup"];


def find_bun(base_dir: Path) -> str {
    env = os.environ.get("SHERRY_BUN", "");
    if env {
        return env;
    }
    local = base_dir.parent / "web" / ".jac" / "bin" / "bun";
    if local.exists() {
        return str(local);
    }
    found = shutil.which("bun");
    if found {
        return found;
    }
    raise RuntimeError("Bun not found. Run `jac install` in apps/web or set SHERRY_BUN.");
}


def find_jac -> str {
    beside = Path(sys.executable).parent / "jac";
    if beside.exists() {
        return str(beside);
    }
    found = shutil.which("jac");
    if found {
        return found;
    }
    raise RuntimeError("The jac CLI was not found.");
}


def run(cmd: list[str]) -> str {
    done = subprocess.run(cmd, capture_output=True, text=True);
    if done.returncode != 0 {
        raise RuntimeError(f"Command failed: {' '.join(cmd)}\n{done.stdout}\n{done.stderr}");
    }
    return done.stdout;
}


with entry {
    base_dir = Path(str(__file__)).resolve().parent;
    src = base_dir / "src";
    compiled = base_dir / "build" / "js";
    dist = base_dir / "dist";
    jac = find_jac();
    bun = find_bun(base_dir);

    shutil.rmtree(base_dir / "build", ignore_errors=True);
    shutil.rmtree(dist, ignore_errors=True);
    compiled.mkdir(parents=True);
    dist.mkdir(parents=True);

    sources = sorted(src.rglob("*.cl.jac"));
    for source in sources {
        rel = source.relative_to(src);
        target = compiled / str(rel).replace(".cl.jac", ".js");
        target.parent.mkdir(parents=True, exist_ok=True);
        target.write_text(run([jac, "jac2js", str(source)]));
    }
    print(f"compiled {len(sources)} Jac files");

    for name in ENTRIES {
        run(
            [
                bun,
                "build",
                str(compiled / f"{name}.js"),
                "--format",
                "iife",
                "--target",
                "browser",
                "--outfile",
                str(dist / f"{name}.js")
            ]
        );
        print(f"bundled dist/{name}.js");
    }

    for asset in (base_dir / "static").iterdir() {
        shutil.copy(asset, dist / asset.name);
    }
    print(f"copied static files -> {dist}");
    print("Load it in Chrome: chrome://extensions -> Developer mode -> Load unpacked -> apps/extension/dist");
}

# file: apps/extension/src/background.cl.jac
"""Sherry extension background worker.

Content scripts and the popup send it messages; it is the only part that
talks to the Sherry API (so the API key never touches the AI websites' pages).

Messages:
    {type: "capture", platform, conversation_id, url, title, messages}
    {type: "summarize", platform, conversation_id, force}
    {type: "test"}                      - check URL + key
"""

import from .lib.ext { chrome_api, load_settings, load_status, save_status, now_iso }
import from .lib.api { call_sherry }


async def record(update: dict) -> None {
    current = await load_status();
    await save_status({**current, **update, "updatedAt": now_iso()});
}


async def handle_capture(msg: any) -> dict {
    settings = await load_settings();
    platform = str(msg.platform);
    if settings["paused"] {
        return {"ok": False, "skipped": True, "error": "Capture is paused."};
    }
    if not settings["sites"][platform] {
        return {"ok": False, "skipped": True, "error": "Capture is off for this site."};
    }
    reply = await call_sherry(
        "capture_conversation",
        {
            "platform": platform,
            "conversation_id": msg.conversation_id,
            "url": msg.url,
            "title": msg.title,
            "messages": msg.messages
        }
    );
    if reply["ok"] {
        result: any = reply["result"];
        await record(
            {
                "lastCaptureAt": now_iso(),
                "lastPlatform": platform,
                "lastTitle": msg.title,
                "lastAdded": result.added,
                "lastTotal": result.totalMessages,
                "lastIgnored": result.ignored,
                "lastError": ""
            }
        );
    } else {
        await record({"lastError": reply["error"]});
    }
    return reply;
}


async def handle_summarize(msg: any) -> dict {
    settings = await load_settings();
    if settings["paused"] {
        return {"ok": False, "skipped": True, "error": "Capture is paused."};
    }
    reply = await call_sherry(
        "summarize_conversation",
        {
            "platform": msg.platform,
            "conversation_id": msg.conversation_id,
            "force": bool(msg.force)
        }
    );
    if reply["ok"] {
        result: any = reply["result"];
        await record(
            {
                "lastSummaryAt": now_iso(),
                "lastSummaryStatus": result.status,
                "lastSummaryEngine": result.engine,
                "lastSummaryNote": result.note,
                "lastError": ""
            }
        );
    } else {
        await record({"lastError": reply["error"]});
    }
    return reply;
}


async def handle_test -> dict {
    health = await call_sherry("health", {});
    if not health["ok"] {
        return health;
    }
    return await call_sherry("list_memories", {"query": "", "cursor": "", "limit": 1});
}


async def route(msg: any) -> dict {
    kind = str(msg.`type if msg else "");
    if kind == "capture" {
        return await handle_capture(msg);
    }
    if kind == "summarize" {
        return await handle_summarize(msg);
    }
    if kind == "test" {
        return await handle_test();
    }
    return {"ok": False, "error": "Unknown message type: " + kind};
}


with entry {
    chrome_api().runtime.onMessage.addListener(
        lambda (msg: any, sender: any, send: any) -> bool {
            pending: any = route(msg);
            pending.then(
                lambda (reply: any) { send.call(None, reply); }
            ).catch(
                lambda (err: any) { send.call(None, {"ok": False, "error": str(err)}); }
            );
            # Keep the channel open for the async reply.
            return True;
        }
    );
}

# file: apps/extension/src/content.cl.jac
"""Sherry content script - runs inside chatgpt.com, claude.ai and gemini.google.com.

Watches the open chat and captures every message:
1. A MutationObserver notices page changes (debounced); a 5-second interval
   is the safety net (also catches in-app navigation between chats).
2. While the assistant is still streaming, capture waits.
3. Only new or changed messages are sent (via the background worker).
4. After the chat has been quiet for SUMMARY_IDLE_MS, the background worker
   asks Sherry to (re)summarize it. Sherry skips it if nothing changed.
"""

import from .lib.sites {
    detect_site,
    conversation_id,
    conversation_title,
    conversation_url,
    is_streaming,
    read_messages
}
import from .lib.ext { chrome_api, send_to_background }

glob SCAN_DEBOUNCE_MS: int = 1200;
glob SAFETY_SCAN_MS: int = 5000;
glob SUMMARY_IDLE_MS: int = 20000;
glob BATCH_SIZE: int = 100;

# Module state (not reactive): what has been sent for the open chat.
glob STATE: dict = {
    "site": "",
    "conversation": "",
    "sent": {},
    "scanTimer": None,
    "summaryTimer": None,
    "busy": False,
    "dead": False
};


def schedule_scan(delay: int) {
    if STATE["scanTimer"] {
        clearTimeout(STATE["scanTimer"] as float);
    }
    STATE["scanTimer"] = setTimeout(lambda { scan(); }, delay);
}


def schedule_summary(site: str, conv: str) {
    if STATE["summaryTimer"] {
        clearTimeout(STATE["summaryTimer"] as float);
    }
    STATE["summaryTimer"] = setTimeout(
        lambda { request_summary(site, conv, False); }, SUMMARY_IDLE_MS
    );
}


async def request_summary(site: str, conv: str, force: bool) -> dict {
    if STATE["dead"] {
        return {"ok": False, "error": "Extension was reloaded; refresh this page."};
    }
    try {
        return await send_to_background(
            {"type": "summarize", "platform": site, "conversation_id": conv, "force": force}
        );
    } except Exception {
        STATE["dead"] = True;
        return {"ok": False, "error": "Extension was reloaded; refresh this page."};
    }
}


def changed_messages(messages: list[dict]) -> list[dict] {
    sent: any = STATE["sent"];
    return [m for m in messages if sent[m["key"]] != m["text"]];
}


async def scan -> None {
    if STATE["busy"] or STATE["dead"] {
        return;
    }
    site = detect_site();
    conv = conversation_id(site);
    if not site or not conv {
        return;
    }
    if conv != STATE["conversation"] {
        STATE["conversation"] = conv;
        STATE["site"] = site;
        STATE["sent"] = {};
    }
    if is_streaming(site) {
        schedule_scan(SCAN_DEBOUNCE_MS);
        return;
    }
    pending = changed_messages(read_messages(site));
    if len(pending) == 0 {
        return;
    }
    STATE["busy"] = True;
    try {
        start = 0;
        while start < len(pending) {
            batch = pending[start:start + BATCH_SIZE];
            reply = await send_to_background(
                {
                    "type": "capture",
                    "platform": site,
                    "conversation_id": conv,
                    "url": conversation_url(),
                    "title": conversation_title(site),
                    "messages": batch
                }
            );
            if not reply["ok"] {
                # Leave these unsent; the next scan retries them.
                break;
            }
            sent: any = STATE["sent"];
            for m in batch {
                sent[m["key"]] = m["text"];
            }
            start += BATCH_SIZE;
        }
        if start > 0 {
            schedule_summary(site, conv);
        }
    } except Exception {
        # The extension was reloaded or removed: stop until the page reloads.
        STATE["dead"] = True;
    }
    STATE["busy"] = False;
}


"""Answers the popup: what's on this page, and 'summarize this chat now'."""
async def handle_popup(msg: any) -> dict {
    site = detect_site();
    conv = conversation_id(site);
    kind = str(msg.`type if msg else "");
    if kind == "page-info" {
        return {
            "ok": True,
            "site": site,
            "conversationId": conv,
            "title": conversation_title(site),
            "detected": len(read_messages(site)),
            "streaming": is_streaming(site)
        };
    }
    if kind == "summarize-now" {
        if not site or not conv {
            return {"ok": False, "error": "Open a saved chat first."};
        }
        await scan();
        return await request_summary(site, conv, True);
    }
    return {"ok": False, "error": "Unknown request."};
}


with entry {
    if detect_site() {
        on_change = lambda (records: any) { schedule_scan(SCAN_DEBOUNCE_MS); };
        observer: any = new(MutationObserver, on_change);  # jac:ignore[E1053]
        observer.observe(
            document.body, {"childList": True, "subtree": True, "characterData": True}
        );
        setInterval(lambda { scan(); }, SAFETY_SCAN_MS);
        chrome_api().runtime.onMessage.addListener(
            lambda (msg: any, sender: any, send: any) -> bool {
                pending: any = handle_popup(msg);
                pending.then(lambda (reply: any) { send.call(None, reply); });
                return True;
            }
        );
        schedule_scan(SCAN_DEBOUNCE_MS);
    }
}

