.review-top small { color: var(--al-muted); font-size: 12px; }
.review-item p { font-size: 13px; line-height: 1.55; margin: 9px 0 0; }
.review-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.review-tags span { background: var(--al-surface-soft); border-radius: 20px; padding: 4px 9px; font-size: 12px; color: var(--al-ink); }
.review-more { color: var(--al-muted); font-size: 12px; text-align: center; margin: 6px 0 0; }
.stars { display: inline-flex; gap: 1px; }
.star-slot { color: #d6dbd7; display: inline-grid; }
.star-slot.on { color: var(--al-amber); }
.star-slot.on svg { fill: currentColor; }
.star-slot.half { color: var(--al-amber); opacity: .55; }
.star-slot.half svg { fill: currentColor; }
.traveler-actions .btn { margin-top: 10px; }
.traveler-actions > p { margin-bottom: 8px; }
.review-cta { border-color: var(--al-amber); color: #7a4a14; }
.reviewed-note { display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--al-green); font-size: 13px; font-weight: 700; margin: 14px 0; }
.traveler-actions .safe-note { margin-top: 16px; }

/* review form: compliment tags */
.tag-picker { text-align: left; margin-top: 20px; }
.tag-picker > span { display: block; font-weight: 700; font-size: 13px; margin-bottom: 8px; }
.tag-picker em { font-style: normal; font-weight: 400; color: var(--al-muted); }
.tag-picker > div { display: flex; flex-wrap: wrap; gap: 7px; }
.tag-chip { border: 1px solid var(--al-line); background: white; border-radius: 20px; padding: 7px 12px; font-size: 13px; cursor: pointer; display: inline-flex; align-items: center; gap: 5px; color: var(--al-ink); }
.tag-chip:hover { border-color: var(--al-green); }
.tag-chip.on { background: var(--al-green-soft); border-color: var(--al-green); color: var(--al-green-dark); font-weight: 700; }

/* result card: handle opens the profile */
.name-link { border: 0; background: none; padding: 0; font: inherit; color: inherit; cursor: pointer; text-align: left; }
.name-link:hover { color: var(--al-green); text-decoration: underline; text-underline-offset: 3px; }

@media (max-width: 700px) {
  .traveler-hero { flex-direction: column; }
  .traveler-stats { grid-template-columns: 1fr 1fr; }
}

