.search-steps li > span strong { color: inherit; }
.agent-report { border: 1px solid var(--al-line); border-radius: 14px; background: linear-gradient(135deg, #f4faf6, #ffffff); margin: 4px 0 12px; overflow: hidden; }
.agent-report-head { width: 100%; border: 0; background: transparent; display: flex; align-items: center; gap: 12px; padding: 12px 14px; cursor: pointer; text-align: left; color: var(--al-ink); }
