.agent-stack i:nth-child(3), .agent-report li:nth-child(3) > b, .agent-notes li:nth-child(3) > b { background: var(--al-purple); }
.agent-stack i:nth-child(4), .agent-report li:nth-child(4) > b, .agent-notes li:nth-child(4) > b { background: var(--al-amber); }
.agent-stack i:nth-child(5), .agent-report li:nth-child(5) > b, .agent-notes li:nth-child(5) > b { background: var(--al-green-dark); }
.agent-report ol, .agent-notes { list-style: none; margin: 0; padding: 0 14px 12px; display: flex; flex-direction: column; gap: 10px; }
.agent-report li, .agent-notes li { display: flex; gap: 10px; align-items: flex-start; }
.agent-report li > div, .agent-notes li > div { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.agent-report li strong, .agent-notes li strong { font-size: 13px; }
.agent-report li small { color: var(--al-muted); font-size: 12px; }
.agent-report li p, .agent-notes li p { font-size: 13px; margin: 3px 0 0; color: var(--al-ink); }
.agent-report li > em { font-style: normal; font-size: 12px; color: var(--al-muted); white-space: nowrap; }
.agent-notes { padding: 0; }

/* Notifications bell (Matchmaker + messages) */
.bell-wrap { position: relative; }
.bell-button { position: relative; width: 38px; height: 38px; border-radius: 50%; border: 0; background: transparent; display: grid; place-items: center; cursor: pointer; color: #415046; }
.bell-button:hover { background: var(--al-surface-soft); color: var(--al-green); }
.bell-button.has-unread svg { animation: bell-ring 2.4s ease-in-out infinite; transform-origin: 50% 10%; }

