# file: mcp_server.jac
"""MCP server for any MCP client (Claude Code, Cursor, ...): the same vetting as the web app.

The goal and budget come from the user's prompt, which the agent passes to get_plan_instructions once per session.
Both are fixed for the session after that first call.
As in the web app, a purchase page must load when the server fetches it, and the price must be listed on it.

Run: jac run mcp_server.jac
"""
import os;
import time;
import from mcp.server.mcpserver { MCPServer, Context }
import from services.models { Mandate, Purchase }
import from services.tools { accepted_items, plan_instructions, submit_plan as vet_submitted_plan, purchase as vet_and_buy }
import from services.vetting { money, extract_mandate, retrying }

glob mcp = MCPServer(
    "plan-graph-payments",
    instructions="These tools are for an autonomous purchasing agent. Once the user has given a goal and budget, plan and buy without asking the user for confirmation or more details: choose sensible defaults for anything unstated. The server vets every plan and purchase against the user's mandate, so that is the safety check, not the user. Only a missing budget needs the user.",
);
# ponytail: one mandate per client session, in memory; a restart forgets every session.
glob mandates: dict[str, Mandate] = {};
# A client can reuse its session across conversations, so a mandate ends once every item is bought or after this long.
glob MANDATE_TTL_S = 6 * 3600;
glob NO_GOAL = {"ok": False, "error": "No goal yet. Call get_plan_instructions with the user's request first."};

"""The client's MCP session id over HTTP; stdio has one client, so one key."""
def key(ctx: Context) -> str {
    return (ctx.headers or {}).get("mcp-session-id") or "stdio";
}

"""This session's mandate, once get_plan_instructions has set its goal. Kept in the graph as an audit trail."""
def current(ctx: Context) -> Mandate | None {
    m = mandates.get(key(ctx));
    if m is not None and (time.time() - m.created_at > MANDATE_TTL_S or finished(m)) {
        del mandates[key(ctx)];
        return None;
    }
    return m;
}

"""True once every item of the accepted plan has an approved purchase."""
def finished(m: Mandate) -> bool {
    items = accepted_items(m);
    bought = {p.node_id for p in [m -->[?:Purchase]] if p.approved};
    return bool(items) and set(items) <= bought;
}

def logged(m: Mandate, name: str, args: dict, result: dict) -> dict {
    m.log("tool_result", "mcp", {"name": name, "args": args, "result": result});
    return result;
}

"""Step 1. Pass the user's request verbatim (their own words: what they want and why). Returns the instructions for
building the plan graph for their goal and budget. The request must state a budget. Goal and budget are fixed for the session after the first call.
Then carry out the instructions autonomously, without asking the user to confirm."""
@mcp.tool()
def get_plan_instructions(request: str, ctx: Context) -> str {
    m = current(ctx);
    header = "";
    if m is not None and request != m.request {
        header = "This session already has a mandate; its goal and budget are fixed until every item is bought, so the new request was not applied.\n";
    }
    if m is None {
        draft = retrying(extract_mandate, request);
        if draft.budget_usd <= 0 {
            return "No budget found in the request. Ask the user for their total budget in USD, then call again with it included.";
        }
        m = Mandate(goal=draft.goal, budget=money(draft.budget_usd), request=request, created_at=time.time());
        root ++> m;
        mandates[key(ctx)] = m;
    }
    return f"{header}Mandate: {m.goal}, budget ${m.budget:.2f} (USD). Tell the user this budget.\n\n{plan_instructions(m)}";
}

"""Step 2. Submit the plan graph for vetting. nodes: [{id, kind: item|subgoal|goal, name, price}], edges: [{child, parent}].
On rejection, fix the findings and resubmit, without asking the user. Resubmitting also replaces an accepted plan, e.g. when an item price was underestimated."""
@mcp.tool()
def submit_plan(nodes: list[dict], edges: list[dict], ctx: Context) -> dict {
    m = current(ctx);
    if m is None {
        return NO_GOAL;
    }
    return logged(m, "submit_plan", {"nodes": nodes, "edges": edges}, vet_submitted_plan(m, nodes, edges));
}

"""Step 3. Request payment for one item node of the accepted plan. price is the USD price listed at payment_url.
Buy every item without asking the user to confirm: the server vets each purchase."""
@mcp.tool()
def purchase(node_id: str, item_name: str, payment_url: str, price: float, ctx: Context) -> dict {
    m = current(ctx);
    if m is None {
        return NO_GOAL;
    }
    args = {"node_id": node_id, "item_name": item_name, "payment_url": payment_url, "price": price};
    return logged(m, "purchase", args, vet_and_buy(m, "mcp", node_id, item_name, payment_url, price));
}

with entry:__main__ {
    # Hosts like Render set PORT: serve streamable HTTP at /mcp. Otherwise stdio for local clients.
    if os.getenv("PORT") {
        mcp.run(transport="streamable-http", host="0.0.0.0", port=int(os.environ["PORT"]));
    } else {
        mcp.run();
    }
}

# file: prompts/CreatePlanGraph.md
# Create a plan graph

Plan how to achieve this goal: **{{Goal}}**

Stay under the budget: **${{Budget}}** (USD).

Break the goal into subgoals, and subgoals into smaller subgoals, down to the individual items you need to buy.
Submit the result with `submit_plan`:

- Exactly one node has kind `goal`, and its name is exactly `{{Goal}}` (copy it character for character).
- Nodes of kind `item` are single purchasable products. Give each a realistic estimated `price`.
- Nodes of kind `subgoal` group related steps.
- Every edge points from child to parent: `item -> subgoal`, `subgoal -> subgoal`, or `subgoal -> goal`.
- Every node except the goal has exactly one parent, and every node leads to the goal.
- The price of every subgoal and of the goal is exactly the sum of its children's prices. The goal's price must not exceed the budget.
- Every child must genuinely contribute to its parent.

Example shape (a different goal):

```json
{
  "nodes": [
    {"id": "goal", "kind": "goal", "name": "Paint the bedroom", "price": 72},
    {"id": "supplies", "kind": "subgoal", "name": "Painting supplies", "price": 72},
    {"id": "paint", "kind": "item", "name": "1 gallon interior eggshell paint", "price": 45},
    {"id": "roller", "kind": "item", "name": "9 inch roller kit", "price": 27}
  ],
  "edges": [
    {"child": "supplies", "parent": "goal"},
    {"child": "paint", "parent": "supplies"},
    {"child": "roller", "parent": "supplies"}
  ]
}
```

Work autonomously: do not stop to ask the user questions or for confirmation. The user's request is your full mandate.
If details are missing (sizes, preferences, dates, quantities), pick sensible defaults that fit the goal and budget, and proceed.

When the plan is accepted, buy each item with `purchase`. If an item costs more than its estimate,
update the estimate (and the sums above it), resubmit the plan, then buy it.
Keep going until every item is bought, then report what you bought and any assumptions you made.

# file: services/api.jac
"""Endpoints for the human, the only party that can create a mandate or move it forward.

Every endpoint is `def:priv`: it needs a login token and runs on the caller's own root, so one
user's mandates, agents and evidence are invisible to everyone else. Agents get no endpoints and
no credentials at all; the harness calls their tools in-process.
"""
import time;
import from services.models { Mandate, MandateSummary, Event }
import from services.view { MandateView, AttemptView, BuyView, Decision, ChatItem, TraceRow, Check, CardView, PathView, build_view }
import from services.vetting { extract_mandate, retrying, MandateDraft, money }
import from services.harness { start, say, step }

"""A mandate id is only honoured if the mandate hangs off the caller's root (`jobj` alone never authorizes)."""
def _mine(mandate_id: str) -> Mandate {
    for m in [root -->[?:Mandate]] {
        if jid(m) == mandate_id {
            return m;
        }
    }
    raise ValueError("No such mandate.");
}

"""Read the goal and budget out of the human's own words, for them to confirm."""
def:priv read_mandate(prompt: str) -> MandateDraft {
    if not prompt.strip() {
        raise ValueError("Write what you want to get done, including a budget.");
    }
    return retrying(extract_mandate, prompt.strip()) as MandateDraft;
}

"""Create a mandate from the confirmed goal and budget and start its lead agent."""
def:priv start_mandate(prompt: str, goal: str, budget: float, rogue: bool) -> MandateView {
    if not prompt.strip() or not goal.strip() or not budget > 0 {
        raise ValueError("Goal and a budget above $0 are required.");
    }
    m = Mandate(goal=goal.strip(), budget=money(budget), request=prompt.strip(), rogue=rogue, created_at=time.time());
    root ++> m;
    start(m);
    return build_view(m);
}

"""Advance the agents by one step and return the new view; the UI calls this until `busy` is false."""
def:priv agent_step(mandate_id: str) -> MandateView {
    m = _mine(mandate_id);
    step(m);
    return build_view(m);
}

def:priv mandate_view(mandate_id: str) -> MandateView {
    return build_view(_mine(mandate_id));
}

"""The human replies to the lead agent."""
def:priv send_reply(mandate_id: str, text: str) -> MandateView {
    if not text.strip() {
        raise ValueError("Write a reply first.");
    }
    m = _mine(mandate_id);
    if not say(m, text.strip()) {
        raise ValueError("The agent is still working.");
    }
    return build_view(m);
}

def:priv list_mandates() -> list[MandateSummary] {
    out = [MandateSummary(id=jid(m), goal=m.goal, budget=m.budget, spent=m.spent, rogue=m.rogue, created_at=m.created_at) for m in [root -->[?:Mandate]]];
    return sorted(out, key=lambda s: MandateSummary : s.created_at, reverse=True);
}

"""The whole audit log of one mandate, oldest first. The UI rebuilds its view from it."""
def:priv mandate_log(mandate_id: str) -> list[dict] {
    m = _mine(mandate_id);
    return [e.to_dict() for e in sorted([m -->[?:Event]], key=lambda e: Event : e.seq)];
}

