def:pub FilterBar(
    filters: dict,
    onChange: Callable[[dict], None],
    showDistance: bool = True,
    dark: bool = True
) -> JsxElement {
    has draft: str = "",
        asking: bool = False,
        askError: str = "";

    cats: list[str] = filters["categories"] or [];
    kinds: list[str] = filters["kinds"] or [];
    price: str = filters["price"] or "any";
    time: str = filters["time"] or "week";
    date: str = filters["date"] or "";
    distance: float = filters["distance"] or 0.0;
    reply: str = filters["reply"] or "";
    include_posted: bool = filters["community"] != False;
    dateChips: list[dict] = future_date_chips(14);
    dayValue: str = date if date else "any";

    def patch(key: str, val: any) {
        nxt = {** filters};
        nxt[key] = val;
        onChange(nxt);
    }

    def toggle_cat(c: str) {
        if c in cats {
            patch(
                "categories",
                [
                    x
                    for x in cats
                    if x != c
                ]
            );
        } else {
            patch("categories", cats + [c]);
        }
    }

    def toggle_kind(k: str) {
        if k in kinds {
            patch(
                "kinds",
                [
                    x
                    for x in kinds
                    if x != k
                ]
            );
        } else {
            patch("kinds", kinds + [k]);
        }
    }

    # Bind outside the JSX loop so each chip captures its own value (Jac/JS closure).
    def bind_toggle_cat(c: str) -> Callable[[], None] {
        return lambda { toggle_cat(c); };
    }

    def bind_toggle_kind(k: str) -> Callable[[], None] {
        return lambda { toggle_kind(k); };
    }

    def on_day_select(v: str) {
        if not v or v == "any" {
            patch("date", "");
        } else {
            patch("date", v);
        }
    }

    def set_distance_preset(mi: float) {
        patch("distance", mi);
    }

    def bind_distance(mi: float) -> Callable[[], None] {
        return lambda { set_distance_preset(mi); };
    }

    async def ask -> None {
        text = draft.strip();
        if not text {
            return;
        }
        asking = True;
        askError = "";
        try {
            # Plain dict: FilterSpec is a server type with no constructor in the browser
            # bundle (new FilterSpec threw, so Ask always failed). The server builds it.
            prior: any = {
                "query": filters["query"] or "",
                "categories": cats,
                "kinds": kinds,
                "price": price,
                "time": time,
                "date": date,
                "community": include_posted,
                "community_only": False,
                "distance": distance,
                "reply": ""
            };
            spec = await converse_query(text, prior);
            onChange(
                {
                    "categories": spec.categories,
                    "kinds": spec.kinds,
                    "price": spec.price,
                    "time": spec.time,
                    "date": spec.date or "",
                    "community": spec.community,
                    "community_only": False,
                    "distance": spec.distance,
                    "reply": spec.reply,
                    "query": text
                }
            );
            draft = "";
        } except Exception {
            askError = "Could not read that request. Try again.";
        }
        asking = False;
    }

