def:pub WelcomePage(dark: bool = True) -> JsxElement {
    has step: int = 1,
        opts: dict = {"places": [], "categories": [], "organizers": []},
        ready: bool = False,
        editing: bool = False,
        home_key: str = "",
        home_label: str = "",
        home_lat: float = 0.0,
        home_lng: float = 0.0,
        home_dist: float = -1.0,
        commute: str = "",
        dest_key: str = "pl-central",
        dest_label: str = "",
        route: list[dict] = [],
        interests: list[str] = [],
        follows: list[str] = [],
        saving: bool = False,
        err: str = "";

    nav = useNavigate();

    async can with entry {
        w: any = window;
        if "reset=1" in (w.location.search or "") {
            reset_identity();
            nav("/welcome", {"replace": True});
        }
        # Both requests run at once, so a dead API costs one 8 s timeout, not two.
        opts_req: any = with_timeout(onboarding_options(), None);
        prof_req: any = load_profile();
        o: any = None;
        try {
            o = await opts_req;
        } except Exception {
            o = None;
        }
        opts = o if o is not None else FALLBACK_OPTIONS;
        prof: dict = await prof_req;
        if prof["ok"] and prof["onboarded"] {
            editing = True;
            home_key = prof["home_key"];
            home_label = prof["home_label"];
            home_lat = prof["home_lat"];
            home_lng = prof["home_lng"];
            commute = prof["commute"];
            dest_key = prof["dest_key"] or "pl-central";
            dest_label = prof["dest_label"];
            interests = prof["interests"];
            follows = prof["follows"];
        }
        ready = True;
    }

    can with (home_key, dest_key) entry {
        refresh_route();
    }

    async def refresh_route -> None {
        hk: str = home_key;
        dk: str = dest_key;
        if not hk {
            route = [];
            return;
        }
        w: any = window;
        seq: int = (w.__pulseRouteSeq or 0) + 1;
        w.__pulseRouteSeq = seq;
        rows: list[dict] = [];
        fallback: list[dict] = [{"key": hk, "name": place_name(hk)}] + ([{"key": dk, "name": place_name(dk)}] if dk and dk != hk else []);
        try {
            got: any = await with_timeout(route_places(hk, dk), None);
            rows = got if got is not None and len(got) > 0 else fallback;
        } except Exception {
            rows = fallback;
        }
        if w.__pulseRouteSeq == seq {
            route = rows;
        }
    }

    def place_name(key: str) -> str {
        places: list[dict] = opts["places"] or [];
        for pl in places {
            if pl["key"] == key {
                name: str = pl["name"];
                return name;
            }
        }
        return "";
    }

    # "1100, Beal Avenue, Ann Arbor, ..." -> "1100 Beal Avenue" (OSM splits house numbers off).
    def short_label(label: str) -> str {
        parts: list[str] = [x.strip() for x in label.split(",")];
        if len(parts) > 1 and len(parts[0]) <= 6 {
            return parts[0] + " " + parts[1];
        }
        return parts[0] if len(parts) > 0 else label;
    }

    def choose_home_preset(key: str) {
        home_key = key;
        home_label = "";
        home_lat = 0.0;
        home_lng = 0.0;
        home_dist = -1.0;
        err = "";
    }

    async def choose_home_address(lat: float, lng: float, label: str) -> None {
        err = "";
        home_label = label;
        home_lat = lat;
        home_lng = lng;
        hit: any = None;
        try {
            hit = await with_timeout(nearest_place(lat, lng), None);
        } except Exception {
            hit = None;
        }
        if hit is None or not hit["key"] {
            err = "We couldn't place that address. Tap your neighborhood below instead.";
            return;
        }
        home_key = hit["key"];
        home_dist = hit["dist"];
    }

    def choose_dest_preset(key: str) {
        dest_key = key;
        dest_label = "";
    }

    async def choose_dest_address(lat: float, lng: float, label: str) -> None {
        hit: any = None;
        try {
            hit = await with_timeout(nearest_place(lat, lng), None);
        } except Exception {
            hit = None;
        }
        if hit is None or not hit["key"] {
            err = "We couldn't place that address. Tap a spot above instead.";
            return;
        }
        dest_label = label;
        dest_key = hit["key"];
    }

    def toggle_interest(c: str) {
        if c in interests {
            interests = [x for x in interests if x != c];
        } else {
            interests = interests + [c];
        }
    }

    def toggle_follow(k: str) {
        if k in follows {
            follows = [x for x in follows if x != k];
        } else {
            follows = follows + [k];
        }
    }

    # Up to 5 organizers whose events share the most categories with the picked interests.
    def suggested_orgs() -> list[dict] {
        all_orgs: list[dict] = opts["organizers"] or [];
        out: list[dict] = [];
        best: int = 10;
        while best >= 0 and len(out) < 5 {
            for o in all_orgs {
                cats: list[str] = o["categories"];
                overlap: int = len([c for c in cats if c in interests]);
                wanted: bool = overlap > 0 or o["key"] in follows;
                if wanted and overlap == best and len(out) < 5 {
                    out.append(o);
                }
            }
            best = best - 1;
        }
        return out;
    }

    def org_sub(o: dict) -> str {
        kind: str = o["type"];
        cats: list[str] = o["categories"];
        return kind + " · " + ", ".join(cats[:3]);
    }

    def can_continue() -> bool {
        if step == 1 {
            return home_key != "";
        }
        if step == 2 {
            return commute != "";
        }
        return len(interests) >= 2;
    }

    def go_back(e: MouseEvent) {
        err = "";
        if step > 1 {
            step = step - 1;
        } else {
            nav("/monday");
        }
    }

    def go_next(e: MouseEvent) {
        if not can_continue() {
            return;
        }
        err = "";
        if step < STEP_COUNT {
            step = step + 1;
        } else {
            finish();
        }
    }

    async def finish -> None {
        if saving {
            return;
        }
        saving = True;
        err = "";
        via_keys: list[str] = [r["key"] for r in route];
        res: dict = {"ok": False, "error": ""};
        timed_out: dict = {"ok": False, "error": "Saving is taking too long. Check your connection and try again."};
        try {
            res = await with_timeout(save_profile(
                browser_uid(), home_key, home_lat, home_lng, home_label, commute,
                via_keys, dest_key, dest_label, interests, follows
            ), timed_out);
        } except Exception {
            res = {"ok": False, "error": "Can't reach the A2 Pulse server. Check your connection and try again."};
        }
        if not res["ok"] {
            saving = False;
            err = res["error"] or "Could not save your profile. Try again.";
            return;
        }
        await load_profile(True);
        saving = False;
        nav("/monday?who=you");
    }

