/* ============================================================
   PlateMate - cozy community-bulletin-board styling
   Warm neutrals + tomato accent. Paper texture, rounded,
   hand-drawn feel. No gradients, no emojis.
   ============================================================ */

:root {
  --cream: #fdf6ec;
  --paper: #f7ecd9;
  --card: #fffdf7;
  --ink: #3d2c22;
  --ink-soft: #6d594a;
  --terracotta: #c96f4a;
  --terracotta-dark: #a8532f;
  --tomato: #d4452f;
  --leaf: #5c8a4e;
  --leaf-dark: #3f6b34;
  --mustard: #e3a72f;
  --line: #e4d3ba;
  --wobble: 255px 15px 225px 15px / 15px 225px 15px 255px;
  --shadow: 0 3px 0 rgba(61, 44, 34, 0.12);
}

* { box-sizing: border-box; }

/* PlateMate smiley cursor everywhere (32px image, fallback to pointer). */
body {
  cursor: url("/compiled/assets/cursor.png") 4 2, auto;
}
button, a, input, select, textarea, summary, [role="button"] {
  cursor: url("/compiled/assets/cursor.png") 4 2, pointer;
}

