    radial-gradient(rgba(201, 111, 74, 0.05) 1px, transparent 1.6px);
  background-size: 26px 26px, 41px 41px;
  background-position: 0 0, 13px 19px;
  line-height: 1.55;
}

h1, h2, h3, h4 { line-height: 1.2; margin: 0 0 0.5rem 0; }
