"""Post an unfilled slot as an open shift. Only employees who pass every rule are told about it."""
@guarded
def:protect post_open_shift(
    day: any = UNSET, start: any = UNSET, end: any = UNSET, position_id: any = UNSET, week: str = ""
) -> dict[str, any] {
    day = opt(day);
    start = opt(start);
    end = opt(end);
    position_id = opt(position_id);
    d = me_employer();
    (dy, s, e) = slot_args(day, start, end);
    pid = position_arg(d, position_id);
    wk = week_arg(week);
    did = jid(d);
    add_shift(
        d,
        Shift(week=wk, day=dy, start=s, end=e, student="", state="open", status="published", position=pid, source="open")
    );
    ledger = Ledger(week=wk);
    notified = 0;
    for st in team_of(d) {
        if ledger.check(jid(st), did, dy, s, e, pid=pid).ok {
            to_student(st, f"{d.name} posted an open shift you can take: {dated(wk, dy, s, e)}.", "/s", title="Open shift");
            notified += 1;
        }
    }
    return {"ok": True, "notified": notified};
}

# file: server/api_membership.jac
"""Sign-up, join codes and employers (public + employee endpoints).

Sign-up is three calls from the web client: `check_signup` (validates everything first, so no half-made
account can exist), the platform's /user/register + /user/login (Jac's built-in auth), then
`register_employer` / `register_employee`, which create the profile for the signed-in login.
"""

import re;
import from zoneinfo { ZoneInfo }
import from server.clock { now_s }
import from server.config {
    TIMEZONE,
    DEFAULT_PAY_RATE,
    INTERNATIONAL_WEEKLY_CAP,
    WORKER_WEEKLY_LIMIT
}
import from server.notify { log_event }
import from server.models {
    Account,
    Employer,
    Employee,
    Employment,
    Position,
    University,
    hub,
    put,
    employer_of,
    university_of,
    position_of
}
import from server.membership {
    JoinError,
    normalize_code,
    employer_by_code,
    new_join_code,
    university_named,
    org_card,
    can_join,
    add_member,
    leave_team
}
import from server.api_common {
    ApiError,
    guarded,
    me,
    me_student,
    check_email,
    check_password,
    account_by_email,
    session_payload
}

def _tz(value: str) -> str {
    name = str(value or "").strip();
    try {
        ZoneInfo(name);
        return name;
    } except Exception {
        return TIMEZONE;
    }
}

def _clean_name(v: str, n: int) -> str {
    return re.sub(r"\s+", " ", str(v or "").strip())[:n];
}

# ------------------------------------------------------------------ public
@guarded
def:pub lookup_join_code(code: str = "") -> dict[str, any] {
    d = employer_by_code(str(code or ""));
    if d is None {
        raise ApiError("No employer uses that code. Check it with your manager.");
    }
    return org_card(d);
}

@guarded
def:pub list_universities(query: str = "") -> dict[str, any] {
    q = str(query or "").strip().lower();
    rows = sorted(
        [u for u in [hub() --> [?:University]] if not q or q in u.name.lower()],
        key=lambda (u: University) -> str { return u.name; }
    )[:20];
    return {"universities": [{"id": jid(u), "name": u.name} for u in rows]};
}

"""Validate a sign-up before the login is created (so a failed sign-up never leaves an account behind)."""
@guarded
def:pub check_signup(
    role: str = "",
    email: str = "",
    password: str = "",
    name: str = "",
    organization: str = "",
    kind: str = "",
    university: str = "",
    code: str = "",
    status: str = ""
) -> dict[str, any] {
    if role == "department" {
        org = _clean_name(organization, 120);
        if len(org) < 2 {
            raise ApiError("Enter your organization's name.");
        }
        if not str(name or "").strip() {
            raise ApiError("Missing name.");
        }
        check_email(email);
        check_password(password);
        if kind == "campus" and not _clean_name(university, 160) {
            raise ApiError("Enter your university's name.");
        }
    } else {
        nm = _clean_name(name, 120);
        if len(nm) < 2 {
            raise ApiError("Enter your full name.");
        }
        d = employer_by_code(str(code or ""));
        if d is None {
            raise ApiError("No employer uses that join code. Check it with your manager.");
        }
        check_email(email);
        check_password(password);
        k = "worker" if kind == "worker" else "student";
        probe = Employee(name=nm, kind=k, school=d.university if k == "student" else "", status="domestic");
        reason = can_join(probe, d);
        if reason {
            raise ApiError(reason);
        }
    }
    e = check_email(email);
    if account_by_email(e) is not None {
        raise ApiError("An account with this email already exists. Try signing in.");
    }
    return {"ok": True};
}

def _new_account(email: str, role: str, name: str, ref: str) -> Account {
    e = email.strip().lower();
    if account_by_email(e) is not None {
        raise ApiError("An account with this email already exists. Try signing in.");
    }
    acc = Account(email=e, role=role, name=name, root_id=jid(root), ref=ref, created=now_s());
    put(hub(), acc);
    return acc;
}

def _no_profile_yet() {
    rid = jid(root);
    if [hub() --> [?:Account, root_id == rid]] {
        raise ApiError("This login already has a CampusSync profile. Sign in instead.");
    }
}

@guarded
def:protect register_employer(
    organization: str = "",
    name: str = "",
    email: str = "",
    kind: str = "business",
    university: str = "",
    timezone: str = "",
    description: str = ""
) -> dict[str, any] {
    _no_profile_yet();
    org = _clean_name(organization, 120);
    person = str(name or "").strip()[:120];
    if len(org) < 2 {
        raise ApiError("Enter your organization's name.");
    }
    if not person {
        raise ApiError("Missing name.");
    }
    e = check_email(email);
    k = "campus" if kind == "campus" else "business";
    uni: University | None = None;
    if k == "campus" {
        uni = university_named(str(university or ""));
        if uni is None {
            raise ApiError("Enter your university's name.");
        }
    }
    code = "";
    try {
        code = new_join_code(org);
    } except JoinError as je {
        raise ApiError(str(je));
    }
    dept = Employer(
        name=org,
        kind=k,
        type="department" if k == "campus" else "vendor",
        university=jid(uni) if uni is not None else "",
        join_code=code,
        timezone=_tz(timezone),
        default_pay_rate=DEFAULT_PAY_RATE,
        default_weekly_hours=20 if k == "campus" else 40,
        description=str(description or "").strip()[:500],
        auto_recruit=k == "campus",
        created=now_s()
    );
    put(hub(), dept);
    acc = _new_account(e, "department", person, jid(dept));
    log_event(
        "Coordinator", f"Welcome to CampusSync · share join code {dept.join_code} with your team", employer=dept, level="done"
    );
    out = session_payload(acc);
    out["department_id"] = jid(dept);
    out["join_code"] = dept.join_code;
    return out;
}

@guarded
def:protect register_employee(
    name: str = "",
    email: str = "",
    code: str = "",
    kind: str = "student",
    status: str = "domestic",
    student_number: str = ""
) -> dict[str, any] {
    _no_profile_yet();
    nm = _clean_name(name, 120);
    if len(nm) < 2 {
        raise ApiError("Enter your full name.");
    }
    dept = employer_by_code(str(code or ""));
    if dept is None {
        raise ApiError("No employer uses that join code. Check it with your manager.");
    }
    e = check_email(email);
    k = "worker" if kind == "worker" else "student";
    st: Employee | None = None;
    if k == "student" {
        stat = "international" if status == "international" else "domestic";
        limit = INTERNATIONAL_WEEKLY_CAP if stat == "international" else 20;
        st = Employee(
            name=nm, email=e, kind="student", school=dept.university, status=stat, weekly_limit=limit,
            student_number=str(student_number or "").strip()[:40], desired_hours=0, preferences=[],
            open_swap_days=[], created=now_s()
        );
    } else {
        st = Employee(
            name=nm, email=e, kind="worker", status="domestic", weekly_limit=WORKER_WEEKLY_LIMIT, desired_hours=0,
            preferences=[], open_swap_days=[], created=now_s()
        );
    }
    person: Employee = st;
    reason = can_join(person, dept);
    if reason {
        raise ApiError(reason);
    }
    put(hub(), person);
    acc = _new_account(e, "student", nm, jid(person));
    add_member(person, dept);
    out = session_payload(acc);
    out["student_id"] = jid(person);
    out["employer"] = org_card(dept);
    return out;
}

# ------------------------------------------------------------------ employee
@guarded
def:protect join_employer(code: str = "") -> dict[str, any] {
    st = me_student();
    dept = employer_by_code(str(code or ""));
    if dept is None {
        raise ApiError("No employer uses that join code. Check it with your manager.");
    }
    reason = can_join(st, dept);
    if reason {
        raise ApiError(reason);
    }
    if st.kind == "student" and not st.school {
        st.school = dept.university;
    }
    add_member(st, dept);
    return {"ok": True, "employer": org_card(dept)};
}

@guarded
def:protect leave_employer(department_id: str = "") -> dict[str, any] {
    st = me_student();
    dept = employer_of(str(department_id or ""));
    if dept is None {
        raise ApiError("Employer not found.");
    }
    released = 0;
    try {
        released = leave_team(st, dept);
    } except JoinError as je {
        raise ApiError(str(je));
    }
    return {"ok": True, "released": released};
}

@guarded
def:protect get_my_employers() -> dict[str, any] {
    st = me_student();
    rows = sorted(
        [e for e in [st --> [?:Employment]] if e.state in ("active", "invited")],
        key=lambda (e: Employment) -> str { return e.created; }
    );
    out: list[dict[str, any]] = [];
    for e in rows {
        d = employer_of(e.employer);
        if d is None {
            continue;
        }
        roles: list[str] = [];
        for pid in (e.positions or []) {
            p = position_of(pid);
            if p is not None {
                roles.append(p.name);
            }
        }
        card = org_card(d);
        card["state"] = e.state;
        card["hours"] = e.hours;
        card["pay_rate"] = e.pay_rate;
        card["roles"] = roles;
        out.append(card);
    }
    uni = university_of(st.school);
    return {
        "employers": out,
        "kind": st.kind,
        "university": uni.name if uni is not None else None,
        "can_join_more": st.kind == "student" or not any([e.state == "active" for e in rows])
    };
}

# repo: mm-25__JacHacks

# file: apps/web/services/memories.sv.jac
node connected to that workspace:

    root --> Workspace --> Memory, Memory, ...

All endpoints except `health` are authenticated (`def:priv`), so each caller
only ever reads and writes their own workspace (NFR-004). Deletes are soft
(`deleted_at` is set) so demo mistakes can be undone (FR-052).

New workspaces start empty. Sample data is only loaded by `load_demo_data`
(the web app's "Open the demo workspace" button), which also marks the
workspace as a demo so that `reset_demo` is allowed on it.

The wire shapes (`MemoryView`, `MemorySource`, `MemoryPage`) mirror the
`Memory` contract in REQUIREMENTS.md, including camelCase field names, so
mobile and desktop clients can call the same `/function/<name>` endpoints.
"""

import from datetime { datetime, timezone, timedelta }

# How an item reached Sherry: typed in a Sherry app, saved by an assistant via
# MCP, captured from a website by the browser extension, captured from local AI
# tool logs by the desktop app, or bulk-imported.
glob CAPTURE_CHANNELS: list[str] = ["app", "mcp", "extension", "desktop", "import"];
glob SOURCE_TYPES: list[str] = ["manual_note", "conversation_excerpt", "import"];
glob SOURCE_PLATFORMS: list[str] = [
         "web",
         "desktop",
         "mobile",
         "chatgpt",
         "claude",
         "gemini",
         "codex",
         "antigravity"
     ];
glob MAX_CONTENT: int = 20000;
glob MAX_TAGS: int = 20;
glob MAX_TAG_LEN: int = 40;
glob MAX_LABEL_LEN: int = 120;
glob MAX_CONTEXT_LEN: int = 200;
glob DEFAULT_LIMIT: int = 25;
glob MAX_LIMIT: int = 100;


node Workspace {
    has name: str = "My workspace",
        created_at: str = "",
        is_demo: bool = False;
}


node Memory {
    has content: str,
        tags: list[str] = [],
        source_type: str = "manual_note",
        source_platform: str = "web",
        source_label: str = "",
        source_url: str = "",
        source_context: str = "",
        captured_via: str = "app",
        conversation_id: str = "",
        idempotency_key: str = "",
        created_at: str = "",
        updated_at: str = "",
        deleted_at: str = "";
}


obj MemorySource {
    has `type: str,
        platform: str,
        label: str | None = None,
        url: str | None = None,
        context: str | None = None,
        capturedVia: str = "app",
        conversationId: str | None = None;
}


obj MemoryView {
    has id: str,
        workspaceId: str,
        content: str,
        tags: list[str],
        source: MemorySource,
        createdAt: str,
        updatedAt: str,
        deletedAt: str | None = None;
}


obj MemoryPage {
    has data: list[MemoryView],
        nextCursor: str | None = None,
        total: int = 0;
}


obj SeedItem {
    has key: str,
        content: str,
        tags: list[str],
        source_type: str,
        source_platform: str,
        source_label: str,
        source_url: str = "";
}


obj HealthStatus {
    has ok: bool,
        service: str,
        time: str;
}


def _now_iso -> str {
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace(
        "+00:00", "Z"
    );
}


"""Read a field that newer versions of Sherry added to a node type. Nodes saved
before the field existed don't have it, so fall back to its default. Always
use this for fields added after launch (source_context, context,
captured_via on chats, sent_at)."""
def _field(n: any, name: str, fallback: str) -> str {
    value = getattr(n, name, fallback);
    return str(value) if value is not None else fallback;
}


def _workspace -> Workspace {
    found = [root-->][?:Workspace];
    if len(found) > 0 {
        return found[0];
    }
    return (root ++> Workspace(name="My workspace", created_at=_now_iso()))[0];
}


def _view(m: Memory, ws: Workspace) -> MemoryView {
    return MemoryView(
        id=jid(m),
        workspaceId=jid(ws),
        content=m.content,
        tags=list(m.tags),
        source=MemorySource(
            `type=m.source_type,
            platform=m.source_platform,
            label=m.source_label or None,
            url=m.source_url or None,
            context=_field(m, "source_context", "") or None,
            capturedVia=m.captured_via or "app",
            conversationId=m.conversation_id or None
        ),
        createdAt=m.created_at,
        updatedAt=m.updated_at,
        deletedAt=m.deleted_at or None
    );
}


def _find(ws: Workspace, id: str) -> Memory | None {
    for m in [ws-->][?:Memory] {
        if jid(m) == id {
            return m;
        }
    }
    return None;
}


def _matches(m: Memory, needle: str) -> bool {
    if needle in m.content.lower() {
        return True;
    }
    if needle in m.source_label.lower() or needle in m.source_platform {
        return True;
    }
    if needle in _field(m, "source_context", "").lower() {
        return True;
    }
    for t in m.tags {
        if needle in t.lower() {
            return True;
        }
    }
    return False;
}


def _clean_tags(tags: list[str]) -> list[str] {
    cleaned: list[str] = [];
    for raw in tags {
        t = raw.strip().lstrip("#").lower();
        if not t or t in cleaned {
            continue;
        }
        if len(t) > MAX_TAG_LEN {
            raise ValueError(f"Tags can be at most {MAX_TAG_LEN} characters.");
        }
        cleaned.append(t);
    }
    if len(cleaned) > MAX_TAGS {
        raise ValueError(f"A memory can have at most {MAX_TAGS} tags.");
    }
    return cleaned;
}


def _by_created(m: Memory) -> str {
    return m.created_at;
}


"""Liveness probe. Public so clients can tell 'API down' from 'signed out'."""
def:pub health -> HealthStatus {
    return HealthStatus(ok=True, service="sherry-api", time=_now_iso());
}


"""List active memories, newest first, with optional case-insensitive search
over content, tags, source label and platform. `cursor` is an opaque offset
string returned as `nextCursor` by the previous page. `kind` narrows the list:
"chat" (summaries of captured chats) or "personal" (everything else)."""
def:priv list_memories(
    query: str = "", cursor: str = "", limit: int = 25, kind: str = ""
) -> MemoryPage {
    ws = _workspace();
    needle = query.strip().lower();
    active = [
        m
        for m in [ws-->][?:Memory]
        if not m.deleted_at
    ];
    if needle {
        active = [
            m
            for m in active
            if _matches(m, needle)
        ];
    }
    if kind == "chat" or kind == "personal" {
        active = [
            m
            for m in active
            if bool(_field(m, "conversation_id", "")) == (kind == "chat")
        ];
    }
    active.sort(key=_by_created, reverse=True);
    start = int(cursor) if cursor.isdigit() else 0;
    size = max(1, min(limit, MAX_LIMIT));
    window = active[start:start + size];
    next_cursor = str(start + size) if start + size < len(active) else None;
    return MemoryPage(
        data=[_view(m, ws) for m in window], nextCursor=next_cursor, total=len(active)
    );
}


"""Fetch one active memory with full content and provenance."""
def:priv get_memory(id: str) -> MemoryView | None {
    ws = _workspace();
    m = _find(ws, id);
    if m is None or m.deleted_at {
        return None;
    }
    return _view(m, ws);
}


"""Create a memory. Replaying the same `idempotency_key` returns the memory
created the first time instead of a duplicate (FR-041, AT-03)."""
def:priv create_memory(
    content: str,
    source_platform: str,
    idempotency_key: str,
    tags: list[str] | None = None,
    source_type: str = "manual_note",
    source_label: str = "",
    source_url: str = "",
    captured_via: str = "app",
    source_context: str = ""
) -> MemoryView {
    ws = _workspace();
    key = idempotency_key.strip();
    if len(key) < 16 or len(key) > 128 {
        raise ValueError("idempotency_key must be 16-128 characters.");
    }
    for existing in [ws-->][?:Memory] {
        if existing.idempotency_key == key {
            return _view(existing, ws);
        }
    }
    body = content.strip();
    if not body {
        raise ValueError("Memory content is required.");
    }
    if len(body) > MAX_CONTENT {
        raise ValueError(f"Memory content can be at most {MAX_CONTENT} characters.");
    }
    if source_type not in SOURCE_TYPES {
        raise ValueError(f"Unknown source type '{source_type}'.");
    }
    if source_platform not in SOURCE_PLATFORMS {
        raise ValueError(f"Unknown source platform '{source_platform}'.");
    }
    if captured_via not in CAPTURE_CHANNELS {
        raise ValueError(f"Unknown capture channel '{captured_via}'.");
    }
    label = source_label.strip();
    if len(label) > MAX_LABEL_LEN {
        raise ValueError(f"Source label can be at most {MAX_LABEL_LEN} characters.");
    }
    url = source_url.strip();
    if url and not (url.startswith("https://") or url.startswith("http://")) {
        raise ValueError("Source URL must start with http:// or https://.");
    }
    context = source_context.strip();
    if len(context) > MAX_CONTEXT_LEN {
        raise ValueError(f"Source context can be at most {MAX_CONTEXT_LEN} characters.");
    }
    stamp = _now_iso();
    m = Memory(
        content=body,
        tags=_clean_tags(tags or []),
        source_type=source_type,
        source_platform=source_platform,
        source_label=label,
        source_url=url,
        source_context=context,
        captured_via=captured_via,
        idempotency_key=key,
        created_at=stamp,
        updated_at=stamp
    );
    ws ++> m;
    return _view(m, ws);
}


"""Soft-delete a memory. Returns False when it does not exist."""
def:priv delete_memory(id: str) -> bool {
    ws = _workspace();
    m = _find(ws, id);
    if m is None or m.deleted_at {
        return False;
    }
    stamp = _now_iso();
    m.deleted_at = stamp;
    m.updated_at = stamp;
    if m.conversation_id {
        _forget_conversation(ws, m.conversation_id, True);
    }
    return True;
}


"""Undo a soft delete (backs the 'Undo' action after deleting)."""
def:priv restore_memory(id: str) -> MemoryView | None {
    ws = _workspace();
    m = _find(ws, id);
    if m is None {
        return None;
    }
    m.deleted_at = "";
    m.updated_at = _now_iso();
    if m.conversation_id {
        _forget_conversation(ws, m.conversation_id, False);
    }
    return _view(m, ws);
}


node CapturedConversation {
    has platform: str,
        external_id: str,
        url: str = "",
        title: str = "",
        context: str = "",
        captured_via: str = "extension",
        created_at: str = "",
        updated_at: str = "",
        summarized_hash: str = "",
        summarized_at: str = "",
        summary_engine: str = "",
        summary_note: str = "",
        ignored: bool = False;
}


node CapturedMessage {
    has key: str,
        role: str,
        text: str,
        position: int = 0,
        sent_at: str = "",
        captured_at: str = "",
        updated_at: str = "";
}


"""Deleting a chat summary is a privacy action: the captured transcript is
erased and the chat is ignored from then on. Undo lifts the ignore flag; the
transcript is re-captured the next time the chat is open."""
def _forget_conversation(ws: Workspace, conversation_id: str, forget: bool) {
    for c in [ws-->][?:CapturedConversation] {
        if jid(c) != conversation_id {
            continue;
        }
        c.ignored = forget;
        c.updated_at = _now_iso();
        if forget {
            for msg in [c-->][?:CapturedMessage] {
                del msg;
            }
            c.summarized_hash = "";
        }
    }
}


"""Turn this workspace into the demo workspace: mark it as a demo and add the
sample memories if they are not there yet. Safe to call repeatedly."""
def:priv load_demo_data -> MemoryPage {
    ws = _workspace();
    ws.is_demo = True;
    has_seed = False;
    for m in [ws-->][?:Memory] {
        if m.idempotency_key.startswith("seed-") {
            has_seed = True;
        }
    }
    if not has_seed {
        _seed(ws);
    }
    return list_memories("", "", DEFAULT_LIMIT);
}


"""Wipe a demo workspace and restore the deterministic seed data (FR-061).
Refuses on real workspaces so a stray call can't erase a user's memories."""
def:priv reset_demo -> MemoryPage {
    ws = _workspace();
    if not ws.is_demo {
        raise ValueError("Only the demo workspace can be reset.");
    }
    for m in [ws-->][?:Memory] {
        del m;
    }
    _seed(ws);
    return list_memories("", "", DEFAULT_LIMIT);
}


def _seed(ws: Workspace) {
    base = datetime(2026, 9, 26, 18, 0, 0, tzinfo=timezone.utc);
    for (i, s) in enumerate(SEED) {
        stamp = (base - timedelta(hours=i * 7)).isoformat(
            timespec="milliseconds"
        ).replace(
            "+00:00", "Z"
        );
        ws ++> Memory(
            content=s.content,
            tags=list(s.tags),
            source_type=s.source_type,
            source_platform=s.source_platform,
            source_label=s.source_label,
            source_url=s.source_url,
            idempotency_key=f"seed-{s.key}-0000000000",
            created_at=stamp,
            updated_at=stamp
        );
    }
}


