"""Agent feed + notifier.

log_event: the live feed on Mission Control and in the employee app. Employer events never name
another employer; employee events are shown to that employee only.

Notifications are in-app and also delivered as phone push (see push.jac). `dedupe_key` makes an
alert idempotent: the alert scheduler runs every few seconds and each reminder still goes out once.
"""

import from server.clock { now_s }
import from server.models {
    Employer,
    Employee,
    AgentEvent,
    Notification,
    put
}

def log_event(
    agent: str,
    text: str,
    kind: str = "agent",
    employer: Employer | None = None,
    student: Employee | None = None,
    level: str = "info",
    link: str = ""
) {
    ev = AgentEvent(
        agent=agent,
        kind=kind,
        text=text[:400],
        level=level,
        link=link,
        created=now_s(),
        employer=jid(employer) if employer is not None else "",
        student=jid(student) if student is not None else ""
    );
    if employer is not None {
        put(employer, ev);
    } elif student is not None {
        put(student, ev);
    }
}

def _add(
    owner: any,
    student_id: str,
    employer_id: str,
    text: str,
    link: str,
    title: str,
    kind: str,
    dedupe_key: str,
    push: bool
) -> Notification | None {
    if dedupe_key {
        k = dedupe_key;
        if [owner --> [?:Notification, dedupe_key == k]] {
            return None;
        }
    }
    n = Notification(
        student=student_id,
        employer=employer_id,
        text=text[:1000],
        link=link[:200],
        title=title[:120],
        kind=kind,
        dedupe_key=dedupe_key,
        push=push,
        created=now_s()
    );
    put(owner, n);
    return n;
}

def to_student(
    st: Employee,
    text: str,
    link: str = "",
    title: str = "",
    kind: str = "general",
    dedupe_key: str = "",
    push: bool = True
) -> Notification | None {
    return _add(st, jid(st), "", text, link, title, kind, dedupe_key, push);
}

def to_employer(
    e: Employer,
    text: str,
    link: str = "",
    title: str = "",
    kind: str = "general",
    dedupe_key: str = "",
    push: bool = True
) -> Notification | None {
    return _add(e, "", jid(e), text, link, title, kind, dedupe_key, push);
}

# file: server/payroll.jac
"""Take-home pay estimates. Deterministic code, clearly labelled as an estimate in the UI.

Per week (US, single filer, no extra withholding):
  * Federal income tax: the week's gross annualised (x52), minus the standard deduction, run through
    the 2026 brackets, then divided back by 52 -- the IRS percentage-method idea, simplified.
  * FICA (Social Security 6.2% + Medicare 1.45%): international students on F-1/J-1 visas are
    generally exempt (nonresident aliens), everyone else pays it.
  * State income tax: a flat rate each employer sets (default 4.25%).
"""

glob STANDARD_DEDUCTION_2026: float = 16100.0,
     BRACKETS_2026: list[tuple[float, float]] = [
         (12400.0, 0.10),
         (50400.0, 0.12),
         (105700.0, 0.22),
         (201775.0, 0.24),
         (256225.0, 0.32),
         (640600.0, 0.35),
         (float("inf"), 0.37)
     ],
     SOCIAL_SECURITY: float = 0.062,
     MEDICARE: float = 0.0145;

def federal_annual(taxable: float) -> float {
    tax = 0.0;
    lower = 0.0;
    for (upper, rate) in BRACKETS_2026 {
        if taxable <= lower {
            break;
        }
        tax += (min(taxable, upper) - lower) * rate;
        lower = upper;
    }
    return tax;
}

"""gross_by_state_rate: {state tax % -> gross earned this week under that rate}."""
def weekly_taxes(gross_by_state_rate: dict[float, float], fica_exempt: bool) -> dict[str, float] {
    gross = sum(list(gross_by_state_rate.values()));
    taxable = max(0.0, gross * 52 - STANDARD_DEDUCTION_2026);
    federal = federal_annual(taxable) / 52;
    state = sum([g * (pct / 100) for (pct, g) in gross_by_state_rate.items()]);
    fica = 0.0 if fica_exempt else gross * (SOCIAL_SECURITY + MEDICARE);
    total = federal + state + fica;
    return {
        "gross": round(gross, 2),
        "federal": round(federal, 2),
        "state": round(state, 2),
        "fica": round(fica, 2),
        "taxes": round(total, 2),
        "net": round(gross - total, 2),
        "rate": (total / gross) if gross else 0.0
    };
}

