"""Pomodoro + Calendar -- client."""

import from endpoints {
    Event, Note, Session, Settings,
    list_events, get_event, create_event, update_event,
    add_note, list_notes,
    start_pomodoro, pause_pomodoro, resume_pomodoro, stop_pomodoro,
    advance_phase, current_session,
    get_settings, set_idle_text
}
import from .components.MonthCalendar { MonthCalendar }
import from .components.EventModal { EventModal }
import from .components.PomodoroFloat { PomodoroFloat }
import from .components.SettingsModal { SettingsModal }
import from .components.ui.button { Button }


glob MONTH_NAMES: list[str] = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
];


def days_in_month(y: int, m: int) -> int {
    # `new(Date, y, m, 0)` is day 0 of month `m+1` -> last day of month `m`.
    d = new(Date, y, m, 0);
    return int(d.getDate());
}


def first_weekday(y: int, m: int) -> int {
    d = new(Date, y, m - 1, 1);
    return int(d.getDay());
}


def month_label(y: int, m: int) -> str {
    return MONTH_NAMES[m - 1] + " " + str(y);
}


def next_month(y: int, m: int) -> (int, int) {
    if m == 12 { return (y + 1, 1); }
    return (y, m + 1);
}


def prev_month(y: int, m: int) -> (int, int) {
    if m == 1 { return (y - 1, 12); }
    return (y, m - 1);
}


def:pub app -> JsxElement {
    has events: list[Event] = [];
    has session: Session | None = None;
    has settings: Settings | None = None;

    # Today (fixed on mount) + current calendar view (user-navigable).
    has today_year: int = int(new(Date).getFullYear());
    has today_month: int = int(new(Date).getMonth()) + 1;
    has today_day: int = int(new(Date).getDate());
    has view_year: int = int(new(Date).getFullYear());
    has view_month: int = int(new(Date).getMonth()) + 1;

    # UI state
    has modal_day: int = 0;                  # 0 = closed; else the day number
    has modal_event: Event | None = None;    # existing event being edited
    has settings_open: bool = False;
    has float_expanded: bool = False;

    # Refetch events any time the viewed month changes (mount included).
    async can with [view_year, view_month] entry {
        events = await list_events(view_year, view_month);
    }

    # Session + settings only need to load once, on mount.
    async can with entry {
        session = await current_session();
        settings = await get_settings();
    }

    def open_day_modal(d: int) -> None {
        modal_event = None;
        modal_day = d;
    }

    def open_event_modal(ev: Event) -> None {
        modal_event = ev;
        modal_day = ev.day;
    }

    def close_modal -> None {
        modal_day = 0;
        modal_event = None;
    }

    def on_event_saved(ev: Event) -> None {
        # Replace if exists, else append.
        replaced = False;
        new_list: list[Event] = [];
        for e in events {
            if jid(e) == jid(ev) {
                new_list = new_list + [ev];
                replaced = True;
            } else {
                new_list = new_list + [e];
            }
        }
        events = new_list if replaced else new_list + [ev];
    }

    async def on_start_from_event(ev: Event) -> None {
        session = await start_pomodoro(jid(ev));
        close_modal();
        float_expanded = True;
    }

    async def on_quick_start -> None {
        # Ad-hoc: create a default event for today and start it.
        ev = await create_event(
            today_year, today_month, today_day,
            0, 0,
            "Quick focus", "",
            25, 5, 1
        );
        on_event_saved(ev);
        session = await start_pomodoro(jid(ev));
        float_expanded = True;
    }

    async def on_session_updated(s: Session | None) -> None {
        session = s;
    }

    async def on_settings_saved(s: Settings) -> None {
        settings = s;
        settings_open = False;
    }

    def open_settings -> None { settings_open = True; }
    def close_settings -> None { settings_open = False; }
    def toggle_float -> None { float_expanded = not float_expanded; }

    def go_prev_month -> None {
        (view_year, view_month) = prev_month(view_year, view_month);
    }
    def go_next_month -> None {
        (view_year, view_month) = next_month(view_year, view_month);
    }
    def go_today -> None {
        view_year = today_year;
        view_month = today_month;
    }

    idle_text = settings.idle_text if settings is not None else "( :3 )=3";
    viewing_today = view_year == today_year and view_month == today_month;
    highlight_day = today_day if viewing_today else 0;

    <div className="min-h-screen bg-background text-foreground">
        <header className="border-b border-border">
            <div className="max-w-6xl mx-auto p-4 flex items-center justify-between">
                <h1 className="text-lg font-semibold">Pomodoro + Calendar</h1>
                <div className="flex items-center gap-2">
                    <Button variant="ghost" size="sm" onClick={go_prev_month}>
                        &lt;
                    </Button>
                    <span className="text-sm font-mono min-w-40 text-center">
                        {month_label(view_year, view_month)}
                    </span>
                    <Button variant="ghost" size="sm" onClick={go_next_month}>
                        &gt;
                    </Button>
                    <Button variant="ghost" size="sm" onClick={go_today}>
                        Today
                    </Button>
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={open_settings}
                    >
                        Settings
                    </Button>
                </div>
            </div>
        </header>

        <main className="max-w-6xl mx-auto p-4">
            <MonthCalendar
                year={view_year}
                month={view_month}
                today_day={highlight_day}
                days_in_month={days_in_month(view_year, view_month)}
                first_weekday={first_weekday(view_year, view_month)}
                events={events}
                onSelectDay={open_day_modal}
                onOpenEvent={open_event_modal}
            />
        </main>

        {if modal_day != 0 {
            <EventModal
                day={modal_day}
                year={view_year}
                month={view_month}
                existing={modal_event}
                day_events={[e for e in events if e.day == modal_day]}
                onClose={close_modal}
                onSaved={on_event_saved}
                onStart={on_start_from_event}
                onOpenEvent={open_event_modal}
            />
        }}

        {if settings_open {
            <SettingsModal
                settings={settings}
                onClose={close_settings}
                onSaved={on_settings_saved}
            />
        }}

        <PomodoroFloat
            session={session}
            events={events}
            idle_text={idle_text}
            expanded={float_expanded}
            onToggleExpand={toggle_float}
            onQuickStart={on_quick_start}
            onSessionUpdated={on_session_updated}
        />
    </div>
}

