        comments_open: bool = False, claims_open: bool = False,
        comment_form_open: bool = False, claim_form_open: bool = False;

    async def save_edit {
        busy = True;
        try {
            await edit_media(item.id, item.incident, title, source, description, edit_key());
            editing = False;
            await onRefresh();
        } except Exception as e { error = "Could not save media details: " + write_error(e); }
