                        }}
                        {if not str(im["b64"]) {
                            <div key="stub" className="stat-line rounded-md border border-dashed border-input p-3">{str(im["name"])} · {str(im["note"])}</div>
                            skip;
                        }}
                        <span className="stat-line truncate">{str(im["name"])}</span>
