# file: apps/cloud/src/worker.cl.jac
"""Sherry on Cloudflare Workers: the HTTP entry point.

Keeps the Jac server's API contract, so every existing client (web app,
browser extension, desktop sync, MCP connector) only needs a new address and
key:

    POST /function/<name>     JSON body in, envelope out:
        {"ok": true, "type": "response", "data": {"result": ...}}
        {"ok": true, "type": "response", "data": {"error": "message"}}   bad input (HTTP 200)
        {"ok": false, "type": "error", "error": {...}}                   401 / 404 / 500

Anything else is served from the web app's static files (env.ASSETS) when
they're configured.
"""

import from .util { text_of, now_iso, construct, is_plain_object }
import from .auth { authenticate, ensure_workspace, Principal }
import from .memories {
    list_memories,
    get_memory,
    create_memory,
    delete_memory,
    restore_memory,
    load_demo_data,
    reset_demo
}
import from .captures { capture_conversation, summarize_conversation, get_conversation }
import from .keys { create_api_key, list_api_keys, revoke_api_key }
import from .dashboard { dashboard_stats, list_conversations, delete_conversation }
import from .oauth {
    protected_resource_metadata,
    authorization_server_metadata,
    register_client,
    authorize_start,
    authorize_submit,
    token,
    revoke,
    mcp_caller,
    unauthorized_mcp
}
import from .mcp { handle_mcp }

glob CORS: dict = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "authorization, content-type",
    "Access-Control-Max-Age": "86400"
};


def _json(payload: any, status: int) -> any {
    headers: dict = {**CORS, "Content-Type": "application/json"};
    return construct("Response", [JSON.stringify(payload), {"status": status, "headers": headers}]);
}


def _result(result: any) -> any {
    return _json({"ok": True, "type": "response", "data": {"result": result}, "error": None}, 200);
}


def _rejected(message: str) -> any {
    return _json({"ok": True, "type": "response", "data": {"error": message}, "error": None}, 200);
}


def _failure(status: int, code: str, message: str) -> any {
    return _json({"ok": False, "type": "error", "data": None, "error": {"code": code, "message": message}}, status);
}


"""Run one endpoint. Returns [found, result]."""
async def _dispatch(name: str, env: any, who: Principal, ws: str, body: any) -> list {
    if name == "list_memories" {
        return [True, await list_memories(env, who, ws, body)];
    }
    if name == "get_memory" {
        return [True, await get_memory(env, who, ws, body)];
    }
    if name == "create_memory" {
        return [True, await create_memory(env, who, ws, body)];
    }
    if name == "delete_memory" {
        return [True, await delete_memory(env, who, ws, body)];
    }
    if name == "restore_memory" {
        return [True, await restore_memory(env, who, ws, body)];
    }
    if name == "load_demo_data" {
        return [True, await load_demo_data(env, who, ws, body)];
    }
    if name == "reset_demo" {
        return [True, await reset_demo(env, who, ws, body)];
    }
    if name == "capture_conversation" {
        return [True, await capture_conversation(env, who, ws, body)];
    }
    if name == "summarize_conversation" {
        return [True, await summarize_conversation(env, who, ws, body)];
    }
    if name == "get_conversation" {
        return [True, await get_conversation(env, who, ws, body)];
    }
    if name == "create_api_key" {
        return [True, await create_api_key(env, who, ws, body)];
    }
    if name == "list_api_keys" {
        return [True, await list_api_keys(env, who, ws, body)];
    }
    if name == "revoke_api_key" {
        return [True, await revoke_api_key(env, who, ws, body)];
    }
    if name == "dashboard_stats" {
        return [True, await dashboard_stats(env, who, ws, body)];
    }
    if name == "list_conversations" {
        return [True, await list_conversations(env, who, ws, body)];
    }
    if name == "delete_conversation" {
        return [True, await delete_conversation(env, who, ws, body)];
    }
    if name == "whoami" {
        row: any = await env.DB.prepare("SELECT is_demo FROM workspaces WHERE user_id = ?").bind(who.userId).first();
        return [True, {"userId": who.userId, "email": who.email, "workspaceId": ws, "isDemo": bool(row and row.is_demo), "via": who.via}];
    }
    return [False, None];
}


async def _function(request: any, env: any, name: str) -> any {
    if name == "health" {
        return _result({"ok": True, "service": "sherry-api", "time": now_iso()});
    }
    if request.method != "POST" {
        return _failure(405, "method_not_allowed", "Use POST.");
    }
    who = await authenticate(request, env);
    if who is None {
        return _failure(401, "unauthorized", "Sign in again, or check your Sherry API key.");
    }
    body: any = {};
    try {
        body = await request.json();
    } except Exception {
        body = {};
    }
    if not is_plain_object(body) {
        body = {};
    }
    try {
        ws = await ensure_workspace(env, who);
        outcome = await _dispatch(name, env, who, ws, body);
        if not outcome[0] {
            return _failure(404, "not_found", "Unknown function '" + name + "'.");
        }
        return _result(outcome[1]);
    } except Exception as err {
        e: any = err;
        if e.sherryReject {
            return _rejected(text_of(e.message));
        }
        console.error("sherry: " + name + " failed", e);
        return _failure(500, "internal", "Something went wrong on Sherry's side.");
    }
}


async def:pub handle(request: any, env: any, ctx: any) -> any {
    url: any = construct("URL", [request.url]);
    path = text_of(url.pathname);
    if request.method == "OPTIONS" {
        return construct("Response", [None, {"status": 204, "headers": CORS}]);
    }
    if path.startswith("/function/") {
        return await _function(request, env, path[len("/function/"):]);
    }
    # ---- MCP connector (claude.ai, ChatGPT, Gemini) and its OAuth ----
    if path == "/mcp" or path == "/mcp/" {
        caller = await mcp_caller(request, env);
        if caller is None {
            return unauthorized_mcp(request);
        }
        return await handle_mcp(request, env, caller);
    }
    if path.startswith("/.well-known/oauth-protected-resource") {
        return protected_resource_metadata(request);
    }
    if path.startswith("/.well-known/oauth-authorization-server") or path.startswith("/.well-known/openid-configuration") {
        return authorization_server_metadata(request);
    }
    if path == "/register" and request.method == "POST" {
        return await register_client(request, env);
    }
    if path == "/authorize" {
        if request.method == "POST" {
            return await authorize_submit(request, env);
        }
        return await authorize_start(request, env);
    }
    if path == "/token" and request.method == "POST" {
        return await token(request, env);
    }
    if path == "/revoke" and request.method == "POST" {
        return await revoke(request, env);
    }
    if env.ASSETS {
        return await env.ASSETS.fetch(request);
    }
    return _failure(404, "not_found", "Not found.");
}

# file: apps/extension/README.md
# Sherry browser extension (Jac)

A Chrome extension written in Jac. It captures **every message** of your
chats on chatgpt.com, claude.ai and gemini.google.com into your Sherry workspace, and keeps
**one summary memory per chat**, refreshed as the chat grows.

```
chatgpt.com / claude.ai / gemini.google.com page
  └─ content.js      reads the chat (src/lib/sites.cl.jac), sends new/changed messages
       └─ background.js   holds the API key, calls the Sherry API
            └─ Sherry (https://sherry.sherry-cloud.workers.dev): capture_conversation, summarize_conversation
```

## Build and load

```bash
cd apps/extension
../../.venv/bin/jac run build.jac      # -> dist/
```

1. Open `chrome://extensions`, turn on **Developer mode**, click **Load unpacked**,
   and pick `apps/extension/dist`.
2. Sign in at https://sherry.sherry-cloud.workers.dev. Open the account menu →
   **Connect apps and assistants** → **Create key**, and copy the key (`shr_…`, shown once).
3. Click the Sherry extension icon. The address is already filled in; paste the key,
   then click **Save & test**. It should say *Connected ✓*.
4. Open (or reload) a chat on chatgpt.com, claude.ai or gemini.google.com. The popup shows
   *N messages on this page*.

After changing any `.cl.jac` file, rebuild and click the reload icon on the
extension card in `chrome://extensions`. Then reload the chat tabs.

## How capture works

- A `MutationObserver` notices page changes, and capture runs 1.2 s after the
  page settles. A 5 s safety scan also runs, which catches switching between chats.
- Nothing is sent while the assistant is still typing.
- Only new or changed messages are sent. The server stores each message under a
  stable key (the site's message id, or position + role), so re-sends never
  duplicate anything.
- After 20 s without new messages, Sherry is asked to summarize the chat. It skips
  the summary if the transcript hasn't changed. **Summarize this chat now** in the
  popup forces one.
- **Summaries:** the server uses Claude (`claude-opus-5`) when `ANTHROPIC_API_KEY`
  is set on the Sherry Worker. Otherwise it writes a basic summary (first question,
  latest question, latest answer).
- **Deleting a chat's summary** in Sherry erases that chat's captured transcript,
  and the extension stops capturing it. Undo re-enables capture.
- **Pausing:** the popup can pause all capture or turn it off per site.

## Testing with the new accounts

Use the new test Gmail accounts on chatgpt.com, claude.ai and gemini.google.com, not personal ones.
For each site:

1. Start a chat, send a couple of messages, and wait for the reply to finish.
2. Open the popup:
   - *This page* should show the right message count.
   - *Last activity* should say *Captured N new message(s)*.
3. Click **Summarize this chat now**. The summary appears in the Sherry web app
   with a *via extension* badge. **Show captured chat** in its detail view shows
   the transcript.
4. Edit or regenerate a message and check the stored transcript updates.
5. Switch to another chat in the sidebar. It should be captured as a separate
   conversation.

**If the count is 0 on a chat that has messages**, the site has changed its page
structure. Fix the selectors at the top of [src/lib/sites.cl.jac](src/lib/sites.cl.jac).
To find the new ones, right-click a message → Inspect. Only that file is site-specific.

## Files

| File | What it does |
|---|---|
| `src/lib/sites.cl.jac` | Site adapters: chat id, title, streaming check, messages. **All selectors live here.** |
| `src/content.cl.jac` | Watches the page, sends changes, schedules summaries, answers the popup |
| `src/background.cl.jac` | Routes messages; the only part that calls the API |
| `src/lib/api.cl.jac` | `POST /function/<name>` client with clear error messages |
| `src/lib/ext.cl.jac` | Typed wrappers for `chrome.*` (storage, messaging) and settings |
| `src/popup.cl.jac` + `static/popup.html` | Settings, status, summarize button |
| `static/manifest.json` | Manifest V3 |
| `build.jac` | `jac jac2js` each file, then bundle with Bun into `dist/` |

## Known limitations

- **Live-site status:** the ChatGPT and Claude selectors are confirmed on the live
  sites. The Gemini ones (`user-query` / `model-response` / `message-content`) were
  written from Gemini's known markup and tested against mock pages only; verify them
  with the popup's message count first.
- claude.ai and Gemini expose no message ids. If an earlier message is deleted, later
  messages shift position, and some may be stored again under their new keys.
- Only chats with an id in the URL are captured. A brand-new ChatGPT chat is
  captured as soon as its URL changes to `/c/<id>`.
- A deployed (HTTPS) Sherry URL needs an extra host permission. The manifest lists
  it as optional, but the popup doesn't request it yet. `localhost` works out of the box.
- The API key is the Sherry account token. It can't be revoked separately (see `apps/web/README.md`).

