"""Board filters: project (persisted), assignee, category, tag, estimate,
hide-Done."""

import from ...models { Project, MemberView }
import from ..ui.select {
    Select,
    SelectTrigger,
    SelectValue,
    SelectContent,
    SelectItem
}
import from ..ui.button { Button }

def:pub FilterBar(
    projects: list[Project],
    members: list[MemberView],
    project: str,
    assignee: str,
    category: str,
    hideDone: bool,
    onProject: Callable[[str], None],
    onAssignee: Callable[[str], None],
    onCategory: Callable[[str], None],
    onHideDone: Callable[[], None],
    categories: list[str] = [],
    tags: list[str] = [],
    tag: str = "All",
    estimate: str = "All",
    onTag: Callable[[str], None] = None,
    onEstimate: Callable[[str], None] = None
) -> JsxElement {
    shownMembers = [
        m
        for m in members
        if project == "all" or project in m.project_ids
    ];
    return
        <div className="flex flex-wrap items-center gap-2">
            <Select value={project} onValueChange={onProject}>
                <SelectTrigger
                    className="h-8 w-44"
                    size="sm"
                    aria-label="Filter by project"
                >
                    <SelectValue placeholder="Project"/>
                </SelectTrigger>
                <SelectContent>
                    <SelectItem value="all">All projects</SelectItem>
                    {for p in projects {
                        <SelectItem key={jid(p)} value={jid(p)}>{p.name}</SelectItem>
                    }}
                </SelectContent>
            </Select>
            <Select value={assignee} onValueChange={onAssignee}>
                <SelectTrigger
                    className="h-8 w-40"
                    size="sm"
                    aria-label="Filter by assignee"
                >
                    <SelectValue placeholder="Assignee"/>
                </SelectTrigger>
                <SelectContent>
                    <SelectItem value="All">Everyone</SelectItem>
                    {for m in shownMembers {
                        <SelectItem key={m.id} value={m.id}>{m.name}</SelectItem>
                    }}
                </SelectContent>
            </Select>
            <Select value={category} onValueChange={onCategory}>
                <SelectTrigger
                    className="h-8 w-40"
                    size="sm"
                    aria-label="Filter by category"
                >
                    <SelectValue placeholder="Category"/>
                </SelectTrigger>
                <SelectContent>
                    <SelectItem value="All">All categories</SelectItem>
                    {for c in categories {
                        <SelectItem key={c} value={c}>{c}</SelectItem>
                    }}
                </SelectContent>
            </Select>
            {if len(tags) > 0 {
                <Select key="tag" value={tag} onValueChange={onTag}>
                    <SelectTrigger
                        className="h-8 w-36"
                        size="sm"
                        aria-label="Filter by tag"
                    >
                        <SelectValue placeholder="Tag"/>
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="All">All tags</SelectItem>
                        {for tg in tags {
                            <SelectItem key={tg} value={tg}>{tg}</SelectItem>
                        }}
                    </SelectContent>
                </Select>
            }}
            <Select value={estimate} onValueChange={onEstimate}>
                <SelectTrigger
                    className="h-8 w-36"
                    size="sm"
                    aria-label="Filter by estimate"
                >
                    <SelectValue placeholder="Estimate"/>
                </SelectTrigger>
                <SelectContent>
                    <SelectItem value="All">Any estimate</SelectItem>
                    <SelectItem value="yes">Estimated</SelectItem>
                    <SelectItem value="no">Unestimated</SelectItem>
                </SelectContent>
            </Select>
            <Button
                variant={"default" if hideDone else "outline"}
                size="sm"
                className="h-8"
                aria-pressed={hideDone}
                onClick={lambda { onHideDone(); }}
            >
                Hide Done
            </Button>
        </div>;
}

# file: components/board/GitHubChip.jac
"""GitHub state on a kanban card: the linked issue, its PR, and the nudge. A
merged PR *suggests* Done here; auto-done repos move the card server-side
on sync instead, from the same statuses (MERGE_SUGGEST_STATUSES)."""

import from ...models { TaskView }
import from ...constants { MERGE_SUGGEST_STATUSES }
import from ..ui.badge { Badge }
import from ..ui.button { Button }

# Merged and closed mean opposite things on GitHub, so they never share a
# tint. Anything unrecognised falls back to the neutral outline.
glob PR_TINT: dict[str, str] = {
         "open": "border-success/40 bg-success/10 text-success",
         "draft": "border-border bg-muted text-muted-foreground",
         "merged": "border-primary/40 bg-primary/10 text-primary",
         "closed": "border-destructive/40 bg-destructive/10 text-destructive"
     };

# Columns where "the PR merged" is news. A card already in Done or Backlog
# does not need telling.
def:pub GitHubChip(task: TaskView, onMarkDone: Callable[[str], None]) -> JsxElement {
    issueTint = (
        "border-border bg-muted/60 text-muted-foreground line-through"
            if task.gh_issue_state == "closed"
            else "border-border bg-card text-foreground hover:bg-accent"
    );
    prLabel = "PR " + task.pr_state;
    prTitle = (
        (task.gh_repo + " #" + str(task.pr_number)) if task.pr_number > 0 else prLabel
    );
    suggestDone = task.pr_state == "merged" and task.status in MERGE_SUGGEST_STATUSES;

    return
        <div className="space-y-1.5">
            <div className="flex flex-wrap items-center gap-1">
                {if task.gh_issue_number > 0 {
                    <a
                        key="issue"
                        href={task.issue_link}
                        target="_blank"
                        rel="noreferrer"
                        title={task.gh_repo + " #" + str(task.gh_issue_number)}
                        # The card itself opens the task dialog on click.
                        onClick={lambda (e: MouseEvent) { e.stopPropagation(); }}
                        className={"inline-flex h-5 items-center rounded-full border px-2 text-xs font-medium transition-colors "
                            + issueTint}
                    >
                        {"#" + str(task.gh_issue_number)}
                    </a>
                }}
                {if task.pr_state {
                    <Badge
                        key="pr"
                        variant="outline"
                        title={prTitle}
                        className={PR_TINT.get(
                            task.pr_state, "border-border bg-card text-muted-foreground"
                        )
                            + " h-5 rounded-full"}
                    >
                        {prLabel}
                    </Badge>
                }}
                {if task.gh_sub_total > 0 {
                    <Badge
                        key="family"
                        variant="outline"
                        title={"Sub-issues: "
                            + str(task.gh_sub_done)
                            + " of "
                            + str(task.gh_sub_total)
                            + " done"}
                        className={(
                            "border-success/40 bg-success/10 text-success"
                                if task.gh_sub_done == task.gh_sub_total
                                else "border-primary/40 bg-primary/10 text-primary"
                        )
                            + " h-5 rounded-full tabular-nums"}
                    >
                        {"⌗ " + str(task.gh_sub_done) + "/" + str(task.gh_sub_total)}
                    </Badge>
                }}
                {if task.gh_parent_number > 0 {
                    <Badge
                        key="parent"
                        variant="outline"
                        title={"Part of "
                            + task.gh_parent_repo
                            + " #"
                            + str(task.gh_parent_number)}
                        className="h-5 rounded-full border-border bg-card text-muted-foreground"
                    >
                        {"↳ #" + str(task.gh_parent_number)}
                    </Badge>
                }}
            </div>
            {if suggestDone {
                <div
                    key="suggest"
                    className="flex items-center justify-between gap-2 rounded-md border border-primary/30 bg-primary/5 px-2 py-1 text-xs"
                >
                    <span className="text-muted-foreground">PR merged.</span>
                    <Button
                        variant="ghost"
                        size="xs"
                        onClick={lambda (e: MouseEvent) {
                            e.stopPropagation();
                            onMarkDone(task.id);
                        }}
                    >
                        Mark done
                    </Button>
                </div>
            }}
        </div>;
}

