def:pub update_event(
    event_id: str,
    year: int, month: int, day: int, hour: int, minute: int,
    title: str, description: str,
    work_min: int, break_min: int, cycles: int
) -> Event | None {
    for e in [root-->][?:Event] {
        if jid(e) == event_id {
            e.year = year;
            e.month = month;
            e.day = day;
            e.hour = hour;
            e.minute = minute;
            e.title = title;
            e.description = description;
            e.work_min = work_min;
            e.break_min = break_min;
            e.cycles = cycles;
            return e;
        }
    }
    return None;
}


