        == "Sun, Sep 27 · 1:00 PM – 4:00 PM";
    assert when_label("2026-09-27", "2026-10-11", "7:00 AM", "")
        == "Sun, Sep 27 – Oct 11";
    assert when_label("2026-10-02", "", "", "") == "Fri, Oct 2";
    assert when_label("soon", "", "7:00 PM", "") == "soon 7:00 PM";
}

