/* This file is the CSS entry (imported by main.jac). It pulls in the
   generated theme first, so Tailwind sees both sets of tokens in one pass. */
@import "./global.css";

/*
  Trace design tokens.

  HOW THEMING WORKS
  - styles/global.css (generated by `jac retheme`) defines the base shadcn
    tokens: --background, --foreground, --card, --primary, --secondary,
    --accent, --muted, --border, --destructive ... for :root (light) and .dark.
  - This file adds Trace-specific tokens the same way: one value under :root
    (light) and one under .dark. It is a separate file so `jac retheme` never
    overwrites it.
  - The app starts in light mode. The header toggle turns dark mode on by adding
    the `dark` class to <html> (see components/TraceDashboard.jac). No component
    needs to change.

  RULE: components use token classes only (bg-card, text-status-safe,
  font-display...). Never raw colours like bg-zinc-900 or text-red-500.
*/

:root {
  /* Status colours for claim types */
  --status-missing: oklch(0.58 0.21 25);
  --status-missing-soft: oklch(0.58 0.21 25 / 0.12);
  --status-safe: oklch(0.55 0.14 155);
  --status-safe-soft: oklch(0.55 0.14 155 / 0.12);
  --status-warning: oklch(0.66 0.15 70);
