"""studio - unit tests for the metrics.sv.jac parsers.

Pure-logic coverage for the training/eval artifact parsers that feed the Train
HISTORY / MONITOR views. Each test writes a fixture into an isolated temp dir and
asserts the parsed shape, so nothing here touches the real data_root or a server.

Annex file: pairs with metrics.sv.jac and sees its private `def`s directly.
Run with `jac test metrics.sv.jac`.
"""

import tempfile;
import from pathlib { Path }

"""Write `text` to a fresh temp file and return its Path (auto-cleaned by the OS)."""
def _tmpfile(text: str, suffix: str = ".log") -> Path {
    d = tempfile.mkdtemp(prefix="studio-metrics-");
    p = Path(d) / f"fixture{suffix}";
    p.write_text(text);
    return p;
}

test "parse_train_log reads mlx SFT format" {
    log = (
        "Iter 1: Train loss 2.500, Learning Rate 1.0e-5, Tokens/sec 120.0\n"
        "Iter 2: Val loss 2.100\n"
        "Iter 2: Train loss 2.000, Learning Rate 1.0e-5, Tokens/sec 130.0\n"
    );
    r = parse_train_log(_tmpfile(log));
    # Series values come back as `any` out of the dict; bind typed lists so the
    # checker (and len/index) are happy while asserting the same shape.
    train: list = list(r["train"]);
    val: list = list(r["val"]);
    tps: list = list(r["tps"]);
    lr: list = list(r["lr"]);
    assert r["last_iter"] == 2, r;
    assert len(train) == 2, train;
    assert train[0] == {"x": 1, "y": 2.5}, train[0];
    assert len(val) == 1, val;
    assert val[0]["y"] == 2.1, val;
    assert len(tps) == 2, tps;
    assert len(lr) == 2, lr;
}

test "parse_train_log reads DPO ': loss' format" {
    log = "Iter 10: loss 0.693, lr 5.0e-6, tok/s 88.0\n";
    r = parse_train_log(_tmpfile(log));
    train: list = list(r["train"]);
    lr: list = list(r["lr"]);
    tps: list = list(r["tps"]);
    assert r["last_iter"] == 10, r;
    assert train[0] == {"x": 10, "y": 0.693}, train;
    assert lr[0]["y"] == 5.0e-6, lr;
    assert tps[0]["y"] == 88.0, tps;
}

test "parse_train_log skips lines without an Iter marker" {
    log = "Starting training...\nrandom noise\nIter 3: Train loss 1.0\n";
    r = parse_train_log(_tmpfile(log));
    train: list = list(r["train"]);
    assert r["last_iter"] == 3, r;
    assert len(train) == 1, train;
}

test "parse_train_log returns empty shape for a missing file" {
    r = parse_train_log(Path("/nonexistent/does-not-exist.log"));
    assert r == {"train": [], "val": [], "lr": [], "tps": [], "last_iter": 0}, r;
}

test "read_series pulls x/y pairs and skips malformed rows" {
    body = (
        '{"step": 0, "acc": 0.10}\n'
        'not json at all\n'
        '{"step": 1, "acc": 0.55}\n'
        '{"step": 2}\n'                 # missing ykey → skipped
        '{"step": 3, "acc": 0.90}\n'
    );
    series = read_series(_tmpfile(body, ".jsonl"), "acc");
    assert len(series) == 3, series;
    assert series[0] == {"x": 0, "y": 0.10}, series[0];
    assert series[2] == {"x": 3, "y": 0.90}, series[2];
}

test "read_series is empty for a missing file" {
    assert read_series(Path("/nope/missing.jsonl"), "acc") == [];
}

test "last_row returns the final parseable object" {
    body = '{"step": 0, "v": 1}\n{"step": 1, "v": 2}\nbroken\n{"step": 2, "v": 3}\n';
    r = last_row(_tmpfile(body, ".jsonl"));
    assert r["step"] == 2 and r["v"] == 3, r;
}

test "last_row is empty for a file with no JSON objects" {
    assert last_row(_tmpfile("just\nsome\ntext\n")) == {};
}

test "tail returns the last n lines" {
    body = "\n".join([str(i) for i in range(100)]);
    out = tail(_tmpfile(body), 5);
    assert out == "95\n96\n97\n98\n99", out;
}

test "tail is empty for a missing file" {
    assert tail(Path("/nope/missing.log")) == "";
}

test "last_iter finds the maximum Iter across the file" {
    body = "Iter 5\nIter 42\nIter 7\n";
    assert last_iter(_tmpfile(body)) == 42;
    assert last_iter(Path("/nope/missing.log")) == 0;
}

test "merge_by_x overlays per-run series and sorts by x" {
    by_run = {
        "runA": [{"x": 0, "y": 1.0}, {"x": 2, "y": 3.0}],
        "runB": [{"x": 0, "y": 9.0}, {"x": 1, "y": 8.0}]
    };
    rows = merge_by_x(by_run);
    assert len(rows) == 3, rows;
    assert rows[0] == {"x": 0, "runA": 1.0, "runB": 9.0}, rows[0];
    assert rows[1] == {"x": 1, "runB": 8.0}, rows[1];
    assert rows[2] == {"x": 2, "runA": 3.0}, rows[2];
}

test "stages lists only completed stage markers in canonical order" {
    d = Path(tempfile.mkdtemp(prefix="studio-stages-"));
    (d / ".base.done").write_text("");
    (d / ".train.done").write_text("");
    (d / ".finetuned.done").write_text("");
    found = stages(d);
    assert found == ["base", "train", "finetuned"], found;
    assert stages(Path("/nope/missing")) == [];
}

test "idiom_summary picks the row carrying avg_sim" {
    d = Path(tempfile.mkdtemp(prefix="studio-idiom-"));
    (d / "idiom-metrics.jsonl").write_text(
        '{"step": 0}\n{"step": 1, "avg_sim": 0.82, "idiomatic": 4}\n'
    );
    row = idiom_summary(d, "sft", "function");
    assert row["avg_sim"] == 0.82, row;
    assert row["idiomatic"] == 4, row;
    # Nothing on disk for the graph kind → empty dict.
    assert idiom_summary(d, "sft", "graph") == {}, "expected empty for missing graph metrics";
}

# file: models.sv.jac
"""studio - model registry + data-root resolution.

Ports server/config.py. models/ is gitignored and resolves against
paths.data_root() (JAC_STUDIO_DATA_ROOT / workspace). `list_models` is the
client-facing endpoint; the rest are helpers used by chat/eval/train modules.
"""

import os;
import inference;
import paths;
import workspace;
import from pathlib { Path }

# Model registry, eval holdouts, and excluded run dirs now live in
# studio.workspace.toml (workspace_root > studio_root). See workspace.sv.jac.

"""One model as the client sees it: registry entry + on-disk availability."""
obj ModelView {
    has id: str = "",
        label: str = "",
        path: str = "",
        available: bool = False,
        size_gb: float = 0.0;
}

def data_root() -> Path {
    return paths.data_root();
}

def model_by_id(model_id: str) -> dict {
    for m in workspace.model_registry() {
        if m["id"] == model_id {
            return m;
        }
    }
    return {};
}

def model_path(m: dict) -> Path {
    return data_root() / str(m["path"]);
}

def model_available(m: dict) -> bool {
    return model_path(m).is_dir();
}

def results_dir() -> Path {
    # run_probe.sh / run_dpo.sh cd to the repo root and write under
    # model-experiments/01-sft-dpo/results/, so the studio must read the same tree.
    return data_root() / "model-experiments/01-sft-dpo" / "results";
}

def jac_bin() -> Path {
    return data_root() / ".venv" / "bin" / "jac";
}

# Memoized model-dir sizes. `list_models()` backs the chat model picker AND
# jms_llm.llm_status AND assistant.assistant_providers — all UI-polled — and each
# call used to rglob + stat every file in every multi-GB model dir. Key = the model
# directory's own absolute path + st_mtime_ns, as specified. Model dirs are
# immutable downloads: files land, the dir mtime bumps, and nothing touches them
# again. CAVEAT: a directory's mtime only tracks its DIRECT entries, so rewriting
# an existing nested file in place (without adding/removing a direct child) would
# not invalidate this entry. That does not happen for a downloaded model snapshot;
# if it ever does, restart the server.
glob _SIZE_CACHE: dict[str, float] = {};
glob _SIZE_CAP: int = 128;

"""On-disk size of a model dir in GB (2 dp), memoized on (dir path, dir mtime_ns).
round(x,2) is broken in the checker, so the cents are computed with int division."""
def dir_size_gb(p: Path) -> float {
    if not p.is_dir() { return 0.0; }
    key = "";
    try {
        key = str(p) + "|" + str(p.stat().st_mtime_ns);
    } except Exception { key = ""; }
    if key {
        hit = _SIZE_CACHE.get(key);
        if hit is not None { return float(hit); }
    }
    total = 0;
    for f in p.rglob("*") {
        if f.is_file() { total += f.stat().st_size; }
    }
    gb = int(total / 10_000_000) / 100.0;
    if key {
        if len(_SIZE_CACHE) > _SIZE_CAP { _SIZE_CACHE.clear(); }
        _SIZE_CACHE[key] = gb;
    }
    return gb;
}

def total_ram_gb() -> int {
    return round(os.sysconf("SC_PHYS_PAGES") * os.sysconf("SC_PAGE_SIZE") / 1024 ** 3);
}

"""Total system RAM in GB — the sidebar memory gauge."""
def system_ram() -> int {
    return total_ram_gb();
}

"""The model registry with live on-disk availability + size — the chat model picker."""
def list_models() -> list[ModelView] {
    out: list[ModelView] = [];
    for m in workspace.model_registry() {
        avail = model_available(m);
        out.append(
            ModelView(
                id=str(m["id"]),
                label=str(m["label"]),
                path=str(m["path"]),
                available=avail,
                size_gb=dir_size_gb(model_path(m)) if avail else 0.0
            )
        );
    }
    return out;
}

"""The currently-resident model plus process fd health:
{id, resident_gb, fd_boot_limit, fd_soft, fd_hard, fd_target, fd_guard}. Drives the
model-pill LOADED badge and the sidebar MEM gauge. Empty id + 0.0 when nothing
is loaded.

The fd_* keys expose the open-file ceiling this process actually achieved at
boot (see inference._fd_info) so the fd-exhaustion fix is verifiable from the
API instead of needing `lsof` on the live pid. Additive only — id/resident_gb
are unchanged for existing callers."""
def loaded_model() -> dict {
    return inference.loaded_info();
}

"""Eagerly load (warm) a model so the next completion streams immediately. Blocks
until resident; the client shows elapsed via its own timer. Returns
{id, load_s, error} — error is "" on success, a message otherwise."""
def warm_model(model_id: str) -> dict {
    m = model_by_id(model_id);
    if not m {
        return {"id": model_id, "load_s": 0.0, "error": f"unknown model_id: {model_id}"};
    }
    if not model_available(m) {
        return {"id": model_id, "load_s": 0.0, "error": f"model not found on disk: {model_id}"};
    }
    # load_sync raises on a genuinely failed load (e.g. OSError [Errno 24] Too
    # many open files) and on model-lock timeout. Honour this function's stated
    # {id, load_s, error} contract instead of letting it escape as a 500 — a
    # failed warm must degrade to an error message for THIS request only.
    try {
        s = inference.load_sync(model_id, str(model_path(m)));
    } except Exception as e {
        return {"id": model_id, "load_s": 0.0, "error": str(e)};
    }
    return {"id": model_id, "load_s": s, "error": ""};
}

