                            <button onClick={lambda (e: MouseEvent) { open_item(n); }}>
                                <span className={"bell-icon " + n.kind}><Icon name={"chat" if n.kind == "message" else ("pin" if n.kind == "relay" else "spark")} size={16} /></span>
                                <span>
