  background: var(--scrollbar);
  border-radius: 4px;
  border: none;
}
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

@keyframes mono-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}
.pulse { animation: mono-pulse 1.6s ease-in-out infinite; }

/* syntax colors are tokens (theme.css) so light mode gets a legible dark set */
.tok-kw { color: var(--tok-kw); font-weight: 600; }
.tok-type { color: var(--tok-type); }
.tok-bi { color: var(--tok-bi); }
.tok-str { color: var(--tok-str); font-style: italic; }
.tok-num { color: var(--tok-num); }
.tok-com { color: var(--tok-com); }

/* Per-workspace accent (nav tile dots + active-bars only; interiors stay
   monochrome). --ws0N / --ws-accent / [data-ws] mapping all live in
   theme.css now — this file only owns the .tok-* syntax colors above. */

/* ---- page-load choreography (Distinctive §3) ---- */
.reveal { opacity: 0; animation: fadeInUp var(--dur-base) var(--ease-out) forwards; }
.stagger-1{animation-delay:.05s} .stagger-2{animation-delay:.10s} .stagger-3{animation-delay:.15s}
.stagger-4{animation-delay:.20s} .stagger-5{animation-delay:.25s} .stagger-6{animation-delay:.30s}
@keyframes fadeInUp { from{opacity:0;transform:translateY(24px)} to{opacity:1;transform:none} }
.reveal-scale { opacity:0; animation: scaleIn var(--dur-base) var(--ease-out) forwards; }
@keyframes scaleIn { from{opacity:0;transform:scale(.94)} to{opacity:1;transform:none} }
/* Reduced motion previously covered only .reveal/.reveal-scale, leaving the
   infinite .pulse loop (status glyphs, empty states), Tailwind's animate-pulse and
   every hover lift still moving — exactly what the query exists to stop. */
.reveal-fade { opacity:0; animation: fadeIn var(--dur-fast) var(--ease-out) forwards; }
@keyframes fadeIn { from{opacity:0} to{opacity:1} }

/* Keyboard focus ring. The app had NO :focus-visible rule at all, and .exp-input
   sets outline:none with no replacement — invisible focus. Now that the landing
   panels and the four dialogs are genuinely keyboard-reachable, this is the other
   half of that fix. :focus-visible only shows for keyboard users, not mouse. */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: calc(var(--radius) * 0.4);
}
.exp-input:focus-visible, .jms-input:focus-visible, .jms-textarea:focus-visible { outline: none; }

@media (prefers-reduced-motion: reduce) {
  .reveal,.reveal-scale,.reveal-fade{animation:none;opacity:1;transform:none}
  .pulse,.animate-pulse,.animate-in{animation:none}
  .exp-hoverable:hover,.jms-card:hover,.jms-hero-panel:hover,
  .exp-btn:hover,.jms-btn:hover{transform:none}
  *,*::before,*::after{transition-duration:1ms!important;scroll-behavior:auto!important}
}

/* Floating panel label. Was written inline 51x as
   `micro-label absolute -top-2 left-3 bg-background px-2` — an OPAQUE --bg chip
   sitting on a translucent glass panel, so it never matched the surface under it
   and read as a flat patch. .jms-section-label already solved this; this is the
   same fix, available to both surfaces. */
.panel-tab {
  position: absolute; top: -8px; left: 12px; padding: 0 8px;
  background: var(--surface-strong);
  backdrop-filter: var(--blur); -webkit-backdrop-filter: var(--blur);
  border-radius: 999px;
}

# file: hooks/useConfirmReset.cl.jac
"""useConfirmReset — auto-disarms the app's two-click "SURE?" destructive confirms.

The two-click pattern (first click arms the button and flips its label to
"SURE?", second click actually deletes) lives in JmsProjects (project DELETE),
Evals (eval-history DEL) and WorkspaceSettings (workspace DELETE + section ✕).
Armed state used to be sticky: nothing but a second click cleared it, so a
button could sit armed indefinitely and a stray click on the same screen
position minutes later silently deleted a project / eval / workspace. Nothing in
this app is recoverable, so that was a data-loss bug, not a cosmetic one.

This hook is the single disarm mechanism for all of them. Call it once per
confirm state var, UNCONDITIONALLY (it wraps a `useEffect`, so it must sit above
any early `return` in the component), passing:

  * `armed` — the confirm state as a string. "" means nothing is armed. Passing
    the id (not a bool) means re-arming on a DIFFERENT row re-fires the effect
    and restarts that row's timer.
  * `reset` — a nullary callback that clears the confirm var.
  * `ms`    — timeout backstop, default 4s.

Three ways it disarms, all with the same `reset`:

  1. Escape — a document keydown, matching the Escape-closes-a-dialog wiring in
     Shortcuts.cl.jac / WorkspaceSettings.cl.jac. Deliberately does NOT
     stopPropagation: in a drawer, Escape disarming the button and closing the
     drawer are both correct.
  2. Pointer-down anywhere that is not inside the armed button. The armed button
     must carry `data-confirm-armed` (see CONFIRM_ARMED_SEL) for the hit test.
     `mousedown`, not `click`, on purpose: mousedown lands BEFORE React's click
     handler re-renders the row, so the attribute is still in the DOM when the
     second (confirming) click starts and the hit test correctly skips it.
  3. A 4s timeout, re-armed from scratch every time `armed` changes and cleared
     in the effect cleanup — same effect-local-timer-id shape as Toast's
     auto-dismiss, so nothing leaks across re-renders or unmount.
"""

import from react { useEffect }

"""The armed button must render `data-confirm-armed={"1" if armed else None}`
(React drops the attribute for a None value), which is what this selector finds."""
glob:pub CONFIRM_ARMED_SEL: str = "[data-confirm-armed]";

def:pub useConfirmReset(armed: str, reset: any, ms: float = 4000.0) {
    useEffect(lambda {
        if not armed or reset is None { return lambda { }; }
        doc: any = document;
        onKey = lambda(e: any) {
            if str(e.key) == "Escape" { reset(); }
        };
        onDown = lambda(e: any) {
            # Structural guard, not a try/except: a JS TypeError from a target
            # with no .closest is NOT a Jac Exception, so `except Exception`
            # would rethrow it and leave the button armed — the exact failure
            # this hook exists to prevent. No `closest` ⇒ treat as outside.
            t: any = e.target;
            inside: any = t.closest(CONFIRM_ARMED_SEL) if (t and t.closest) else None;
            if not inside { reset(); }
        };
        doc.addEventListener("keydown", onKey);
        doc.addEventListener("mousedown", onDown);
        tid: any = setTimeout(lambda { reset(); }, ms);
        return lambda {
            doc.removeEventListener("keydown", onKey);
            doc.removeEventListener("mousedown", onDown);
            clearTimeout(float(str(tid)));
        };
    }, [armed]);
}

# file: hooks/useFocusTrap.cl.jac
"""useFocusTrap — keeps Tab / Shift-Tab inside an open dialog or drawer.

Every overlay in this app (WorkspaceSettings, AssistantPanel, CommandPalette,
ShortcutSheet, ApiKeyModal) already ran the same `useEffect` on `open`: add a
document Escape listener, move focus onto the panel, and restore focus to the
previously-focused element in the cleanup. The one thing all five explicitly
gave up on — five separate `# ponytail: no focus trap` notes — was Tab: focus
walked straight out of the panel and into the page behind it, which is dead
scenery while `aria-modal="true"` is up. This hook is that missing piece, and
ONLY that piece:

  * initial focus (a) and focus restore (c) stay where they already work, in
    each component's existing Escape effect. Duplicating them here would be
    actively wrong for (c): effects run in declaration order, so a second
    `prev = document.activeElement` captured after the panel already focused
    itself would "restore" focus to the panel that is being unmounted.
  * this hook is therefore side-effect-only and returns nothing, matching the
    shape of hooks/useConfirmReset.

Call it UNCONDITIONALLY (it wraps a `useEffect`, so it must sit above any early
`return` in the component) and AFTER the component's own open-effect, so that
by the time the safety net below runs, the panel has already focused itself:

    panelRef: any = useRef(None);
    ...
    useFocusTrap(panelRef, open);      # after the Escape useEffect
    ...
    <aside ref={panelRef} role="dialog" aria-modal="true" tabIndex={-1}>

`panelRef` is a React ref to the dialog container, read at EVENT time (never
captured into the closure), so a re-render that swaps the node cannot leave the
trap pointing at a detached element.

Wrapping rules, given `items` = the panel's focusable descendants in DOM order:
  * Shift-Tab on the first item  -> last item.
  * Tab on the last item         -> first item.
  * either, while the container itself holds focus (it is `tabIndex={-1}`, so it
    IS the active element right after open) -> last / first. Without this case
    the very first Shift-Tab after opening a drawer escaped it, which is the
    exact bug being fixed.
  * no focusable descendants at all -> park focus on the container.

Stacked overlays: the ⌘K palette can open over the assistant drawer, so two
traps can be listening at once. A trap whose panel does not hold focus stands
down IF something else with `role="dialog"` does — otherwise the lower dialog
would yank focus out of the one on top. It only pulls focus back when focus is
loose in the page (e.g. a scrim click left it on <body>).
"""

import from react { useEffect }

"""Focusable descendants, in DOM order. `:not([disabled])` mirrors the guard
buttons across the app rely on, and `[tabindex='-1']` is excluded so the dialog
container itself never counts as one of its own stops."""
glob:pub FOCUSABLE_SEL: str =
    "a[href], area[href], button:not([disabled]), input:not([disabled]):not([type='hidden']), "
    + "select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex='-1']), "
    + "[contenteditable='true'], audio[controls], video[controls], details > summary";

def:pub useFocusTrap(panelRef: any, open: bool) {
    useEffect(lambda {
        if not open or panelRef is None { return lambda { }; }
        doc: any = document;
        onKey = lambda(e: any) {
            if str(e.key) != "Tab" { return; }
            panel: any = panelRef.current;
            if not panel { return; }
            cur: any = doc.activeElement;
            inside: bool = bool(cur and panel.contains(cur));
            # Structural guard, not a try/except (a JS TypeError is not a Jac
            # Exception): a target with no `.closest` is treated as "not in a
            # dialog", i.e. loose focus we are allowed to reclaim.
            other: any = cur.closest('[role="dialog"]') if (cur and cur.closest) else None;
            if not inside and other { return; }

            items: list[any] = list(panel.querySelectorAll(FOCUSABLE_SEL));
            if len(items) == 0 {
                e.preventDefault();
                panel.focus();
                return;
            }
            first: any = items[0];
            last: any = items[len(items) - 1];
            back: bool = bool(e.shiftKey);

            # Focus loose in the page, or parked on the container itself: pull it
            # to the edge the user is tabbing toward.
            if not inside or cur == panel {
                e.preventDefault();
                if back { last.focus(); } else { first.focus(); }
                return;
            }
            if back and cur == first {
                e.preventDefault();
                last.focus();
            } elif (not back) and cur == last {
                e.preventDefault();
                first.focus();
            }
        };
        doc.addEventListener("keydown", onKey);
        return lambda {
            doc.removeEventListener("keydown", onKey);
        };
    }, [open]);
}

