def _my_root_id() -> str {
    return jid(root);
}

# The caller's profile node, created on first use.
def _me() -> User {
    for u in [root-->][?:User] {
        return u;
    }
    user = User(
        handle_number=random.randint(100, 999), completed_connections=0, trust_score=80,
        member_since=datetime.datetime.now().strftime("%B %Y")
    );
    root ++> user;
    return user;
}

# Friendly anonymous name ("Maple Fox"), stable per user and the same whether
# they ride or drive. Hides identity without sounding like a ticket number.
glob HANDLE_WORDS_A: list[str] = [
    "Maple", "Cedar", "River", "Harbor", "Lake", "Birch", "Willow", "Aspen",
    "Pine", "Meadow", "Prairie", "Summit", "Canyon", "Coral", "Amber", "Ivory",
