def nominatim_geocode(
    query: str,
    on_ok: Callable[[dict], None],
    on_err: Callable[[str], None]
) {
    w: any = window;
    q = query.strip();
    low = q.lower();
    if "ann arbor" not in low and "michigan" not in low and ", mi" not in low {
        q = q + ", Ann Arbor, MI, USA";
    }
    url = (
        "https://nominatim.openstreetmap.org/search?format=json&limit=1&q="
        + w.encodeURIComponent(q)
    );
    ok_cb = on_ok;
    err_cb = on_err;
    fetch(
        url,
        {
            "headers": {
                "Accept": "application/json"
            }
        }
    ).then(
        lambda (resp: any) {
            if not resp.ok {
                err_cb("Could not look up that address.");
                return None;
            }
            return resp.json();
        }
    ).then(
        lambda (data: any) {
            if not data {
                return;
            }
            if len(data) > 0 {
                row: any = data[0];
                ok_cb(
                    {
                        "lat": float(row["lat"]),
                        "lng": float(row["lon"]),
                        "label": row["display_name"]
                    }
                );
            } else {
                err_cb("No places match that search.");
            }
        }
    ).catch(
        lambda (e: any) {
            err_cb("Could not look up that address.");
        }
    );
}

def split_place_label(display: str) -> dict {
    parts = display.split(",");
    if len(parts) == 0 {
        return {"title": display, "sub": ""};
    }
    title = parts[0].strip();
    rest: list[str] = [];
    i = 1;
    while i < len(parts) and len(rest) < 3 {
        bit = parts[i].strip();
        if bit {
            rest.append(bit);
        }
        i += 1;
    }
    return {"title": title, "sub": ", ".join(rest)};
}

def:pub suggest_places(
    query: str,
    on_ok: Callable[[list[dict]], None]
) {
    w: any = window;
    q = query.strip();
    ok_cb = on_ok;
    if len(q) < 2 {
        ok_cb([]);
        return;
    }
    low = q.lower();
    bias = q;
    if "ann arbor" not in low and "michigan" not in low and ", mi" not in low {
        bias = q + ", Ann Arbor, MI";
    }
    # viewbox roughly covers Ann Arbor metro (left, top, right, bottom).
    url = (
        "https://nominatim.openstreetmap.org/search?format=json&addressdetails=0"
        + "&limit=3&countrycodes=us"
        + "&viewbox=-83.90,42.36,-83.62,42.20&bounded=0&q="
        + w.encodeURIComponent(bias)
    );
    fetch(
        url,
        {
            "headers": {
                "Accept": "application/json"
            }
        }
    ).then(
        lambda (resp: any) {
            if not resp.ok {
                return [];
            }
            return resp.json();
        }
    ).then(
        lambda (data: any) {
            out: list[dict] = [];
            if not data {
                ok_cb(out);
                return;
            }
            for row in data {
                if len(out) >= 3 {
                    break;
                }
                display = str(row["display_name"]);
                bits = split_place_label(display);
                out.append(
                    {
                        "id": str(row["place_id"]),
                        "title": bits["title"],
                        "sub": bits["sub"],
                        "label": display,
                        "lat": float(row["lat"]),
                        "lng": float(row["lon"])
                    }
                );
            }
            ok_cb(out);
        }
    ).catch(
        lambda (e: any) {
            ok_cb([]);
        }
    );
}

